-- Chemistry 12 (PECTAA, Punjab) textbook MCQs, chapter 17 (Group 2 Elements) CHE-0713 to CHE-0747, chapter 18 (Transition Metals) CHE-0748 to CHE-0784, chapter 19 (Basics of Organic Chemistry) CHE-0785 to CHE-0819, chapter 20 (Aromatic Hydrocarbons) CHE-0820 to CHE-0848, chapter 21 (Halogenoalkanes) CHE-0849 to CHE-0873, chapter 22 (Hydroxy Compounds) CHE-0874 to CHE-0897, chapter 23 (Carbonyl Compounds and Carboxylic Acids) CHE-0898 to CHE-0932, chapter 24 (Organic Nitrogen Compounds) CHE-0933 to CHE-0968, chapter 25 (Organic Synthesis) CHE-0969 to CHE-0991, chapter 26 (Polymers) CHE-0992 to CHE-1020, chapter 27 (Biochemistry) CHE-1021 to CHE-1060, chapter 28 (Chromatography) CHE-1061 to CHE-1082, chapter 29 (Spectroscopy-1) CHE-1083 to CHE-1114, chapter 30 (Spectroscopy-2 (NMR)) CHE-1115 to CHE-1140, chapter 31 (Materials and Energy) CHE-1141 to CHE-1174, chapter 32 (Medicine, Agriculture and Industry) CHE-1175 to CHE-1211, chapter 33 (Water) CHE-1212 to CHE-1242.
-- Original questions in the bank's template (stem, four options, key, why the key is right, why each other option is
-- wrong) with the source page in the textbook. Approved for the bank by the site owner, so they go straight to live.
-- Each question's own chapter is its MDCAT chapter (NUMS and AKU reuse it); FSc Part 2 lists them in bank_questions
-- under the textbook chapter. Not in the free set. INSERT OR IGNORE keeps the file safe to run twice; if the site
-- owner's admin account doesn't exist (a fresh local database) nothing is inserted.

-- Inserted in batches of 20 to stay under D1's statement size limit.

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0713', 's-block elements', 'Properties and trends', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 2 (§17.1)', 'Group 2 elements show similar chemical properties mainly because they all have', '["a completely filled d subshell.", "two electrons in their outermost s subshell (ns²).", "seven valence electrons.", "the same atomic radius."]', 1, 'All Group 2 atoms have the outer configuration ns², so they lose two electrons to form M²⁺ ions and react in similar ways.', '{"0": "Group 2 elements are s-block elements; their chemistry is set by the ns² electrons.", "2": "Seven valence electrons belong to the halogens (Group 17).", "3": "Atomic radius rises steadily from Be (112 pm) to Ba (222 pm)."}'),
  ('CHE-0714', 's-block elements', 'Properties and trends', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 2 (Table 17.1)', 'The electron configuration of strontium is', '["[Kr] 5s²", "[Xe] 6s²", "[Ar] 4s²", "[Kr] 4d¹⁰ 5s²"]', 0, 'Strontium (atomic number 38) follows krypton and has two electrons in 5s: [Kr] 5s².', '{"1": "[Xe] 6s² is barium.", "2": "[Ar] 4s² is calcium.", "3": "Strontium has no 4d electrons; 38 = 36 + 2."}'),
  ('CHE-0715', 's-block elements', 'Properties and trends', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 2–3 (§17.1.1)', 'The reactivity of Group 2 elements increases from Be to Ba because, down the group,', '["ionization energy increases.", "electronegativity increases.", "atomic size and shielding increase, so ionization energy decreases.", "the number of valence electrons increases."]', 2, 'Larger atoms with more shielding hold their two outer electrons less tightly, so less energy is needed to form M²⁺ and reactivity rises: Be < Mg < Ca < Sr < Ba.', '{"0": "Ionization energy falls down the group (first IE: Be 900, Ba 503 kJ mol⁻¹).", "1": "Electronegativity falls from 1.5 (Be) to 0.9 (Ba).", "3": "Every Group 2 element has two valence electrons."}'),
  ('CHE-0716', 's-block elements', 'Properties and trends', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 2 (Table 17.1)', 'Using Table 17.1, which Group 2 metal has the lowest melting point?', '["Beryllium (1287 °C)", "Calcium (842 °C)", "Barium (727 °C)", "Magnesium (650 °C)"]', 3, 'Magnesium melts at 650 °C, the lowest in the table. Melting points do not fall smoothly down the group; the book links this to different packing of the metal atoms.', '{"0": "Beryllium has the highest melting point, 1287 °C.", "1": "Calcium melts at 842 °C, above magnesium.", "2": "Barium melts at 727 °C, above magnesium."}'),
  ('CHE-0717', 's-block elements', 'Properties and trends', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 2 (Table 17.1)', 'The standard electrode potentials of Group 2 metals become more negative from Mg (−2.34 V) to Ba (−2.91 V). This shows that', '["Ba²⁺ is the easiest ion to reduce to the metal.", "Mg loses electrons more easily than Ba.", "Ba is the strongest reducing agent of these metals.", "reactivity decreases down the group."]', 2, 'A more negative E° means a greater tendency for the metal to lose electrons, so barium is the strongest reducing agent and the most reactive.', '{"0": "Ba²⁺ is the hardest of these ions to reduce, since its E° is the most negative.", "1": "Mg has the less negative potential, so it loses electrons less readily than Ba.", "3": "Reactivity increases down the group."}'),
  ('CHE-0718', 's-block elements', 'Properties and trends', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 2 (Table 17.1)', 'According to Table 17.1, the second ionization energy of the Group 2 elements', '["decreases from Be (1757) to Ba (965 kJ mol⁻¹).", "is smaller than the first IE.", "is the same for all members.", "increases from Be to Ba."]', 0, 'Both first and second ionization energies fall down the group, from 1757 kJ mol⁻¹ for Be to 965 kJ mol⁻¹ for Ba, as the outer electrons get further from the nucleus.', '{"1": "The second IE is always larger than the first, since the electron is removed from a positive ion.", "2": "The values differ widely across the group.", "3": "The trend is downward, not upward."}'),
  ('CHE-0719', 's-block elements', 'Reactions with oxygen', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 3 (§17.2.1)', 'Beryllium is less reactive towards oxygen than the other Group 2 metals because', '["it has no valence electrons.", "it is a liquid at room temperature.", "it forms a peroxide instead of an oxide.", "a thin, strong oxide layer protects its surface."]', 3, 'Beryllium reacts with oxygen only at high temperature (above 600 °C). A thin, strong oxide layer normally protects it.', '{"0": "Beryllium has two valence electrons (2s²).", "1": "Beryllium melts at 1287 °C.", "2": "The book gives BeO, a normal oxide, as the product."}'),
  ('CHE-0720', 's-block elements', 'Reactions with oxygen', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 3 (§17.2.1)', 'According to the book, calcium burns in oxygen with a', '["brilliant white flame", "green flame", "brick-red flame", "lilac flame"]', 2, 'The book says calcium''s reaction with oxygen is more vigorous than magnesium''s and gives a brick-red flame.', '{"0": "Magnesium burns with a bright white light.", "1": "A green flame is associated with barium (and copper), not calcium.", "3": "A lilac flame is characteristic of potassium, a Group 1 metal."}'),
  ('CHE-0721', 's-block elements', 'Reactions with oxygen', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 3 (§17.2.1)', 'Group 2 oxides give alkaline solutions in water because', '["they form carbonates in water", "the metal ion reacts with water to release H⁺", "they release oxygen gas", "the oxide ion reacts with water: O²⁻ + H₂O → 2OH⁻"]', 3, 'The basic character comes from the oxide ion taking a proton from water to form two hydroxide ions.', '{"0": "Carbonates form with CO₂, not with water alone.", "1": "Releasing H⁺ would make the solution acidic.", "2": "No oxygen gas is released."}'),
  ('CHE-0722', 's-block elements', 'Reactions with water', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 4 (§17.2.2)', 'When calcium reacts with cold water, a white precipitate appears because', '["calcium hydroxide is only sparingly soluble.", "calcium oxide does not dissolve.", "calcium carbonate forms.", "hydrogen gas is a white solid."]', 0, 'Ca + 2H₂O → Ca(OH)₂ + H₂. Calcium hydroxide is sparingly soluble, so some of it appears as a white precipitate.', '{"1": "Calcium gives the hydroxide with water, not the oxide.", "2": "No carbon is present to form a carbonate.", "3": "Hydrogen is a colourless gas."}'),
  ('CHE-0723', 's-block elements', 'Reactions with acids', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 4 (§17.2.3)', 'Calcium reacts vigorously with dilute HCl, but its reaction with dilute H₂SO₄ can stop early because', '["sulphuric acid is a weak acid.", "hydrogen gas reacts with calcium sulphate.", "sparingly soluble CaSO₄ coats the metal surface.", "calcium is less reactive than magnesium."]', 2, 'Ca + H₂SO₄ → CaSO₄ + H₂. The calcium sulphate formed is sparingly soluble and forms a protective layer on the metal, stopping further reaction.', '{"0": "Dilute sulphuric acid is a strong acid.", "1": "Hydrogen does not react with calcium sulphate.", "3": "Calcium is more reactive than magnesium."}'),
  ('CHE-0724', 's-block elements', 'Group 1 and Group 2 compared', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 5 (Table 17.2)', 'Compared with Group 1 metals in the same period, Group 2 metals are', '["softer and less dense.", "more reactive with lower melting points.", "identical in hardness and density.", "harder, denser and less reactive."]', 3, 'Group 2 metals lose two electrons, which needs more energy, so they are less reactive. Table 17.2 also lists them as harder, denser and higher-melting than Group 1 metals.', '{"0": "Group 1 metals are the softer and less dense ones.", "1": "Group 1 metals are more reactive and have lower melting points.", "2": "The table lists clear differences in hardness and density."}'),
  ('CHE-0725', 's-block elements', 'Group 1 and Group 2 compared', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 5 (Table 17.2)', 'The general formula of a Group 2 oxide is', '["M₂O", "M₂O₃", "MO", "MO₂"]', 2, 'Group 2 metals form M²⁺ ions, which combine with O²⁻ in a 1 : 1 ratio, as in CaO.', '{"0": "M₂O is the Group 1 oxide formula, as in Na₂O.", "1": "M₂O₃ needs M³⁺, as in Al₂O₃.", "3": "MO₂ would need M⁴⁺ (or a peroxide/superoxide)."}'),
  ('CHE-0726', 's-block elements', 'Thermal decomposition', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 5 (§17.4)', 'Thermal decomposition of a Group 2 carbonate is usually', '["exothermic, because bonds form.", "a reaction that needs no heat.", "a redox reaction producing the metal.", "endothermic, because energy is needed to break bonds."]', 3, 'The book says thermal decomposition usually requires energy (is endothermic) to break the bonds in the compound: MCO₃ → MO + CO₂.', '{"0": "Heat must be supplied; the reaction absorbs energy.", "1": "\"Thermal\" decomposition happens on heating.", "2": "The products are the metal oxide and CO₂, not the metal."}'),
  ('CHE-0727', 's-block elements', 'Thermal decomposition', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 6 (Table 17.3)', 'Using Table 17.3, which carbonate decomposes at about 900 °C?', '["MgCO₃", "BaCO₃", "CaCO₃", "SrCO₃"]', 2, 'The decomposition temperatures are BeCO₃ 250, MgCO₃ 540, CaCO₃ 900, SrCO₃ 1289 and BaCO₃ 1360 °C.', '{"0": "MgCO₃ decomposes at 540 °C.", "1": "BaCO₃ decomposes at 1360 °C.", "3": "SrCO₃ decomposes at 1289 °C."}'),
  ('CHE-0728', 's-block elements', 'Thermal decomposition', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 6 (§17.4)', 'MgCO₃ decomposes at a lower temperature than CaCO₃ because Mg²⁺', '["forms a more stable oxide only at high temperature.", "is larger and has a lower polarizing power.", "has a higher charge than Ca²⁺.", "is smaller and polarizes the carbonate ion more strongly, weakening its bonds."]', 3, 'The smaller Mg²⁺ ion has a higher charge density, so it distorts the large CO₃²⁻ ion more. This weakens the C–O bonds and the carbonate breaks down more easily.', '{"0": "The book''s explanation is polarization of the carbonate ion by the cation.", "1": "Mg²⁺ (65 pm) is smaller than Ca²⁺ (99 pm).", "2": "Both ions carry a 2+ charge."}'),
  ('CHE-0729', 's-block elements', 'Thermal decomposition', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 6 (§17.4)', 'In 2Ca(NO₃)₂ → 2CaO + 4NO₂ + O₂, the brown gas observed is', '["nitrogen dioxide", "nitrogen", "oxygen", "carbon dioxide"]', 0, 'Group 2 nitrates decompose to the metal oxide, brown nitrogen dioxide and oxygen.', '{"1": "Nitrogen is not a product of this decomposition.", "2": "Oxygen is colourless.", "3": "There is no carbon in a nitrate."}'),
  ('CHE-0730', 's-block elements', 'Thermal decomposition', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 6 (§17.4)', 'Which Group 2 nitrate is the least thermally stable?', '["Ca(NO₃)₂", "Mg(NO₃)₂", "Be(NO₃)₂", "Ba(NO₃)₂"]', 2, 'Thermal stability of nitrates increases down the group. Be²⁺, the smallest ion, polarizes the nitrate ion most, so Be(NO₃)₂ is the least stable.', '{"0": "Ca(NO₃)₂ is more stable than both Be and Mg nitrates.", "1": "Mg(NO₃)₂ is more stable than Be(NO₃)₂.", "3": "Ba(NO₃)₂ is the most stable."}'),
  ('CHE-0731', 's-block elements', 'Solubility', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 7 (§17.5)', 'Which statement about hydration enthalpy of Group 2 ions is correct according to the book?', '["It is always exothermic and becomes less negative down the group.", "It is the energy needed to break the crystal lattice.", "It becomes more negative down the group.", "It is always endothermic."]', 0, 'Hydration enthalpy is the energy released when gaseous ions are hydrated, so it is negative. Larger ions attract water less strongly, so it becomes less negative down the group.', '{"1": "That is lattice enthalpy as the book defines it.", "2": "Smaller ions have the more negative values, so it becomes less negative down the group.", "3": "Hydration releases energy; it is exothermic."}'),
  ('CHE-0732', 's-block elements', 'Solubility', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 7 (§17.5)', 'As defined in the book, lattice enthalpy is the energy', '["change when a solid dissolves in water.", "released when gaseous ions are hydrated.", "released when a metal burns in oxygen.", "required to break one mole of a solid ionic compound into its gaseous ions."]', 3, 'The book defines lattice enthalpy as the energy required to break apart one mole of an ionic lattice into gaseous ions; it is endothermic.', '{"0": "That is the enthalpy of solution.", "1": "That is hydration enthalpy.", "2": "That is an enthalpy of combustion."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0733', 's-block elements', 'Solubility', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 7 (§17.5)', 'The solubility of Group 2 hydroxides increases down the group because', '["lattice enthalpy falls more than hydration enthalpy does.", "hydration enthalpy falls more than lattice enthalpy does.", "hydration enthalpy becomes more negative down the group.", "the hydroxide ion becomes larger down the group."]', 0, 'Both enthalpies decrease down the group, but for the small OH⁻ ion the lattice enthalpy falls more, so the enthalpy of solution becomes more favourable and solubility rises.', '{"1": "That is the explanation for sulphates, whose solubility decreases.", "2": "Hydration enthalpy becomes less negative down the group.", "3": "The anion is the same OH⁻ ion throughout."}'),
  ('CHE-0734', 's-block elements', 'Solubility', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 8 (§17.5)', 'Group 2 sulphates become less soluble down the group because, for the large sulphate ion,', '["lattice enthalpy decreases more than hydration enthalpy.", "the sulphate ion becomes smaller down the group.", "hydration enthalpy decreases more than lattice enthalpy.", "lattice enthalpy increases sharply."]', 2, 'With a large anion, the lattice enthalpy changes little as the cation grows, but the hydration enthalpy of M²⁺ falls a lot. So dissolving becomes less favourable and solubility falls (MgSO₄ soluble, BaSO₄ insoluble).', '{"0": "That would make solubility increase, as with the hydroxides.", "1": "The anion is the same SO₄²⁻ ion throughout.", "3": "Lattice enthalpy decreases down the group, it does not rise sharply."}'),
  ('CHE-0735', 's-block elements', 'Solubility', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 8 (Table 17.4)', 'Using Table 17.4, about how many times more soluble is Ba(OH)₂ (1.5 × 10⁻² mol/100 g) than Mg(OH)₂ (2 × 10⁻⁵ mol/100 g)?', '["75", "3.0", "7500", "750"]', 3, '1.5 × 10⁻² ÷ 2 × 10⁻⁵ = 0.75 × 10³ = 750.', '{"0": "75 is out by a factor of ten.", "1": "3.0 comes from subtracting the exponents (−2 and −5) and ignores the coefficients.", "2": "7500 is out by a factor of ten."}'),
  ('CHE-0736', 's-block elements', 'Complex ions', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 8 (§17.6)', 'In a complex ion, the central metal ion acts as', '["a Lewis base, donating electron pairs.", "a Lewis acid, accepting electron pairs.", "a Brønsted acid, donating protons.", "a reducing agent."]', 1, 'The metal ion accepts lone pairs from surrounding species such as H₂O, NH₃, Cl⁻ and OH⁻, which act as Lewis bases.', '{"0": "The surrounding molecules or ions donate the electron pairs.", "2": "Complex formation is about electron pairs, not proton transfer.", "3": "No electron transfer (redox) is involved in forming the coordinate bonds."}'),
  ('CHE-0737', 's-block elements', 'Complex ions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 8 (§17.6)', 'Beryllium ions in water form [Be(H₂O)₄]²⁺. The coordination number of Be²⁺ in this ion is', '["4", "2", "6", "8"]', 0, 'The coordination number is the number of coordinate bonds to the central ion. Four water molecules bond to Be²⁺, so it is 4. The larger Mg²⁺ forms [Mg(H₂O)₆]²⁺ with coordination number 6.', '{"1": "Two would mean only two water ligands.", "2": "Six is the coordination number of Mg²⁺ in [Mg(H₂O)₆]²⁺.", "3": "Eight is not given in the book for Group 2 ions."}'),
  ('CHE-0738', 's-block elements', 'Complex ions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 9 (§17.6)', 'EDTA is used in water softening because it', '["oxidizes Ca²⁺ and Mg²⁺ to insoluble solids.", "forms stable complexes with Ca²⁺ and Mg²⁺ using six electron pairs.", "precipitates calcium as CaCO₃.", "releases Na⁺ ions only."]', 1, 'EDTA is a six electron pair donor that wraps around Ca²⁺ or Mg²⁺ in a ring-like complex, e.g. Ca²⁺ + EDTA⁴⁻ → [Ca(EDTA)]²⁻, removing the hardness ions from solution.', '{"0": "Ca²⁺ and Mg²⁺ are not oxidized.", "2": "EDTA forms soluble complexes, not carbonate precipitates.", "3": "The book''s mechanism is complex formation with the metal ions."}'),
  ('CHE-0739', 's-block elements', 'Extraction', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 9 (§17.7.1)', 'In the Dow process, magnesium is first removed from seawater as', '["MgCl₂, by evaporation", "Mg metal, by adding carbon", "Mg(OH)₂, by adding Ca(OH)₂", "MgCO₃, by adding CO₂"]', 2, 'Calcium hydroxide (from limestone or oyster shells) precipitates insoluble Mg(OH)₂: Mg²⁺ + Ca(OH)₂ → Mg(OH)₂ + Ca²⁺.', '{"0": "MgCl₂ is made later by treating Mg(OH)₂ with HCl.", "1": "Magnesium metal is obtained by electrolysis of molten MgCl₂.", "3": "The book does not use CO₂ in the process."}'),
  ('CHE-0740', 's-block elements', 'Extraction', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 9 (§17.7.1)', 'In the final step of the Dow process, molten MgCl₂ is electrolysed. The products are', '["Mg at the anode and Cl₂ at the cathode", "MgO and HCl", "Mg(OH)₂ and H₂", "Mg at the cathode and Cl₂ at the anode"]', 3, 'Mg²⁺ is reduced at the cathode to magnesium metal, and Cl⁻ is oxidized at the anode to chlorine gas.', '{"0": "The electrodes are swapped; cations are reduced at the cathode.", "1": "Electrolysis of molten MgCl₂ gives the elements.", "2": "Molten MgCl₂ contains no water, so no H₂ or hydroxide forms."}'),
  ('CHE-0741', 's-block elements', 'Extraction', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 10 (§17.7.2)', 'In a lime kiln, CO₂ is removed continuously from CaCO₃ ⇌ CaO + CO₂ in order to', '["cool the kiln.", "shift the equilibrium to the right and produce more CaO.", "stop the reaction.", "convert CaO back into CaCO₃."]', 1, 'The reaction is reversible in a closed container. Removing CO₂ shifts the equilibrium to the right, giving a large amount of quicklime.', '{"0": "Removing the gas is about equilibrium, not cooling.", "2": "It drives the reaction forward instead of stopping it.", "3": "That would happen if CO₂ were kept in, not removed."}'),
  ('CHE-0742', 's-block elements', 'Uses', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 10 (§17.8.1)', 'Plaster of Paris has the formula', '["CaSO₄·2H₂O", "CaSO₄·½H₂O", "MgSO₄·7H₂O", "CaCO₃"]', 1, 'Gypsum is CaSO₄·2H₂O; plaster of Paris is the hemihydrate CaSO₄·½H₂O.', '{"0": "CaSO₄·2H₂O is gypsum.", "2": "MgSO₄·7H₂O is Epsom salt.", "3": "CaCO₃ is limestone, marble or chalk."}'),
  ('CHE-0743', 's-block elements', 'Uses', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 11 (§17.8.2)', 'Barium sulphate is safe to use in a "barium meal" for X-ray imaging because it', '["is highly insoluble and passes through the body without being absorbed.", "is highly soluble and quickly absorbed.", "is transparent to X-rays.", "neutralizes stomach acid."]', 0, 'BaSO₄ is opaque to X-rays, so it shows up the digestive system, and it is so insoluble that toxic Ba²⁺ is not absorbed.', '{"1": "Soluble barium compounds are toxic; BaSO₄ is safe because it is insoluble.", "2": "It is opaque to X-rays, which is why it is useful.", "3": "Antacids are compounds such as Mg(OH)₂ and CaCO₃."}'),
  ('CHE-0744', 's-block elements', 'Uses', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 11 (§17.8.2)', '"Milk of magnesia", used to neutralize excess stomach acid, is', '["MgSO₄", "Mg(OH)₂", "MgO", "MgCO₃"]', 1, 'Magnesium hydroxide is milk of magnesia. Its low solubility makes it safe as an antacid and mild laxative.', '{"0": "MgSO₄·7H₂O (Epsom salt) is a laxative, not milk of magnesia.", "2": "MgO is used as a refractory material.", "3": "The book does not name MgCO₃ as milk of magnesia."}'),
  ('CHE-0745', 's-block elements', 'Uses', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 11 (§17.8.1)', 'In flue gas desulphurization, CaO and CaCO₃ are used to', '["produce oxygen.", "remove acidic SO₂ from power-plant emissions.", "remove CO from car exhausts.", "increase the pH of drinking water."]', 1, 'These basic calcium compounds react with acidic SO₂ in wet scrubbing, cutting emissions that cause acid rain.', '{"0": "They do not produce oxygen.", "2": "CO in car exhaust is dealt with by catalytic converters.", "3": "The book describes their use on flue gases."}'),
  ('CHE-0746', 's-block elements', 'Uses', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 11 (Did you know)', 'Beryllium is used in X-ray tubes because it', '["is opaque to X-rays.", "is transparent to X-rays.", "glows red when heated.", "is very soluble in water."]', 1, 'The book notes that beryllium is used in X-ray tubes because it is transparent to X-rays.', '{"0": "An opaque window would block the X-rays.", "2": "The book does not give this as the reason.", "3": "Solubility is irrelevant to an X-ray window."}'),
  ('CHE-0747', 's-block elements', 'Uses', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 17 Group 2 Elements, p. 11 (§17.8.3)', 'Calcium hydroxide is added to acidic soils in order to', '["raise the soil pH by neutralizing acidity.", "lower the soil pH.", "supply nitrogen.", "kill all soil bacteria."]', 0, 'Ca(OH)₂ and CaCO₃ are bases and neutralize soil acidity, raising the pH so crops grow better.', '{"1": "Bases raise the pH, they do not lower it.", "2": "Calcium hydroxide contains no nitrogen.", "3": "Liming is for pH control, not sterilization."}'),
  ('CHE-0748', 'Transition elements', 'Transition elements', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 16 (§18.1)', 'Zinc is a d-block element but is not classed as a transition element because', '["it has no d electrons.", "it forms coloured ions.", "its only ion, Zn²⁺, has a completely filled 3d subshell.", "it shows many oxidation states."]', 2, 'A transition element must form a stable ion with an incomplete d subshell. Zn²⁺ is [Ar] 3d¹⁰, so zinc does not qualify.', '{"0": "Zinc has ten 3d electrons.", "1": "Zn²⁺ compounds are typically white, because the 3d subshell is full.", "3": "Zinc forms only one ion, Zn²⁺."}'),
  ('CHE-0749', 'Transition elements', 'Electronic configuration', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 16 (§18.1.1, Table 18.1)', 'Which two first-row transition elements do NOT follow the Aufbau order in their ground-state configurations?', '["Manganese and nickel", "Iron and cobalt", "Titanium and vanadium", "Chromium and copper"]', 3, 'Cr is [Ar] 3d⁵ 4s¹ and Cu is [Ar] 3d¹⁰ 4s¹, gaining the extra stability of a half-filled and a completely filled d subshell.', '{"0": "Mn ([Ar] 3d⁵ 4s²) and Ni ([Ar] 3d⁸ 4s²) follow the Aufbau order.", "1": "Fe ([Ar] 3d⁶ 4s²) and Co ([Ar] 3d⁷ 4s²) follow the Aufbau order.", "2": "Ti ([Ar] 3d² 4s²) and V ([Ar] 3d³ 4s²) follow the Aufbau order."}'),
  ('CHE-0750', 'Transition elements', 'Electronic configuration', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 16 (Table 18.1)', 'The electronic configuration of Fe³⁺ is', '["[Ar] 3d⁶", "[Ar] 3d³ 4s²", "[Ar] 3d⁵", "[Ar] 3d⁴ 4s¹"]', 2, 'Fe is [Ar] 3d⁶ 4s². Forming Fe³⁺ removes the two 4s electrons first and then one 3d electron, giving [Ar] 3d⁵.', '{"0": "[Ar] 3d⁶ is Fe²⁺.", "1": "The 4s electrons are lost before the 3d electrons.", "3": "The 4s electrons are removed first, so none remain in Fe³⁺."}'),
  ('CHE-0751', 'Transition elements', 'Electronic configuration', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 16 (Table 18.1)', 'How many unpaired d electrons does Co²⁺ ([Ar] 3d⁷) have in a free ion?', '["3", "1", "5", "7"]', 0, 'By Hund''s rule the seven d electrons fill five orbitals singly first, then pair two of them: five singly occupied minus two paired leaves three unpaired electrons.', '{"1": "One unpaired electron would be d⁹ (e.g. Cu²⁺).", "2": "Five unpaired electrons is d⁵ (e.g. Mn²⁺, Fe³⁺).", "3": "Only five d orbitals exist, so seven electrons cannot all be unpaired."}'),
  ('CHE-0752', 'Transition elements', 'Physical properties', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 17 (§18.2.1)', 'Most first-row transition metals and their compounds are paramagnetic because they', '["have high densities.", "have full d subshells.", "are good conductors of heat.", "have unpaired d electrons."]', 3, 'Unpaired electrons are attracted into a magnetic field. The book links paramagnetism to unpaired d electrons.', '{"0": "Density is unrelated to magnetism.", "1": "Full d subshells have all electrons paired (diamagnetic).", "2": "Conduction of heat is unrelated to magnetism."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0753', 'Transition elements', 'Physical properties', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 17 (§18.2.1)', 'Across the first transition row from Ti to Cu, density generally', '["decreases because atoms get larger.", "stays constant.", "increases because nuclear charge builds up and atoms shrink.", "increases only for Cr and Cu."]', 2, 'The book says density generally rises from titanium to copper due to the regular build-up of nuclear charge and shrinkage in atomic size.', '{"0": "Atomic size decreases across the row (Ti 147 to Ni 124 pm).", "1": "Density changes across the row.", "3": "The rise is a general trend across the row."}'),
  ('CHE-0754', 'Transition elements', 'Physical properties', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 17 (§18.2.1)', 'Which first-row transition metal is reddish-brown, while the others are silvery or grey?', '["Iron", "Titanium", "Nickel", "Copper"]', 3, 'The book notes that copper is reddish-brown, while the others are silvery or grey lustrous metals.', '{"0": "Iron is a grey metal.", "1": "Titanium is silvery grey.", "2": "Nickel is silvery."}'),
  ('CHE-0755', 'Transition elements', 'Variable oxidation states', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 18 (§18.2.3)', 'Which first-row transition element shows the highest oxidation state, +7?', '["Chromium", "Iron", "Manganese", "Vanadium"]', 2, 'Manganese can lose its two 4s and five 3d electrons, reaching +7 as in MnO₄⁻.', '{"0": "Chromium''s highest state is +6.", "1": "Iron''s common states are +2 and +3 (the table goes to +6).", "3": "Vanadium''s highest state is +5."}'),
  ('CHE-0756', 'Transition elements', 'Variable oxidation states', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 18 (§18.2.3)', 'When a 3d metal atom loses only its 4s electrons, it usually forms ions in the', '["+1 oxidation state", "highest oxidation state", "+3 oxidation state", "+2 oxidation state"]', 3, 'Losing the two 4s electrons gives the common +2 state. Losing 3d electrons as well gives higher oxidation states.', '{"0": "+1 would need only one electron lost (as in Cu⁺, from 4s¹).", "1": "Higher states involve 3d electrons too.", "2": "+3 requires loss of a 3d electron as well."}'),
  ('CHE-0757', 'Transition elements', 'Catalysis', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 18–19 (§18.2.4)', 'Which is an example of heterogeneous catalysis by a transition metal given in the book?', '["Fe²⁺/Fe³⁺ ions in solution", "Nickel salts in making acrylic acid from acetylene", "Solid iron in the Haber process for ammonia", "EDTA complexes of copper"]', 2, 'In heterogeneous catalysis, reactants adsorb on the solid catalyst surface. The book''s example is solid iron catalysing N₂ + H₂ → NH₃.', '{"0": "Ions in the same solution as the reactants act homogeneously.", "1": "The nickel salt example is homogeneous catalysis (Ni(0)/Ni(II)).", "3": "EDTA complexes are not given as catalysts."}'),
  ('CHE-0758', 'Transition elements', 'Catalysis', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 18 (§18.2.4)', 'In homogeneous catalysis, a transition metal ion lowers the activation energy mainly because it', '["precipitates the products.", "has a high density.", "is always in its highest oxidation state.", "can switch between stable oxidation states, forming an intermediate and then being regenerated."]', 3, 'The ion changes oxidation state (e.g. Fe²⁺ ⇌ Fe³⁺) to form an unstable intermediate with a reactant, which then forms the product and gives back the catalyst.', '{"0": "Catalysts are not involved in precipitating products.", "1": "Density does not affect catalytic ability.", "2": "The key is the ability to change between states."}'),
  ('CHE-0759', 'Transition elements', 'Complexes and ligands', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 19 (§18.3)', 'A ligand is a species that', '["accepts a lone pair from a metal ion.", "is always negatively charged.", "has at least one lone pair and forms a dative bond to a central metal atom or ion.", "is always a metal."]', 2, 'Ligands are Lewis bases that donate a lone pair to the central metal, forming a coordinate (dative) covalent bond.', '{"0": "The metal accepts the lone pair; the ligand donates it.", "1": "Ligands can be neutral (H₂O, NH₃, CO) or even cationic (NO⁺).", "3": "Ligands are molecules or ions with lone pairs, not metals."}'),
  ('CHE-0760', 'Transition elements', 'Complexes and ligands', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 20 (§18.3)', 'In naming complexes, the neutral ligand NH₃ is called', '["amine", "aqua", "amido", "ammine"]', 3, 'The book lists the special names aqua (H₂O), ammine (NH₃) and carbonyl (CO).', '{"0": "\"Amine\" is the organic functional group, not the ligand name.", "1": "Aqua is the name for H₂O.", "2": "Amido refers to NH₂⁻, not NH₃."}'),
  ('CHE-0761', 'Transition elements', 'Complexes and ligands', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 20 (§18.3)', 'Which of these is a bidentate ligand?', '["NH₃", "Cl⁻", "1,2-diaminoethane (en)", "EDTA"]', 2, 'In 1,2-diaminoethane (H₂NCH₂CH₂NH₂), both N atoms donate a lone pair, giving two dative bonds to the same metal.', '{"0": "NH₃ donates one lone pair (monodentate).", "1": "Cl⁻ is monodentate.", "3": "EDTA is hexadentate (six donor atoms)."}'),
  ('CHE-0762', 'Transition elements', 'Complexes and ligands', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 20 (§18.3)', 'EDTA is hexadentate. Its six donor atoms are', '["six oxygen atoms", "four nitrogen and two oxygen atoms", "four oxygen and two nitrogen atoms", "six nitrogen atoms"]', 2, 'The book says EDTA attaches to a metal ion through four oxygen and two nitrogen atoms.', '{"0": "Two of the donors are nitrogen atoms.", "1": "There are only two nitrogen atoms in EDTA.", "3": "Four of the donors are oxygen atoms of carboxylate groups."}'),
  ('CHE-0763', 'Transition elements', 'Formula and charge', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 20 (Figure 18.2)', 'In [Fe(CN)₆]⁴⁻, the oxidation state of iron is', '["+3", "+2", "+4", "+6"]', 1, 'Charge on the ion = metal charge + ligand charges: x + 6(−1) = −4, so x = +2.', '{"0": "+3 would give [Fe(CN)₆]³⁻.", "2": "+4 would give a charge of −2.", "3": "+6 would give a neutral complex."}'),
  ('CHE-0764', 'Transition elements', 'Formula and charge', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 21 (Table 18.3)', 'A complex is formed from Cr³⁺ and six neutral H₂O ligands. Its formula and charge are', '["[Cr(H₂O)₄]³⁺", "[Cr(H₂O)₆]³⁻", "[Cr(H₂O)₆]", "[Cr(H₂O)₆]³⁺"]', 3, 'Charge = (+3) + 6 × (0) = +3, and six ligands are placed inside the brackets after the metal.', '{"0": "The coordination number is six, so six ligands are needed.", "1": "Neutral ligands cannot make the charge negative.", "2": "The metal''s +3 charge remains, so the complex is not neutral."}'),
  ('CHE-0765', 'Transition elements', 'Formula and charge', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 21 (Table 18.3)', 'The book''s example of a neutral complex is', '["[Co(NH₃)₆]³⁺", "[Fe(CN)₆]⁴⁻", "[Ni(CO)₄]", "[CuCl₄]²⁻"]', 2, 'In [Ni(CO)₄], nickel is in the 0 oxidation state and CO is neutral, so the charge is (0) + 4 × (0) = 0.', '{"0": "[Co(NH₃)₆]³⁺ is the book''s cationic example.", "1": "[Fe(CN)₆]⁴⁻ is the book''s anionic example.", "3": "[CuCl₄]²⁻ carries a 2− charge."}'),
  ('CHE-0766', 'Transition elements', 'Geometry', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 22 (§18.5)', '[Ag(NH₃)₂]⁺ has which geometry?', '["Linear, 180°", "Square planar, 90°", "Tetrahedral, 109.5°", "Octahedral, 90°"]', 0, 'With two ligands on opposite sides of the metal, the complex is linear with a 180° bond angle. The book cites [Ag(NH₃)₂]Cl and K[Ag(CN)₂].', '{"1": "Square planar needs four ligands.", "2": "Tetrahedral needs four ligands.", "3": "Octahedral needs six ligands."}'),
  ('CHE-0767', 'Transition elements', 'Geometry', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 22 (§18.5)', 'Square planar geometry is characteristic of complexes of', '["d¹⁰ ions such as Zn²⁺", "d⁸ ions such as Ni²⁺ and Pt²⁺", "d⁰ ions such as Ti⁴⁺", "d⁵ ions such as Mn²⁺"]', 1, 'The book says square planar is characteristic of d⁸ metal ions with ligands such as NH₃ and CN⁻, e.g. [Ni(CN)₄]²⁻ and [Pt(NH₃)₄]²⁺.', '{"0": "d¹⁰ four-coordinate complexes are usually tetrahedral.", "2": "d⁰ ions are not given as square planar examples.", "3": "[MnCl₄]²⁻ (d⁵) is given as tetrahedral."}'),
  ('CHE-0768', 'Transition elements', 'Geometry', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 22 (§18.5)', 'The most common geometry for transition metal complexes is', '["linear", "square planar", "tetrahedral", "octahedral"]', 3, 'The book states that octahedral, with six ligands along the x, y and z axes, is the most common geometry, e.g. [Cr(NH₃)₆]³⁺ and [Co(en)₃]³⁺.', '{"0": "Linear complexes need only two ligands and are less common.", "1": "Square planar is mainly found for d⁸ ions.", "2": "Tetrahedral complexes are common for some ions but not the most common overall."}'),
  ('CHE-0769', 'Transition elements', 'd-orbital splitting', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 23 (§18.6)', 'In an octahedral complex, the five d orbitals split into', '["three lower (dxy, dxz, dyz) and two higher (dx²−y², dz²) orbitals", "two lower (dx²−y², dz²) and three higher (dxy, dxz, dyz) orbitals", "five orbitals of equal energy", "one lower and four higher orbitals"]', 0, 'The ligands approach along the axes, so the axial dx²−y² and dz² orbitals are pushed higher, leaving dxy, dxz and dyz lower.', '{"1": "That is the tetrahedral pattern, which is inverted.", "2": "Equal energies (degenerate) apply to an isolated ion, not a complex.", "3": "The split is into sets of three and two."}'),
  ('CHE-0770', 'Transition elements', 'd-orbital splitting', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 23 (§18.6)', 'Compared with octahedral splitting, the d-orbital splitting in a tetrahedral complex is', '["inverted and smaller", "the same pattern and larger", "inverted and larger", "zero"]', 0, 'In a tetrahedral field three orbitals (dxy, dxz, dyz) are higher and two (dx²−y², dz²) are lower, and the book says the splitting is smaller than in octahedral complexes.', '{"1": "The pattern is inverted, and the splitting is smaller.", "2": "The splitting is smaller, not larger.", "3": "The orbitals are split, just less than in octahedral complexes."}'),
  ('CHE-0771', 'Transition elements', 'Colour of complexes', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 24 (§18.6.1)', 'A complex absorbs yellow light. According to the colour wheel it appears', '["yellow", "violet", "green", "red"]', 1, 'The colour seen is the complement of the colour absorbed. The book''s example: a complex that absorbs yellow light appears violet.', '{"0": "Yellow is the colour absorbed, so it is removed from the light we see.", "2": "Green is complementary to red.", "3": "Red is complementary to green."}'),
  ('CHE-0772', 'Transition elements', 'Colour of complexes', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 24 (§18.6.1)', 'Replacing H₂O ligands with CN⁻ in a complex generally', '["increases ΔE, so higher-frequency (shorter-wavelength) light is absorbed.", "decreases ΔE, so lower-frequency light is absorbed.", "has no effect on ΔE.", "removes all d-orbital splitting."]', 0, 'CN⁻ is at the top of the book''s series (CN⁻ > en > NH₃ > H₂O > OH⁻ > Cl⁻ > Br⁻ > I⁻), so it causes larger splitting. A larger ΔE means higher-frequency light is absorbed (ΔE = hν).', '{"1": "CN⁻ causes larger, not smaller, splitting than H₂O.", "2": "Changing ligands changes ΔE and so the colour.", "3": "Ligands cause splitting; CN⁻ increases it."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0773', 'Transition elements', 'Colour of complexes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 24 (§18.6.1)', 'Which ligand causes the smallest d-orbital splitting in the book''s series?', '["CN⁻", "NH₃", "H₂O", "I⁻"]', 3, 'The series runs from high to low ΔE: CN⁻ > en > NH₃ > H₂O > OH⁻ > Cl⁻ > Br⁻ > I⁻, so iodide gives the smallest splitting.', '{"0": "CN⁻ gives the largest splitting.", "1": "NH₃ gives larger splitting than water.", "2": "H₂O is in the middle of the series."}'),
  ('CHE-0774', 'Transition elements', 'Ligand exchange', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 25 (§18.7.1)', 'Concentrated HCl is added dropwise to blue aqueous copper(II) sulphate. The solution turns yellow(-green) because', '["Cu²⁺ is reduced to Cu⁺.", "Cl⁻ replaces water to form [CuCl₄]²⁻.", "copper(II) hydroxide precipitates.", "ammonia ligands are lost."]', 1, '[Cu(H₂O)₆]²⁺ + 4Cl⁻ → [CuCl₄]²⁻ + 6H₂O. The new ligands change ΔE, so the colour changes.', '{"0": "There is no change of oxidation state in ligand exchange.", "2": "A precipitate forms with OH⁻, not with HCl.", "3": "There is no ammonia in the solution."}'),
  ('CHE-0775', 'Transition elements', 'Ligand exchange', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 25 (§18.7.1)', 'Sodium hydroxide gives a light blue precipitate with aqueous Cu²⁺. Concentrated ammonia then dissolves it to give', '["a colourless solution", "a dark blue solution of [Cu(NH₃)₄(H₂O)₂]²⁺", "a yellow solution of [CuCl₄]²⁻", "a pink solution"]', 1, 'Ammonia replaces the hydroxide and water ligands in [Cu(H₂O)₄(OH)₂], forming the soluble dark blue [Cu(NH₃)₄(H₂O)₂]²⁺.', '{"0": "The ammine complex is dark blue, not colourless.", "2": "[CuCl₄]²⁻ forms with chloride ions, not ammonia.", "3": "Pink is the colour of aqueous cobalt(II)."}'),
  ('CHE-0776', 'Transition elements', 'Ligand exchange', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 26 (§18.7.2)', 'Concentrated HCl is added to pink aqueous cobalt(II). The blue complex formed is', '["[Co(H₂O)₆]²⁺, octahedral", "[CoCl₄]²⁻, tetrahedral", "[Co(NH₃)₆]²⁺, octahedral", "[CoCl₆]⁴⁻, octahedral"]', 1, '[Co(H₂O)₆]²⁺ + 4Cl⁻ → [CoCl₄]²⁻ + 6H₂O. The product has four ligands in a tetrahedral arrangement and is blue.', '{"0": "[Co(H₂O)₆]²⁺ is the pink starting complex.", "2": "[Co(NH₃)₆]²⁺ forms with ammonia and is yellow.", "3": "The book gives the four-coordinate tetrahedral chloro complex."}'),
  ('CHE-0777', 'Transition elements', 'Stability constants', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 27 (§18.8)', 'For [Cu(H₂O)₆]²⁺ + 4Cl⁻ ⇌ [CuCl₄]²⁻ + 6H₂O, the stability constant expression is', '["Kstab = [CuCl₄²⁻][H₂O]⁶ / ([Cu(H₂O)₆²⁺][Cl⁻]⁴)", "Kstab = [CuCl₄²⁻] / ([Cu(H₂O)₆²⁺][Cl⁻]⁴)", "Kstab = [Cu(H₂O)₆²⁺][Cl⁻]⁴ / [CuCl₄²⁻]", "Kstab = [CuCl₄²⁻] / ([Cu(H₂O)₆²⁺][Cl⁻])"]', 1, 'Water is the solvent, so its concentration is constant and is left out. The chloride concentration is raised to the power 4.', '{"0": "[H₂O] is omitted because water is the solvent.", "2": "This is the reciprocal, the constant for dissociation.", "3": "The chloride concentration must be raised to the power 4."}'),
  ('CHE-0778', 'Transition elements', 'Stability constants', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 27–28 (§18.8, Table 18.5)', 'log Kstab is 5.6 for [CuCl₄]²⁻ and 18.8 for [Cu(EDTA)]²⁻. Which statement is correct?', '["[CuCl₄]²⁻ is the more stable complex.", "EDTA can displace Cl⁻ from [CuCl₄]²⁻ because its complex is far more stable (the chelate effect).", "Chloride can displace EDTA from copper.", "Both complexes have the same stability."]', 1, 'A larger log Kstab means a more stable complex, and a ligand with a higher Kstab can displace one with a lower Kstab. Polydentate ligands give more stable complexes: the chelating effect.', '{"0": "The lower log Kstab (5.6) means [CuCl₄]²⁻ is less stable.", "2": "The less stable complex cannot replace the more stable one under normal conditions.", "3": "The values differ by about 13 log units, a factor of roughly 10¹³."}'),
  ('CHE-0779', 'Transition elements', 'Stereoisomerism', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 28 (§18.9.1)', 'Cisplatin, cis-[Pt(NH₃)₂Cl₂], is used as', '["an anticancer drug", "an antacid", "a water softener", "a fertilizer"]', 0, 'The book notes that cisplatin is an anticancer drug, while its trans isomer, transplatin, does not show this activity.', '{"1": "Antacids are bases such as Mg(OH)₂.", "2": "Water is softened with reagents such as EDTA.", "3": "Cisplatin is a medicine, not a fertilizer."}'),
  ('CHE-0780', 'Transition elements', 'Stereoisomerism', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 28 (§18.9.1)', 'Why is transplatin non-polar while cisplatin is polar?', '["Transplatin contains no chlorine.", "In transplatin the identical ligands are opposite each other, so their bond dipoles cancel.", "Cisplatin is tetrahedral.", "Transplatin is octahedral."]', 1, 'In transplatin the two Cl and two NH₃ ligands are at 180° to each other, so the dipoles cancel. In cisplatin they are at 90°, so a net dipole remains.', '{"0": "Both isomers have two Cl and two NH₃ ligands.", "2": "Both isomers are square planar.", "3": "Both isomers are four-coordinate square planar."}'),
  ('CHE-0781', 'Transition elements', 'Stereoisomerism', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 29 (§18.9.2)', 'Optical isomerism in octahedral complexes is commonly shown by complexes with', '["bidentate ligands, such as [Ni(en)₃]²⁺", "only monodentate ligands of one kind", "a linear geometry", "square planar geometry only"]', 0, 'The book''s example is [Ni(en)₃]²⁺, with three bidentate 1,2-diaminoethane ligands. Its two forms are non-superimposable mirror images.', '{"1": "A complex with six identical monodentate ligands has a plane of symmetry and is not chiral.", "2": "Linear complexes are not chiral.", "3": "The book''s optical isomers are octahedral."}'),
  ('CHE-0782', 'Transition elements', 'Redox reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 30 (§18.10)', 'According to the book, a redox reaction is feasible when', '["E°cell is positive.", "E°cell is negative.", "both half-reactions have negative E°.", "the oxidizing agent has the lower E°."]', 0, 'E°cell = E°(reduction) − E°(oxidation). A positive value means the reaction is feasible. The species with the more positive E° is reduced.', '{"1": "A negative E°cell means the reaction is not feasible as written.", "2": "Feasibility depends on the difference, not the signs of both values.", "3": "The oxidizing agent is the species with the higher (more positive) E°."}'),
  ('CHE-0783', 'Transition elements', 'Redox reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 31 (§18.10.2)', 'In the reaction between acidified MnO₄⁻ (E° = +1.52 V) and Fe²⁺ (Fe³⁺/Fe²⁺, E° = +0.77 V),', '["Fe³⁺ is reduced to Fe²⁺ and Mn²⁺ is oxidized.", "MnO₄⁻ is reduced to Mn²⁺ and Fe²⁺ is oxidized to Fe³⁺.", "MnO₄⁻ is the reducing agent.", "no reaction is feasible."]', 1, 'MnO₄⁻/Mn²⁺ has the more positive E°, so it is reduced; Fe²⁺ is oxidized to Fe³⁺. E°cell = 1.52 − 0.77 = +0.75 V, so the reaction is feasible.', '{"0": "This is the reverse of what the E° values predict.", "2": "MnO₄⁻ gains electrons, so it is the oxidizing agent.", "3": "E°cell is positive, so the reaction is feasible."}'),
  ('CHE-0784', 'Transition elements', 'Redox reactions', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 18 Transition Metals, p. 31 (§18.10.3)', 'Excess KI is added to CuSO₄ solution: 2Cu²⁺ + 4I⁻ → 2CuI + I₂. Although E° values alone suggest the reaction is not feasible, it goes forward because', '["CuI precipitates, removing Cu⁺ and shifting the equilibrium to the right.", "iodine is a stronger reducing agent than copper.", "Cu²⁺ is reduced to copper metal.", "potassium ions catalyse the reaction."]', 0, 'With I₂/I⁻ at +0.54 V and Cu²⁺/Cu⁺ at +0.15 V, E°cell is negative. The white CuI precipitate continuously removes Cu⁺, so by Le Chatelier''s principle the reaction proceeds.', '{"1": "Iodide is the reducing agent here; iodine is the product.", "2": "Copper goes to Cu⁺ in CuI, not to the metal.", "3": "K⁺ is a spectator ion."}'),
  ('CHE-0785', 'Fundamental principles of organic chemistry', 'Catenation', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 36 (§19.1)', 'Catenation is', '["the ability of atoms of the same element to link to each other, forming chains and rings.", "the breaking of a C–C bond by heat.", "the joining of carbon to hydrogen only.", "the formation of ionic bonds by carbon."]', 0, 'The book defines catenation (Latin catena, chain) as self-linkage of atoms of the same element. Carbon''s strong C–C bonds let it form long chains and rings, which explains the huge variety of organic compounds.', '{"1": "That is bond cleavage (cracking), not catenation.", "2": "C–H bonding is not self-linkage.", "3": "Carbon forms covalent bonds in catenation."}'),
  ('CHE-0786', 'Fundamental principles of organic chemistry', 'Classification of hydrocarbons', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 36 (§19.2)', 'The term "aliphatic" comes from a Greek word meaning', '["ring", "chain", "fragrant", "fat"]', 3, 'The book says aliphatic comes from aleiphatos, meaning fat, since fats have open-chain structures.', '{"0": "Aliphatic compounds are open-chain, not rings.", "1": "Catena (Latin) means chain; it gives catenation.", "2": "\"Aromatic\" is linked to fragrance."}'),
  ('CHE-0787', 'Fundamental principles of organic chemistry', 'Classification of hydrocarbons', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 37 (§19.2)', 'Cyclohexane is classed as', '["an aromatic hydrocarbon", "a heterocyclic compound", "an open-chain alkene", "an alicyclic hydrocarbon"]', 3, 'Alicyclic hydrocarbons are cyclic compounds, saturated or unsaturated, that behave like aliphatic ones, such as cycloalkanes and cycloalkenes.', '{"0": "Aromatic hydrocarbons have a benzene ring or similar structure.", "1": "Cyclohexane''s ring contains carbon only.", "2": "Cyclohexane is cyclic and saturated."}'),
  ('CHE-0788', 'Fundamental principles of organic chemistry', 'Functional groups', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 37 (§19.3)', 'Methanol and ethanol are liquids while methane and ethane are gases. The book explains this by', '["the double bond in alcohols.", "the higher molar mass of methane.", "the ionic nature of alcohols.", "the hydroxyl group, which allows hydrogen bonding."]', 3, 'The –OH functional group lets alcohol molecules hydrogen bond with each other, raising melting and boiling points. Alkanes have no functional group and cannot do this.', '{"0": "Simple alcohols have no double bond.", "1": "Methane (16) is lighter than methanol (32); mass does not explain the difference in the book''s account.", "2": "Alcohols are covalent compounds."}'),
  ('CHE-0789', 'Fundamental principles of organic chemistry', 'Functional groups', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 37 (§19.3)', 'According to the book, which class of compounds has no functional group?', '["Alkenes", "Carboxylic acids", "Alkanes and cycloalkanes", "Alcohols"]', 2, 'Alkanes and cycloalkanes have no charged or polar groups and no double or triple bonds, so they have no functional group.', '{"0": "The C=C double bond is the functional group of alkenes.", "1": "Carboxylic acids contain –COOH.", "3": "Alcohols contain –OH."}'),
  ('CHE-0790', 'Fundamental principles of organic chemistry', 'Nomenclature', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 38 (§19.4)', 'In an IUPAC name, the primary suffix (suffix of the stem) shows', '["the family name of the compound.", "the number of carbon atoms.", "the name of a side chain.", "whether the parent chain is saturated or unsaturated (-an, -en, -yn)."]', 3, 'The primary suffix indicates saturation (an) or unsaturation (en, yn). The secondary suffix gives the functional group (family), the stem gives the chain length, and the prefix names substituents.', '{"0": "The family name comes from the secondary suffix.", "1": "The stem or root gives the number of carbon atoms.", "2": "Side chains are named in the prefix."}'),
  ('CHE-0791', 'Fundamental principles of organic chemistry', 'Nomenclature', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 39', 'The IUPAC name of (CH₃)₂CHCH₂CHO is', '["2-methylbutanal", "3-methylbutanone", "3-methylbutanal", "pentanal"]', 2, 'The longest chain including the CHO carbon has four carbons, numbered from the CHO carbon (C-1). The methyl is on C-3: 3-methylbutanal.', '{"0": "Numbering must start from the aldehyde carbon, which puts the methyl on C-3.", "1": "A CHO group at the end of the chain is an aldehyde (-al), not a ketone (-one).", "3": "Pentanal is the straight-chain C₅ aldehyde; here the chain is branched."}'),
  ('CHE-0792', 'Fundamental principles of organic chemistry', 'Nomenclature', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 40', 'The IUPAC name of CH₃COOCH₂CH₃ is', '["propyl methanoate", "methyl propanoate", "ethoxyethanone", "ethyl ethanoate"]', 3, 'Esters are named alkyl alkanoate. The alkyl group on oxygen is ethyl and the acid part, CH₃COO–, is ethanoate.', '{"0": "Propyl methanoate is HCOOCH₂CH₂CH₃.", "1": "Methyl propanoate is CH₃CH₂COOCH₃.", "2": "This is not an IUPAC ester name."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0793', 'Fundamental principles of organic chemistry', 'Nomenclature', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 40', 'Ethers are named in the IUPAC system as', '["alkanols", "alkanals", "alkoxyalkanes", "alkanones"]', 2, 'The book gives alkoxyalkane, e.g. CH₃OCH₂CH₃ is methoxyethane.', '{"0": "Alkanol is the alcohol name.", "1": "Alkanal is the aldehyde name.", "3": "Alkanone is the ketone name."}'),
  ('CHE-0794', 'Fundamental principles of organic chemistry', 'Nomenclature', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 41', 'CH₃CH₂CH₂NHCH₃ is named', '["N-propylmethanamine", "butan-1-amine", "propan-2-amine", "N-methylpropan-1-amine"]', 3, 'This is a secondary amine. The longest chain on N is propyl, and the methyl on nitrogen is shown with the locant N: N-methylpropan-1-amine.', '{"0": "The parent is the longer (propyl) chain, not methyl.", "1": "Butan-1-amine is the primary amine CH₃CH₂CH₂CH₂NH₂.", "2": "Propan-2-amine is a primary amine with NH₂ on C-2."}'),
  ('CHE-0795', 'Fundamental principles of organic chemistry', 'Nomenclature', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 41', 'The IUPAC name of CH₃CN is', '["methyl cyanide only", "ethanamine", "ethanenitrile", "methanenitrile"]', 2, 'Alkyl cyanides are named alkanenitriles, counting the nitrile carbon: CH₃–C≡N has two carbons, so ethanenitrile.', '{"0": "Methyl cyanide is a common name, not the IUPAC name.", "1": "Ethanamine is CH₃CH₂NH₂.", "3": "The nitrile carbon is counted, giving two carbons."}'),
  ('CHE-0796', 'Fundamental principles of organic chemistry', 'Formulae', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 42 (§19.5)', 'Ethanol and methoxymethane share the molecular formula', '["C₂H₄O", "C₂H₆O₂", "CH₄O", "C₂H₆O"]', 3, 'Both contain two C, six H and one O. The molecular formula does not show how the atoms are linked, so two different compounds can share it.', '{"0": "C₂H₄O is ethanal.", "1": "C₂H₆O₂ is ethane-1,2-diol.", "2": "CH₄O is methanol."}'),
  ('CHE-0797', 'Fundamental principles of organic chemistry', 'Formulae', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 42 (§19.5)', 'The empirical formula of butane, C₄H₁₀, is', '["CH₃", "CH₂", "C₂H₅", "C₄H₁₀"]', 2, 'Dividing C₄H₁₀ by the common factor 2 gives the smallest whole-number ratio C₂H₅.', '{"0": "CH₃ is the empirical formula of ethane.", "1": "CH₂ is the empirical formula of alkenes.", "3": "C₄H₁₀ can be simplified, so it is not the empirical formula."}'),
  ('CHE-0798', 'Fundamental principles of organic chemistry', 'Formulae', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 43 (§19.5)', 'In a skeletal (bond-line) formula,', '["every carbon and hydrogen atom is written out.", "only functional groups are shown, without any lines.", "double bonds are not shown.", "C and H symbols and C–H bonds are omitted; each line junction or end is a carbon."]', 3, 'Bonds between carbon atoms are lines meeting at angles, each carbon is assumed to have enough H atoms for four bonds, and double/triple bonds and functional groups are still shown.', '{"0": "That is a displayed formula.", "1": "The carbon skeleton is drawn with lines.", "2": "Double and triple bonds are shown in skeletal formulae."}'),
  ('CHE-0799', 'Fundamental principles of organic chemistry', 'Bond fission', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 44 (§19.7)', 'Homolytic fission of a covalent bond', '["gives ions, because one atom keeps both electrons.", "occurs only in polar bonds.", "shares the bonding electrons equally, producing free radicals.", "forms a carbocation and a carbanion."]', 2, 'In homolysis each atom takes one electron of the shared pair, giving free radicals such as Cl· from Cl₂. The book says it happens when the breaking bond is non-polar.', '{"0": "That describes heterolytic fission.", "1": "Homolysis happens with non-polar bonds; heterolysis with polar ones.", "3": "Carbocations and carbanions come from heterolytic fission."}'),
  ('CHE-0800', 'Fundamental principles of organic chemistry', 'Bond fission', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 45 (§19.7)', 'According to the book, a carbanion is formed when carbon is bonded to a', '["more electronegative atom such as O or N, and the bond breaks heterolytically.", "less electronegative metal such as Li or Mg, and the bond breaks heterolytically.", "hydrogen atom, by homolysis.", "chlorine atom in sunlight."]', 1, 'When carbon is bonded to a metal less electronegative than itself (Li, Mg, Cd), heterolysis leaves the electron pair on carbon, giving a carbanion.', '{"0": "With a more electronegative partner, carbon loses the pair and becomes a carbocation.", "2": "Homolysis gives free radicals, not carbanions.", "3": "Cl₂ in sunlight undergoes homolysis to radicals."}'),
  ('CHE-0801', 'Fundamental principles of organic chemistry', 'Reagents', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 45 (§19.7)', 'An electrophile is a species that', '["donates a pair of electrons to form a new bond.", "accepts a pair of electrons to form a new bond.", "has an unpaired electron only.", "is always a negative ion."]', 1, 'Electrophiles (electron lovers) accept an electron pair; they are positive ions or neutral molecules such as BF₃ or SO₃.', '{"0": "That describes a nucleophile.", "2": "That describes a free radical.", "3": "Electrophiles are positive or neutral; nucleophiles may be negative."}'),
  ('CHE-0802', 'Fundamental principles of organic chemistry', 'Reagents', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 45 (§19.7)', 'Which of these is a nucleophile?', '["BF₃", "NH₃", "NO₂⁺", "CH₃⁺"]', 1, 'NH₃ has a lone pair on nitrogen that it can donate to form a new bond.', '{"0": "BF₃ has an empty orbital on boron and accepts an electron pair (electrophile).", "2": "The nitronium ion is an electrophile.", "3": "A carbocation is an electrophile."}'),
  ('CHE-0803', 'Fundamental principles of organic chemistry', 'Types of reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 46 (§19.7)', 'Ethene + H₂ → ethane over nickel is', '["a substitution reaction", "an addition reaction (and a reduction)", "an elimination reaction", "a hydrolysis"]', 1, 'Two reactants give a single product, so it is addition. Carbon gains hydrogen, so it is also a reduction.', '{"0": "Nothing is replaced; H₂ adds across the double bond.", "2": "Elimination forms a multiple bond; here one is removed.", "3": "No water is involved."}'),
  ('CHE-0804', 'Fundamental principles of organic chemistry', 'Types of reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 46 (§19.7)', 'Bromoethane heated with alcoholic KOH forms ethene. This is', '["nucleophilic substitution", "electrophilic addition", "elimination", "condensation"]', 2, 'H and Br are removed from adjacent carbon atoms, forming a C=C double bond. Elimination is the reverse of addition.', '{"0": "With aqueous KOH, substitution gives ethanol instead.", "1": "Addition would add to a double bond, not form one.", "3": "Condensation joins two molecules."}'),
  ('CHE-0805', 'Fundamental principles of organic chemistry', 'Types of reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 46 (§19.7)', 'Propanone reacts with hydroxylamine to give propanone oxime and water. This is', '["a hydrolysis", "a condensation reaction", "an elimination reaction only", "a free radical substitution"]', 1, 'Two molecules combine into a bigger molecule with loss of a small molecule (H₂O), which is the book''s definition of condensation.', '{"0": "Hydrolysis splits a compound using water; here water is formed.", "2": "Two molecules join, which is more than an elimination.", "3": "No free radicals are involved."}'),
  ('CHE-0806', 'Fundamental principles of organic chemistry', 'Mechanisms', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 47 (§19.8)', 'The reaction of methane with chlorine in diffused sunlight follows', '["nucleophilic addition", "a free radical mechanism", "nucleophilic substitution", "electrophilic addition"]', 1, 'Chlorine molecules split homolytically in light (initiation), radicals react and regenerate radicals (propagation), and radicals combine (termination).', '{"0": "Nucleophilic addition happens at carbonyl groups.", "2": "The attacking species are radicals, not nucleophiles.", "3": "Methane has no double bond for addition."}'),
  ('CHE-0807', 'Fundamental principles of organic chemistry', 'Mechanisms', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 47–48 (§19.8)', 'HCN adding to ethanal to form 2-hydroxypropanenitrile is an example of', '["nucleophilic substitution", "electrophilic addition", "free radical addition", "nucleophilic addition"]', 3, 'The CN⁻ nucleophile attacks the electrophilic (δ+) carbonyl carbon, giving an addition product.', '{"0": "Nothing is substituted; the C=O bond is added across.", "1": "Electrophilic addition happens at C=C double bonds.", "2": "No radicals are involved."}'),
  ('CHE-0808', 'Fundamental principles of organic chemistry', 'Mechanisms', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 48 (§19.8)', 'Ethene + HBr → bromoethane is', '["electrophilic addition", "nucleophilic addition", "free radical substitution", "elimination"]', 0, 'The electrophile (H of HBr) attacks the electron-rich C=C double bond, and Br⁻ then completes the addition.', '{"1": "Nucleophilic addition occurs at carbonyl groups.", "2": "Two reactants form one product, so it is addition.", "3": "A double bond is used up, not formed."}'),
  ('CHE-0809', 'Fundamental principles of organic chemistry', 'Isomerism', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 48 (§19.9)', 'Isomers are compounds that have', '["different molecular formulae but the same properties.", "the same molecular formula but different arrangements of atoms.", "the same structural formula and the same properties.", "the same empirical formula only."]', 1, 'Isomers share the molecular formula but differ in atom arrangement and properties.', '{"0": "Isomers have the same molecular formula.", "2": "Identical structure would mean the same compound.", "3": "Same empirical formula alone is not enough; e.g. C₂H₄ and C₄H₈."}'),
  ('CHE-0810', 'Fundamental principles of organic chemistry', 'Optical isomerism', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 50 (§19.9.1)', 'A chiral carbon atom is one that is', '["part of a double bond.", "bonded to four different atoms or groups.", "bonded to two identical groups.", "in a benzene ring."]', 1, 'A carbon with four different groups has a non-superimposable mirror image, so it can give rise to optical isomers.', '{"0": "A doubly bonded carbon has only three groups.", "2": "Two identical groups give a plane of symmetry at that carbon.", "3": "Ring carbons of benzene have only three groups."}'),
  ('CHE-0811', 'Fundamental principles of organic chemistry', 'Optical isomerism', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 50 (§19.9.1)', 'In lactic acid, CH₃CH(OH)COOH, the four different groups on the chiral carbon are', '["CH₃, H, OH and COOH", "CH₃, OH, OH and COOH", "H, H, OH and COOH", "CH₃, CH₃, H and OH"]', 0, 'The central carbon carries CH₃, H, OH and COOH, all different, so it is chiral and lactic acid has two enantiomers.', '{"1": "There is only one OH on the central carbon.", "2": "The central carbon carries one H and one CH₃.", "3": "There is only one CH₃ group."}'),
  ('CHE-0812', 'Fundamental principles of organic chemistry', 'Optical isomerism', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 51 (§19.9.1)', 'A racemic mixture is', '["a 50 : 50 mixture of two enantiomers, which is optically inactive.", "a single enantiomer that rotates light strongly.", "a meso compound.", "a mixture of cis and trans isomers."]', 0, 'Equal amounts of the (+) and (−) forms rotate light equally in opposite directions, so the mixture is optically inactive. It is shown by (±).', '{"1": "A single enantiomer is optically active.", "2": "A meso compound is a single compound inactive by internal compensation.", "3": "Cis and trans isomers are geometrical, not optical."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0813', 'Fundamental principles of organic chemistry', 'Optical isomerism', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 51 (§19.9.1)', 'Meso-tartaric acid has two chiral carbon atoms but is optically inactive because', '["it has a plane of symmetry, so the rotations of its two halves cancel.", "it is a racemic mixture.", "its chiral carbons are not really chiral.", "it does not dissolve in water."]', 0, 'The two halves are mirror images within one molecule, so one half rotates the light one way and the other half cancels it (internal compensation).', '{"1": "A racemic mixture contains two different molecules; meso is one compound.", "2": "Both carbons do carry four different groups.", "3": "Solubility has nothing to do with optical activity."}'),
  ('CHE-0814', 'Fundamental principles of organic chemistry', 'Optical isomerism', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 51 (§19.9.1)', 'A compound has three different chiral carbon atoms and no plane of symmetry. The maximum number of optical isomers is', '["8", "6", "3", "9"]', 0, 'The maximum number of optical isomers is 2ⁿ, where n is the number of chiral carbons: 2³ = 8.', '{"1": "6 is 2 × n, not 2ⁿ.", "2": "The number is 2ⁿ, not n.", "3": "9 is 3², not 2³."}'),
  ('CHE-0815', 'Fundamental principles of organic chemistry', 'Cis-trans isomerism', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 52 (§19.9.1)', 'Rotation about a C=C double bond is restricted because', '["the carbon atoms are sp³ hybridized.", "the σ bond is very weak.", "the π bond would have to break, which needs about 263 kJ mol⁻¹.", "the molecule is always ionic."]', 2, 'The π bond is formed by parallel overlap of p orbitals; rotating breaks this overlap. The book gives the energy needed as 263 kJ mol⁻¹, too much at room temperature.', '{"0": "The double-bonded carbons are sp² hybridized.", "1": "The σ bond allows rotation; the π bond prevents it.", "3": "Alkenes are covalent molecules."}'),
  ('CHE-0816', 'Fundamental principles of organic chemistry', 'Cis-trans isomerism', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 52 (§19.9.1)', 'Which compound cannot show cis-trans isomerism?', '["2,3-Dimethylbut-2-ene", "Pent-2-ene", "But-2-ene", "1,2-Dichloroethene"]', 0, 'In 2,3-dimethylbut-2-ene each doubly bonded carbon carries two identical CH₃ groups, so no cis-trans isomers exist.', '{"1": "Each double-bond carbon in pent-2-ene has two different groups.", "2": "But-2-ene has H and CH₃ on each double-bond carbon, so it has cis and trans forms.", "3": "Each carbon has H and Cl, so cis and trans forms exist."}'),
  ('CHE-0817', 'Fundamental principles of organic chemistry', 'Cis-trans isomerism', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 52 (Keep in mind)', 'Which statement about cis and trans isomers does the book make?', '["Trans isomers are generally more stable than the corresponding cis isomers.", "They rotate plane-polarized light in opposite directions.", "They have identical physical properties.", "They interconvert freely at room temperature."]', 0, 'Cis and trans isomers differ in physical properties (melting point, boiling point, dipole moment, density) and in stability; trans isomers are usually more stable.', '{"1": "That describes enantiomers.", "2": "Their physical properties differ.", "3": "They cannot interconvert without breaking the π bond."}'),
  ('CHE-0818', 'Fundamental principles of organic chemistry', 'Conformations', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 51 (§19.9.1)', 'The different forms of butane produced by rotation about the C2–C3 single bond are', '["cis-trans isomers", "enantiomers", "conformational isomers, which cannot be separated at room temperature", "structural isomers"]', 2, 'Free rotation about the C–C single bond interconverts these forms, so they are conformations that cannot be isolated at room temperature.', '{"0": "Cis-trans isomers need restricted rotation about a double bond.", "1": "Enantiomers are non-superimposable mirror images that do not interconvert by rotation.", "3": "The atoms are connected in the same order, so they are not structural isomers."}'),
  ('CHE-0819', 'Fundamental principles of organic chemistry', 'Chirality in drugs', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 19 Basics of Organic Chemistry, p. 53 (§19.10)', 'Thalidomide could not be made safe by selling only the (+) isomer because', '["the (+) isomer was itself the cause of birth defects.", "the (+) isomer racemises rapidly in the bloodstream.", "the (−) isomer cannot be separated in the laboratory.", "the drug is achiral."]', 1, 'The book explains that pure (+) thalidomide racemises quickly once it enters the blood (over 50% within 10 minutes), producing the harmful (−) isomer.', '{"0": "The (−) isomer damaged the fetus; the (+) isomer was the effective sedative.", "2": "The problem is racemisation in the body, not separation.", "3": "Thalidomide has a chiral centre and exists as enantiomers."}'),
  ('CHE-0820', 'Organic chemistry', 'Structure of benzene', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 57 (§20.1)', 'According to X-ray studies, the C–C–C bond angles in benzene are', '["109.5°", "120°", "180°", "90°"]', 1, 'Benzene is a planar regular hexagon of six sp² carbon atoms, so all C–C–C and H–C–C angles are 120°.', '{"0": "109.5° is the tetrahedral angle of sp³ carbon.", "2": "180° is the angle at sp carbon.", "3": "90° is not found in the benzene ring."}'),
  ('CHE-0821', 'Organic chemistry', 'Structure of benzene', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 57–58 (§20.1, Table 20.1)', 'All six C–C bonds in benzene are 139 pm long. This value lies between', '["a C–H bond (109 pm) and a C=C bond (133 pm).", "a C=C double bond (133 pm) and a C≡C triple bond (120 pm).", "two different C≡C bonds.", "a C–C single bond (154 pm) and a C=C double bond (133 pm)."]', 3, 'Delocalization makes every C–C bond in benzene equal, with a length between a single and a double bond.', '{"0": "139 pm is longer than both of these.", "1": "139 pm is longer than a C=C double bond, not shorter.", "2": "Benzene has no triple bonds."}'),
  ('CHE-0822', 'Organic chemistry', 'Structure of benzene', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 57 (§20.1)', 'In 1865, the structure of benzene as a six-membered ring with alternate single and double bonds was proposed by', '["Michael Faraday", "August Kekulé", "Linus Pauling", "Friedrich Wöhler"]', 1, 'The book credits the German professor August Kekulé with the cyclic structure of alternating single and double bonds in 1865.', '{"0": "Faraday discovered benzene but did not propose this structure.", "2": "Pauling is linked with resonance theory later, not the 1865 structure.", "3": "Wöhler is known for synthesizing urea."}'),
  ('CHE-0823', 'Organic chemistry', 'Stability and resonance', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 58 (§20.1.1)', 'Cyclohexene releases 120 kJ mol⁻¹ on hydrogenation. Hypothetical cyclohexatriene would be expected to release 360 kJ mol⁻¹, but benzene releases only 208 kJ mol⁻¹. The resonance (delocalization) energy of benzene is', '["152 kJ mol⁻¹", "120 kJ mol⁻¹", "208 kJ mol⁻¹", "568 kJ mol⁻¹"]', 0, '360 − 208 = 152 kJ mol⁻¹. Benzene is more stable than the hypothetical triene by this amount.', '{"1": "120 kJ mol⁻¹ is the heat of hydrogenation of one C=C bond in cyclohexene.", "2": "208 kJ mol⁻¹ is benzene''s actual heat of hydrogenation.", "3": "568 kJ mol⁻¹ is the sum of 360 and 208, not the difference."}'),
  ('CHE-0824', 'Organic chemistry', 'Stability and resonance', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 58 (§20.1.2)', 'In the orbital picture of benzene, the delocalized π system is formed by', '["end-on overlap of sp³ orbitals.", "sideways overlap of six unhybridized 2p orbitals, one from each carbon.", "overlap of sp² orbitals with hydrogen 1s orbitals.", "six separate localized π bonds."]', 1, 'Each carbon uses three sp² orbitals for σ bonds. The remaining 2p orbitals, perpendicular to the ring, overlap sideways to form π clouds above and below the plane.', '{"0": "Benzene carbons are sp², not sp³.", "2": "sp²–1s overlap forms the C–H σ bonds.", "3": "Benzene has three pairs of π electrons delocalized over all six carbons."}'),
  ('CHE-0825', 'Organic chemistry', 'Nomenclature', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 59 (§20.2)', 'The IUPAC-accepted name for C₆H₅NH₂ is', '["phenol", "anisole", "toluene", "aniline (benzenamine)"]', 3, 'Aniline (benzenamine) is one of the common names accepted as an IUPAC base name.', '{"0": "Phenol is C₆H₅OH.", "1": "Anisole is C₆H₅OCH₃.", "2": "Toluene is C₆H₅CH₃."}'),
  ('CHE-0826', 'Organic chemistry', 'Nomenclature', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 60 (§20.2)', 'Using the book''s priority order (–COOH > –CN > –CHO > –COCH₃ > –OH > –NH₂ > –OR > –R), a benzene ring carrying –COOH and –OH at positions 1 and 3 is named', '["3-hydroxybenzoic acid", "3-carboxyphenol", "1-hydroxy-3-benzoic acid", "meta-phenolcarboxylic acid only"]', 0, 'The higher-priority –COOH carbon is C-1, so the parent is benzoic acid and the OH is a 3-hydroxy prefix.', '{"1": "–COOH outranks –OH, so the parent is benzoic acid, not phenol.", "2": "This form does not follow the naming rules.", "3": "The book''s systematic name uses benzoic acid as the parent."}'),
  ('CHE-0827', 'Organic chemistry', 'Nomenclature', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 60 (Did you know)', 'In a disubstituted benzene, the prefix meta- (m-) means the substituents are at positions', '["1,3", "1,2", "1,4", "1,6"]', 0, 'Ortho is 1,2, meta is 1,3 and para is 1,4.', '{"1": "1,2 is ortho.", "2": "1,4 is para.", "3": "1,6 is the same as 1,2 (ortho) by symmetry."}'),
  ('CHE-0828', 'Organic chemistry', 'Reactivity of benzene', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 61 (§20.3)', 'Benzene reacts with bromine by substitution rather than addition because', '["benzene has no π electrons.", "substitution keeps the stable delocalized π system intact in the product.", "addition products are aromatic.", "bromine cannot act as an electrophile."]', 1, 'Addition would destroy the delocalization permanently. In substitution the aromaticity is lost only in the intermediate and is restored when H⁺ is removed.', '{"0": "Benzene has six delocalized π electrons.", "2": "Addition destroys aromaticity.", "3": "Bromine, polarized by a Lewis acid, is the electrophile in bromination."}'),
  ('CHE-0829', 'Organic chemistry', 'Reactivity of benzene', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 61 (§20.3)', 'Compared with alkenes, benzene is', '["more reactive and undergoes electrophilic addition.", "unreactive towards all electrophiles.", "less reactive and undergoes electrophilic substitution.", "reactive only by free radical substitution."]', 2, 'Benzene''s delocalization makes it very stable, so it is less reactive than alkenes and prefers electrophilic substitution to addition.', '{"0": "Alkenes are the more reactive compounds and undergo addition.", "1": "Benzene does react with electrophiles in the presence of suitable catalysts.", "3": "Free radical substitution is typical of alkanes."}'),
  ('CHE-0830', 'Organic chemistry', 'Electrophilic substitution', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 62 (§20.3)', 'Benzene reacts with chlorine or bromine only in the presence of a Lewis acid such as FeBr₃ or AlCl₃ because the Lewis acid', '["reduces the halogen.", "breaks the benzene ring.", "acts as a nucleophile.", "polarizes the halogen and generates a strong electrophile."]', 3, 'The Lewis acid accepts a lone pair from the halogen, polarizing it so that X⁺ (as X–X–AlX₃) can attack the benzene π system.', '{"0": "No reduction of the halogen is involved.", "1": "The ring stays intact in substitution.", "2": "The Lewis acid accepts electrons, so it is not a nucleophile."}'),
  ('CHE-0831', 'Organic chemistry', 'Electrophilic substitution', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 62 (§20.3.1)', 'In electrophilic aromatic substitution, the intermediate formed when the electrophile bonds to a ring carbon is called', '["a carbanion", "a free radical", "a sigma complex (arenium ion)", "an acylium ion"]', 2, 'A new σ bond forms to one ring carbon, leaving four π electrons and a positive charge spread over five carbons. This intermediate is the sigma complex.', '{"0": "The intermediate is positively charged.", "1": "No unpaired electrons are involved.", "3": "The acylium ion RCO⁺ is the electrophile in Friedel–Crafts acylation, not the intermediate."}'),
  ('CHE-0832', 'Organic chemistry', 'Nitration', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 63 (Nitration of benzene)', 'The electrophile in the nitration of benzene is', '["NO₂⁻", "HNO₃", "NO₃⁻", "NO₂⁺ (nitronium ion)"]', 3, 'Concentrated H₂SO₄ and HNO₃ react to form the nitronium ion: H₂SO₄ + HNO₃ → NO₂⁺ + HSO₄⁻ + H₂O.', '{"0": "NO₂⁻ (nitrite) is negatively charged and cannot be an electrophile here.", "1": "HNO₃ itself is the source; it must form NO₂⁺ first.", "2": "Nitrate is a negative ion."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0833', 'Organic chemistry', 'Nitration', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 63 (Nitration of benzene)', 'If benzene is nitrated at temperatures well above 50 °C,', '["no reaction occurs.", "benzene undergoes addition.", "more than one nitro group is likely to be substituted, e.g. 1,3-dinitrobenzene.", "nitrobenzene decomposes to benzene."]', 2, 'The book notes that higher temperatures increase the chance of further nitration; some 1,3-dinitrobenzene forms even at 50 °C.', '{"0": "Nitration still occurs, faster at higher temperature.", "1": "Benzene still undergoes substitution.", "3": "Nitrobenzene does not revert to benzene."}'),
  ('CHE-0834', 'Organic chemistry', 'Friedel–Crafts reactions', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 64 (Friedel–Crafts)', 'Benzene heated with chloroethane and AlCl₃ gives', '["chlorobenzene", "benzoic acid", "phenylethanone", "ethylbenzene"]', 3, 'This Friedel–Crafts alkylation substitutes an ethyl group into the ring: C₆H₆ + CH₃CH₂Cl → C₆H₅CH₂CH₃ + HCl.', '{"0": "Chlorobenzene comes from benzene + Cl₂ with a Lewis acid.", "1": "Benzoic acid comes from side-chain oxidation.", "2": "Phenylethanone comes from acylation with ethanoyl chloride."}'),
  ('CHE-0835', 'Organic chemistry', 'Friedel–Crafts reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 65 (Friedel–Crafts acylation)', 'In Friedel–Crafts acylation, the electrophile formed from an acyl chloride and AlCl₃ is', '["a carbanion", "a nitronium ion", "an acylium ion, RCO⁺", "a chloride ion"]', 2, 'AlCl₃ takes Cl⁻ from RCOCl, forming AlCl₄⁻ and the acylium ion RC≡O⁺, which attacks the ring.', '{"0": "Carbanions are nucleophiles.", "1": "The nitronium ion is the nitration electrophile.", "3": "Cl⁻ is removed to form AlCl₄⁻; it is not the electrophile."}'),
  ('CHE-0836', 'Organic chemistry', 'Friedel–Crafts reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 64–65 (Friedel–Crafts)', 'In both Friedel–Crafts alkylation and acylation, AlCl₃ is', '["used up completely.", "a nucleophile.", "converted into benzene.", "regenerated at the end, so it acts as a catalyst."]', 3, 'The proton lost from the intermediate combines with Cl⁻ from AlCl₄⁻ to form HCl, which regenerates AlCl₃.', '{"0": "It is regenerated and acts as a catalyst.", "1": "AlCl₃ is a Lewis acid (electron pair acceptor).", "2": "AlCl₃ contains no carbon."}'),
  ('CHE-0837', 'Organic chemistry', 'Directing effects', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 65–66 (§20.4)', 'Which group is an ortho-para director and ring activator?', '["–NO₂", "–CN", "–OH", "–CHO"]', 2, 'Groups that donate electrons to the ring, such as –OH, –OR, –R and –NR₂, activate it and direct incoming electrophiles to the 2 and 4 positions.', '{"0": "–NO₂ withdraws electrons and is meta-directing.", "1": "–CN is meta-directing.", "3": "The C=O group is meta-directing."}'),
  ('CHE-0838', 'Organic chemistry', 'Directing effects', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 66 (§20.4)', 'Methylbenzene reacts with chlorine in the presence of AlCl₃ (no UV light) to give mainly', '["3-chloromethylbenzene", "(chloromethyl)benzene, C₆H₅CH₂Cl", "a mixture of 2-chloro- and 4-chloromethylbenzene", "hexachlorocyclohexane"]', 2, 'The methyl group is electron-donating and directs substitution to the 2 and 4 positions of the ring.', '{"0": "The meta product is only a minor by-product.", "1": "Side-chain chlorination needs UV light, not a Lewis acid.", "3": "Addition of chlorine needs UV light and heat without a catalyst."}'),
  ('CHE-0839', 'Organic chemistry', 'Directing effects', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 66 (§20.4)', 'Chlorination of nitrobenzene with Cl₂/AlCl₃ gives mainly', '["2-chloronitrobenzene", "chlorobenzene", "4-chloronitrobenzene", "3-chloronitrobenzene (meta)"]', 3, '–NO₂ withdraws electrons, deactivates the ring and directs the electrophile to the meta position.', '{"0": "–NO₂ is not ortho-directing.", "1": "The nitro group is not replaced.", "2": "–NO₂ is not para-directing."}'),
  ('CHE-0840', 'Organic chemistry', 'Directing effects', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 66 (§20.4)', 'Which reaction sequence gives 3-chloronitrobenzene from benzene?', '["Nitrate first (conc. HNO₃/H₂SO₄), then chlorinate (Cl₂/AlCl₃).", "Chlorinate first (Cl₂/AlCl₃), then nitrate.", "Nitrate, then react with HCl.", "Chlorinate under UV light, then nitrate."]', 0, 'The nitro group directs meta, so nitrating first and then chlorinating puts Cl at position 3. Chlorinating first would give ortho and para nitro products, since –Cl directs ortho/para.', '{"1": "Chlorine directs incoming groups ortho/para, giving 2- and 4-chloronitrobenzene.", "2": "HCl does not chlorinate the ring.", "3": "UV light causes addition of chlorine to benzene, not substitution."}'),
  ('CHE-0841', 'Organic chemistry', 'Combustion', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 66 (§20.4.1)', 'Benzene burns in air with a smoky flame. The balanced equation for complete combustion is', '["2C₆H₆ + 15O₂ → 12CO₂ + 6H₂O", "C₆H₆ + 6O₂ → 6CO₂ + 3H₂", "2C₆H₆ + 9O₂ → 12CO + 6H₂O", "C₆H₆ + 3O₂ → 6C + 3H₂O"]', 0, 'Carbon: 12 = 12; hydrogen: 12 = 12; oxygen: 30 = 24 + 6. The smoky flame is used as a test for aromatic compounds.', '{"1": "Complete combustion gives water, not H₂.", "2": "This gives CO (incomplete combustion), and oxygen is not balanced.", "3": "This shows soot, not complete combustion."}'),
  ('CHE-0842', 'Organic chemistry', 'Side-chain oxidation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 67 (§20.4.2)', 'Methylbenzene (toluene) is heated with alkaline KMnO₄. The organic product (after acidification) is', '["benzene", "benzoic acid", "benzyl alcohol", "phenol"]', 1, 'Side-chain oxidation converts the alkyl group into –COOH, leaving the benzene ring intact.', '{"0": "The ring is kept and the side chain is oxidized, not removed.", "2": "The book gives oxidation all the way to the carboxylic acid.", "3": "Phenol has –OH on the ring; the methyl carbon becomes –COOH."}'),
  ('CHE-0843', 'Organic chemistry', 'Side-chain oxidation', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 67 (§20.4.2)', 'Which compound does NOT decolourize hot KMnO₄ by side-chain oxidation?', '["Ethylbenzene", "Isopropylbenzene", "tert-Butylbenzene", "Methylbenzene"]', 2, 'Side-chain oxidation needs at least one benzylic hydrogen. In tert-butylbenzene the benzylic carbon carries three methyl groups and no hydrogen, so there is no reaction.', '{"0": "Ethylbenzene has two benzylic hydrogens.", "1": "Isopropylbenzene has one benzylic hydrogen.", "3": "Methylbenzene has three benzylic hydrogens."}'),
  ('CHE-0844', 'Organic chemistry', 'Side-chain oxidation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 67 (§20.4.2)', 'Propylbenzene is oxidized by hot alkaline KMnO₄. Regardless of the side-chain length, the product is', '["benzoic acid", "phenylpropanoic acid", "phenylethanoic acid", "propanoic acid"]', 0, 'The book says any alkyl group with a benzylic hydrogen is oxidized to a single –COOH group on the ring, giving benzoic acid.', '{"1": "The whole side chain is cut back to one carboxyl carbon.", "2": "The chain is not kept at two carbons.", "3": "The benzene ring stays in the product."}'),
  ('CHE-0845', 'Organic chemistry', 'Addition reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 67–68 (§20.4.3)', 'Complete hydrogenation of benzene gives', '["cyclohexene", "cyclohexane", "hexane", "cyclohexadiene"]', 1, 'Adding three moles of H₂ over finely divided nickel (about 150 °C, higher pressure) saturates the ring to cyclohexane.', '{"0": "Cyclohexene results from adding only one mole of H₂.", "2": "The ring is not opened.", "3": "Cyclohexadiene results from adding only two moles of H₂."}'),
  ('CHE-0846', 'Organic chemistry', 'Addition reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 68 (§20.4.3)', 'Benzene and chlorine react in UV light and heat, with no catalyst, to give', '["1,2,3,4,5,6-hexachlorocyclohexane", "chlorobenzene", "1,3-dichlorobenzene", "hexachlorobenzene"]', 0, 'Without a Lewis acid but with UV light and heat, three Cl₂ molecules add across the ring: C₆H₆ + 3Cl₂ → C₆H₆Cl₆.', '{"1": "Chlorobenzene forms by substitution with a Lewis acid catalyst.", "2": "Dichlorobenzenes come from further substitution with a catalyst.", "3": "Hexachlorobenzene, C₆Cl₆, would be substitution of all H atoms; here each carbon still carries H."}'),
  ('CHE-0847', 'Organic chemistry', 'Addition reactions', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 68 (§20.4.3)', 'Hydrogenation of benzene is exothermic overall but needs a catalyst and higher pressure because', '["it is endothermic.", "it has a high activation barrier, since the delocalization must be destroyed.", "hydrogen is unreactive with all compounds.", "cyclohexane is unstable."]', 1, 'The new C–H bonds release energy, but breaking the stable delocalized system gives a high activation energy, so finely divided nickel and pressure are used.', '{"0": "The book says the reactions are exothermic overall.", "2": "Hydrogen adds readily to alkenes over nickel.", "3": "Cyclohexane is a stable, useful solvent."}'),
  ('CHE-0848', 'Organic chemistry', 'Polycyclic arenes', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 20 Aromatic Hydrocarbons, p. 60 (§20.2)', 'Naphthalene has the molecular formula', '["C₆H₆", "C₁₀H₈", "C₁₄H₁₀", "C₁₀H₁₀"]', 1, 'Naphthalene has two fused benzene rings: C₁₀H₈. Anthracene and phenanthrene are C₁₄H₁₀.', '{"0": "C₆H₆ is benzene.", "2": "C₁₄H₁₀ is anthracene or phenanthrene.", "3": "C₁₀H₁₀ has two hydrogens too many for two fused aromatic rings."}'),
  ('CHE-0849', 'Alkyl halides', 'Classification', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 73', '2-Chloro-2-methylpropane, (CH₃)₃CCl, is a', '["primary halogenoalkane", "secondary halogenoalkane", "tertiary halogenoalkane", "halogenoarene"]', 2, 'The carbon bearing Cl is bonded to three other carbon atoms, so it is tertiary.', '{"0": "A primary halogenoalkane has the halogen on a carbon bonded to one or no other carbons.", "1": "A secondary one has the halogen on a carbon bonded to two other carbons.", "3": "A halogenoarene has the halogen on a benzene ring."}'),
  ('CHE-0850', 'Alkyl halides', 'Classification', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 73', 'Which is a secondary halogenoalkane?', '["1-Chloropropane", "Chloromethane", "2-Chlorobutane", "2-Chloro-2-methylpropane"]', 2, 'In 2-chlorobutane the C–Cl carbon is bonded to two other carbon atoms (C-1 and C-3).', '{"0": "In 1-chloropropane the C–Cl carbon is bonded to only one carbon (primary).", "1": "Chloromethane''s carbon has no other carbons (primary by the book''s definition).", "3": "This is tertiary."}'),
  ('CHE-0851', 'Alkyl halides', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 74 (§21.1)', 'Thionyl chloride (with pyridine) is especially useful for converting an alcohol into a chloroalkane because', '["it gives an alkene as the by-product.", "it works without any reaction.", "the by-products SO₂ and HCl are gases that escape, leaving a pure product.", "it produces phosphorous acid."]', 2, 'ROH + SOCl₂ → RCl + SO₂ + HCl. Both by-products are gases, so the chloroalkane is left pure.', '{"0": "No alkene is formed in this method.", "1": "A reaction does take place.", "3": "H₃PO₃ comes from PX₃ reagents, not SOCl₂."}'),
  ('CHE-0852', 'Alkyl halides', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 74 (§21.1)', 'Ethanol reacts with PBr₃ to give bromoethane and', '["H₃PO₄", "HBr only", "POBr₃", "H₃PO₃"]', 3, '3CH₃CH₂OH + PBr₃ → 3CH₃CH₂Br + H₃PO₃ (phosphorous acid).', '{"0": "H₃PO₄ is phosphoric acid, not produced here.", "1": "The phosphorus ends up in H₃PO₃.", "2": "POCl₃ (and HCl) form with PCl₅; PBr₃ gives H₃PO₃."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0853', 'Alkyl halides', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 74 (§21.1)', 'When ethanol is converted to chloroethane using HCl, ZnCl₂ is added as', '["a reactant that supplies chlorine", "an oxidizing agent", "a catalyst", "a solvent"]', 2, 'The book says ZnCl₂ acts as a catalyst in the reaction of alcohols with halogen acids.', '{"0": "HCl supplies the chlorine.", "1": "No oxidation takes place.", "3": "It is used in small amounts as a catalyst."}'),
  ('CHE-0854', 'Alkyl halides', 'Preparation', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 74 (§21.1)', 'To prepare an iodoalkane from an alcohol using KI and an acid, phosphoric acid is used rather than concentrated sulphuric acid because', '["phosphoric acid is the source of iodine.", "phosphoric acid is a stronger acid.", "sulphuric acid does not react with KI.", "concentrated H₂SO₄ would oxidize iodide ions to iodine."]', 3, 'Concentrated H₂SO₄ oxidizes I⁻ to I₂, wasting the iodide. Phosphoric acid is much less likely to do this.', '{"0": "Iodine comes from KI.", "1": "Phosphoric acid is a weaker acid than sulphuric acid.", "2": "Sulphuric acid does react with KI, giving HI and then oxidizing it."}'),
  ('CHE-0855', 'Alkyl halides', 'Reactivity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 75 (Table 21.1)', 'The book gives C–X bond energies of C–F 467, C–Cl 346, C–Br 290 and C–I 228 kJ mol⁻¹. The main reason fluoroalkanes hardly react under ordinary conditions is', '["fluoroalkanes are ionic.", "the low electronegativity of fluorine.", "the very strong C–F bond.", "fluorine is a large atom."]', 2, 'Bond strength is the main factor in reactivity: the strongest bond (C–F) is the hardest to break.', '{"0": "Fluoroalkanes are covalent compounds.", "1": "Fluorine is the most electronegative element.", "3": "Fluorine is the smallest halogen atom."}'),
  ('CHE-0856', 'Alkyl halides', 'Reactivity', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 75 (Table 21.1)', 'Using Table 21.1, how much more energy is needed to break a C–Cl bond than a C–I bond?', '["118 kJ mol⁻¹", "56 kJ mol⁻¹", "121 kJ mol⁻¹", "574 kJ mol⁻¹"]', 0, '346 − 228 = 118 kJ mol⁻¹.', '{"1": "56 kJ mol⁻¹ is the C–Cl minus C–Br difference (346 − 290).", "2": "121 kJ mol⁻¹ is the C–F minus C–Cl difference (467 − 346).", "3": "574 kJ mol⁻¹ is the sum, not the difference."}'),
  ('CHE-0857', 'Alkyl halides', 'SN2', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 76 (§21.3.1)', 'In an SN2 reaction, the nucleophile attacks', '["from the same side as the leaving group.", "the halogen atom directly.", "only after a carbocation has formed.", "from the side opposite to the leaving group, in a single step."]', 3, 'Bond making and bond breaking happen together in one step, and the nucleophile approaches from the back side, opposite the leaving group.', '{"0": "Backside attack is the feature of SN2.", "1": "The nucleophile attacks the electrophilic carbon, not the halogen.", "2": "A carbocation intermediate belongs to the SN1 mechanism."}'),
  ('CHE-0858', 'Alkyl halides', 'SN2', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 76–77 (§21.3.1)', 'For the SN2 reaction of bromomethane with OH⁻, doubling the concentration of OH⁻ while keeping bromomethane constant', '["has no effect on the rate.", "halves the rate.", "doubles the rate.", "quadruples the rate."]', 2, 'Rate = k[alkyl halide][nucleophile]. The reaction is first order in OH⁻, so doubling [OH⁻] doubles the rate.', '{"0": "That would be true for SN1, where rate depends only on the alkyl halide.", "1": "Increasing a reactant concentration does not slow this reaction.", "3": "Quadrupling would need second order in OH⁻ or both concentrations doubled."}'),
  ('CHE-0859', 'Alkyl halides', 'SN1', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 77 (§21.3.1)', 'In the SN1 mechanism, the rate-determining step is', '["the attack of the nucleophile on the carbocation.", "the slow ionization of the alkyl halide to form a carbocation.", "a single step with both reactants.", "removal of a β-hydrogen."]', 1, 'Breaking the C–X bond to form the carbocation is the slow step; combination of the carbocation with the nucleophile is fast.', '{"0": "Combination of ions is the fast second step.", "2": "That describes SN2.", "3": "Removal of a β-hydrogen is part of elimination."}'),
  ('CHE-0860', 'Alkyl halides', 'SN1', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 77 (§21.3.1)', 'Tertiary halogenoalkanes react by the SN1 mechanism because', '["they cannot ionize.", "they have no β-hydrogens.", "their C–X bond is the strongest.", "they form stable tertiary carbocations and their bulky groups block backside attack."]', 3, 'Three alkyl groups stabilize the carbocation by their +I effect and also hinder a nucleophile approaching from the back.', '{"0": "SN1 depends on ionization.", "1": "Tertiary halides do have β-hydrogens; this is not the reason.", "2": "Bond strength depends mainly on the halogen, not on primary/tertiary."}'),
  ('CHE-0861', 'Alkyl halides', 'SN1', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 77', 'Which carbocation is the most stable?', '["CH₃⁺", "CH₃CH₂⁺", "(CH₃)₂CH⁺", "(CH₃)₃C⁺"]', 3, 'Stability falls tertiary > secondary > primary > methyl as the positive inductive (+I) effect of attached alkyl groups decreases.', '{"0": "The methyl carbocation is the least stable.", "1": "This primary carbocation has only one alkyl group.", "2": "This secondary carbocation has two alkyl groups, less stabilization than tertiary."}'),
  ('CHE-0862', 'Alkyl halides', 'Elimination', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 78 (§21.3.2)', 'In β-elimination from a halogenoalkane, the atoms removed are', '["two halogens from the same carbon.", "the halogen and a hydrogen from the adjacent (β) carbon.", "two hydrogens from the α-carbon.", "a hydrogen and an oxygen."]', 1, 'A base removes the hydrogen on the β-carbon, and the halogen leaves from the α-carbon, forming a C=C double bond.', '{"0": "One halogen and one hydrogen are removed.", "2": "The hydrogen is taken from the β-carbon, not the α-carbon.", "3": "No oxygen is removed from the substrate."}'),
  ('CHE-0863', 'Alkyl halides', 'Elimination', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 78–79 (§21.3.2)', '2-Bromo-2-methylpropane undergoes E1 elimination. The alkene formed is', '["but-1-ene", "2-methylpropene", "propene", "but-2-ene"]', 1, 'The tertiary carbocation (CH₃)₃C⁺ loses a proton from a methyl group, giving (CH₃)₂C=CH₂, 2-methylpropene.', '{"0": "But-1-ene has an unbranched chain.", "2": "Propene has only three carbons.", "3": "But-2-ene has an unbranched chain."}'),
  ('CHE-0864', 'Alkyl halides', 'Reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 79 (§21.4)', 'Bromoethane heated with aqueous NaOH gives mainly ___, while with NaOH in ethanol it gives mainly ___.', '["ethene; ethanol", "ethanol; ethene", "ethane; ethanol", "ethanol; ethane"]', 1, 'In aqueous conditions OH⁻ acts mainly as a nucleophile (substitution → ethanol). In ethanol it acts mainly as a base (elimination → ethene).', '{"0": "The conditions are swapped.", "2": "Ethane is not a product of either reaction.", "3": "Elimination gives ethene, not ethane."}'),
  ('CHE-0865', 'Alkyl halides', 'Reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 79 (§21.4)', 'Bromoethane reacts with ethanolic KCN under reflux to give propanenitrile rather than an alkene because', '["CN⁻ is a strong nucleophile but a weak base.", "CN⁻ is a strong base.", "KCN is insoluble in ethanol.", "the reaction is an elimination."]', 0, 'The book explains that cyanide prefers substitution because it is a strong nucleophile and only a weak base. The product has one more carbon: CH₃CH₂CN.', '{"1": "CN⁻ is a weak base, which is why elimination is not favoured.", "2": "The reaction is done in ethanolic solution.", "3": "It is a substitution."}'),
  ('CHE-0866', 'Alkyl halides', 'Reactions', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 79 (§21.4)', 'Why is the KCN reaction useful in organic synthesis?', '["It shortens the chain by one carbon.", "It lengthens the carbon chain by one carbon.", "It converts an alkyl halide into an alkane.", "It removes the halogen without adding anything."]', 1, 'Bromoethane (C₂) becomes propanenitrile (C₃), so the reaction adds one carbon to the chain.', '{"0": "A carbon is added, not removed.", "2": "The product is a nitrile, not an alkane.", "3": "CN replaces the halogen."}'),
  ('CHE-0867', 'Alkyl halides', 'Reactions', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 79–80 (§21.4)', 'When bromoethane reacts with ammonia, a mixture of amines forms because', '["each amine product is itself a nucleophile that can react with more bromoethane.", "ammonia is a strong acid.", "bromoethane eliminates to give ethene.", "amines are oxidized."]', 0, 'Ethanamine attacks more bromoethane to give diethylamine, then triethylamine, and finally a quaternary ammonium salt if bromoethane is in excess.', '{"1": "Ammonia acts as a base and nucleophile, not as a strong acid.", "2": "The products described are amines, from substitution.", "3": "No oxidation is involved."}'),
  ('CHE-0868', 'Alkyl halides', 'Reactions', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 80 (§21.4)', 'With a large excess of bromoethane, the final product of its reaction with ammonia is', '["ethanamine", "N-ethylethanamine", "N,N-diethylethanamine", "a quaternary ammonium salt, (C₂H₅)₄N⁺Br⁻"]', 3, 'Excess bromoethane keeps alkylating the nitrogen until all four positions carry ethyl groups.', '{"0": "Ethanamine is the first product, favoured with excess ammonia.", "1": "Diethylamine reacts further with excess bromoethane.", "2": "Triethylamine reacts further with excess bromoethane."}'),
  ('CHE-0869', 'Alkyl halides', 'Silver nitrate test', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 80 (§21.4)', 'In the test with aqueous silver nitrate in ethanol, ethanol is added because', '["it dissolves the halogenoalkane.", "it is the nucleophile that releases the halide.", "it forms the precipitate.", "it oxidizes the halide."]', 0, 'Halogenoalkanes do not dissolve well in water, so ethanol helps dissolve them. Water is the nucleophile that frees the halide ion.', '{"1": "Water acts as the nucleophile.", "2": "The precipitate is the silver halide.", "3": "No oxidation is involved."}'),
  ('CHE-0870', 'Alkyl halides', 'Silver nitrate test', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 80 (§21.4)', 'A halogenoalkane is warmed with aqueous ethanolic AgNO₃ and slowly gives a cream-yellow precipitate. The halogen present is', '["bromine", "chlorine", "iodine", "fluorine"]', 0, 'The book lists AgCl as white, AgBr as cream yellow and AgI as bright yellow.', '{"1": "AgCl is white.", "2": "AgI is bright yellow and forms fastest.", "3": "AgF is soluble, and the C–F bond hardly reacts."}'),
  ('CHE-0871', 'Alkyl halides', 'Halogenoarenes', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 81 (§21.5)', 'Chlorobenzene is prepared by reacting benzene with chlorine in the presence of', '["anhydrous FeCl₃", "UV light", "aqueous NaOH", "ethanolic KCN"]', 0, 'This is electrophilic aromatic substitution, carried out at room temperature with FeCl₃ (or FeBr₃ for bromine) as catalyst.', '{"1": "UV light causes addition to benzene, not substitution.", "2": "NaOH does not chlorinate benzene.", "3": "KCN is used to make nitriles from halogenoalkanes."}'),
  ('CHE-0872', 'Alkyl halides', 'Halogenoarenes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 81 (§21.5.1)', 'Chlorobenzene is much less reactive than chloroethane towards nucleophiles because', '["the C–Cl bond in chlorobenzene is ionic.", "a lone pair on Cl is delocalized into the ring, giving the C–Cl bond partial double-bond character.", "chlorobenzene has no chlorine lone pairs.", "chloroethane has a stronger C–Cl bond."]', 1, 'Delocalization of a chlorine lone pair into the aromatic ring strengthens the C–Cl bond, making it harder to break.', '{"0": "The C–Cl bond is covalent.", "2": "Chlorine has lone pairs; one of them is delocalized.", "3": "The bond in chlorobenzene is the stronger one."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0873', 'Alkyl halides', 'Uses', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 21 Halogenoalkanes, p. 73', 'Halothane is used as', '["a refrigerant only", "an inhalation anaesthetic", "a pesticide", "a fire-retardant polymer"]', 1, 'The book describes halothane as a halogenated hydrocarbon used as a powerful inhalation anaesthetic.', '{"0": "CFCs were used as refrigerants.", "2": "DDT is given as a pesticide.", "3": "PVC and PTFE are the polymers mentioned."}'),
  ('CHE-0874', 'Alcohols and phenols', 'Classification', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 86 (§22.1)', 'Glycerol, propane-1,2,3-triol, is classified as', '["a monohydric alcohol", "a tertiary alcohol only", "a phenol", "a polyhydric alcohol"]', 3, 'Alcohols are monohydric or polyhydric depending on the number of –OH groups. Glycerol has three.', '{"0": "Monohydric alcohols have one –OH group.", "1": "Glycerol has two primary and one secondary –OH; it is classed by its three OH groups as polyhydric.", "2": "Phenols have –OH on a benzene ring."}'),
  ('CHE-0875', 'Alcohols and phenols', 'Classification', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 86–87 (§22.1)', 'An alcohol with the general formula R₂CHOH is', '["primary", "tertiary", "secondary", "a phenol"]', 2, 'The carbon carrying –OH is bonded to two alkyl groups, so it is a secondary (2°) alcohol.', '{"0": "Primary alcohols are RCH₂OH.", "1": "Tertiary alcohols are R₃COH.", "3": "Phenols have –OH on an aromatic ring."}'),
  ('CHE-0876', 'Alcohols and phenols', 'Acidity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 87 (§22.2)', 'Ethanol is a weaker acid than water because', '["ethanol is more polar than water.", "ethanol has no O–H bond.", "the ethoxide ion is stabilized by delocalization.", "the ethyl group donates electron density, destabilizing the ethoxide ion."]', 3, 'The alkyl group''s positive inductive effect pushes electron density onto oxygen in RO⁻, so it readily takes back H⁺ and the equilibrium lies further left than for water.', '{"0": "Polarity is not the book''s reason.", "1": "Ethanol does have an O–H bond.", "2": "Delocalization stabilizes phenoxide, not ethoxide."}'),
  ('CHE-0877', 'Alcohols and phenols', 'Acidity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 88 (§22.2)', 'Which order of acid strength is given in the book?', '["ethanol > water > phenol", "water > phenol > ethanol", "phenol > water > ethanol", "water > ethanol > phenol"]', 2, 'Phenol is the most acidic because phenoxide is stabilized by delocalization; ethanol is the least because the alkyl group destabilizes ethoxide.', '{"0": "This is the reverse of the book''s order.", "1": "Phenol is more acidic than water.", "3": "Phenol is the most acidic of the three."}'),
  ('CHE-0878', 'Alcohols and phenols', 'Acidity', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 88 (§22.2)', 'Phenol is more acidic than ethanol because', '["the benzene ring donates electrons to oxygen.", "phenol has more hydrogen atoms.", "phenol forms hydrogen bonds and ethanol does not.", "a lone pair on the phenoxide oxygen is delocalized into the ring, stabilizing the ion."]', 3, 'Delocalization spreads the negative charge into the ring, so the phenoxide ion holds H⁺ less strongly and does not readily re-form phenol.', '{"0": "Oxygen''s lone pair is delocalized into the ring, which lowers charge on oxygen.", "1": "Number of hydrogens does not determine acidity.", "2": "Both phenol and ethanol form hydrogen bonds."}'),
  ('CHE-0879', 'Alcohols and phenols', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 88 (§22.3)', 'Ethanol is made industrially by the electrophilic addition of steam to ethene using', '["aqueous NaOH", "nickel as catalyst", "concentrated phosphoric acid as catalyst", "cold dilute KMnO₄"]', 2, 'CH₂=CH₂ + H₂O(g) → CH₃CH₂OH, with H₃PO₄ as catalyst and heat.', '{"0": "NaOH converts halogenoalkanes to alcohols.", "1": "Nickel catalyses hydrogenation, not hydration.", "3": "Cold dilute KMnO₄ gives a diol."}'),
  ('CHE-0880', 'Alcohols and phenols', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 88 (§22.3)', 'Ethene reacts with cold, dilute KMnO₄ to give', '["ethanol", "ethane-1,2-diol", "ethanoic acid", "ethanal"]', 1, 'The mild oxidizing agent adds two –OH groups across the double bond, giving the diol (glycol).', '{"0": "Ethanol needs hydration with steam and H₃PO₄.", "2": "Ethanoic acid would need stronger oxidation.", "3": "Ethanal is formed by oxidation of ethanol."}'),
  ('CHE-0881', 'Alcohols and phenols', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 89 (§22.3)', 'Reduction of propanone with NaBH₄ or LiAlH₄ gives', '["propan-1-ol", "propan-2-ol", "propanal", "propane"]', 1, 'Ketones are reduced to secondary alcohols: CH₃COCH₃ + 2[H] → CH₃CH(OH)CH₃.', '{"0": "Propan-1-ol is the primary alcohol from propanal.", "2": "Propanal is an aldehyde, not a reduction product of a ketone.", "3": "These reagents stop at the alcohol."}'),
  ('CHE-0882', 'Alcohols and phenols', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 89 (§22.3)', 'Which reagent reduces a carboxylic acid such as ethanoic acid to a primary alcohol?', '["NaBH₄", "LiAlH₄", "acidified K₂Cr₂O₇", "dilute HCl"]', 1, 'The book gives LiAlH₄ for reducing carboxylic acids: CH₃COOH + 4[H] → CH₃CH₂OH + H₂O.', '{"0": "The book uses NaBH₄ for aldehydes and ketones only.", "2": "Dichromate is an oxidizing agent.", "3": "Dilute HCl does not reduce acids."}'),
  ('CHE-0883', 'Alcohols and phenols', 'Reactions of alcohols', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 89 (§22.4)', 'The complete combustion of ethanol is', '["2C₂H₅OH + 7O₂ → 4CO₂ + 6H₂O", "C₂H₅OH + 2O₂ → 2CO₂ + 3H₂", "C₂H₅OH + O₂ → 2CO + 3H₂O", "C₂H₅OH + 3O₂ → 2CO₂ + 3H₂O"]', 3, 'Carbon 2 = 2, hydrogen 6 = 6, oxygen 1 + 6 = 4 + 3. The reaction releases 1367 kJ mol⁻¹, which is why ethanol is used as a fuel.', '{"0": "Oxygen is not balanced: 2 + 14 = 16 on the left but 8 + 6 = 14 on the right.", "1": "Combustion gives water, not hydrogen.", "2": "This is incomplete combustion and is not balanced."}'),
  ('CHE-0884', 'Alcohols and phenols', 'Reactions of alcohols', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 90 (§22.4)', 'Sodium reacts with ethanol to give', '["sodium ethoxide and oxygen", "sodium hydroxide and ethene", "sodium ethoxide and hydrogen, less vigorously than with water", "no reaction"]', 2, '2CH₃CH₂OH + 2Na → 2CH₃CH₂ONa + H₂. The reaction is gentler than sodium with water.', '{"0": "Hydrogen, not oxygen, is given off.", "1": "No alkene is formed.", "3": "Sodium does react, and the bubbles are a test for –OH."}'),
  ('CHE-0885', 'Alcohols and phenols', 'Reactions of alcohols', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 90 (§22.4)', 'When a primary or secondary alcohol is oxidized by acidified K₂Cr₂O₇, the colour changes from', '["green to orange", "orange to green", "purple to colourless", "colourless to yellow"]', 1, 'Orange Cr₂O₇²⁻ is reduced to green Cr³⁺.', '{"0": "The colours are reversed.", "2": "Purple to colourless is the change for acidified KMnO₄.", "3": "This is not the dichromate colour change."}'),
  ('CHE-0886', 'Alcohols and phenols', 'Reactions of alcohols', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 90–91 (§22.4)', 'Which alcohol gives no colour change with acidified K₂Cr₂O₇?', '["Propan-1-ol", "Propan-2-ol", "2-Methylpropan-2-ol", "Ethanol"]', 2, '2-Methylpropan-2-ol is tertiary: the carbon carrying –OH has no hydrogen, so it is not oxidized.', '{"0": "Propan-1-ol (primary) is oxidized to propanal and then propanoic acid.", "1": "Propan-2-ol (secondary) is oxidized to propanone.", "3": "Ethanol (primary) is oxidized to ethanal."}'),
  ('CHE-0887', 'Alcohols and phenols', 'Reactions of alcohols', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 90 (§22.4)', 'Oxidation of propan-2-ol by acidified dichromate gives', '["propanal", "propanone", "propanoic acid", "propene"]', 1, 'Secondary alcohols are oxidized only as far as ketones: CH₃CH(OH)CH₃ + [O] → CH₃COCH₃ + H₂O.', '{"0": "Propanal comes from the primary alcohol propan-1-ol.", "2": "Propanoic acid comes from further oxidation of propanal.", "3": "Propene comes from dehydration."}'),
  ('CHE-0888', 'Alcohols and phenols', 'Reactions of alcohols', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 91 (§22.4)', 'Ethanol passed over heated Al₂O₃ gives', '["ethanoic acid", "ethanal, by oxidation", "ethoxyethane only", "ethene, by dehydration"]', 3, 'Dehydration removes a water molecule (an elimination): CH₃CH₂OH → CH₂=CH₂ + H₂O.', '{"0": "No oxidation takes place.", "1": "Al₂O₃ is a dehydrating agent, not an oxidizing agent.", "2": "The book gives the alkene as the product."}'),
  ('CHE-0889', 'Alcohols and phenols', 'Reactions of alcohols', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 89 (Keep in mind)', 'Why must potassium dichromate(VI) be acidified to act as an oxidizing agent for alcohols?', '["The acid makes dichromate green.", "The acid oxidizes the alcohol directly.", "Its reduction needs H⁺ ions, which the acid supplies.", "Acid dissolves the alcohol."]', 2, 'Cr₂O₇²⁻ + 14H⁺ + 6e⁻ → 2Cr³⁺ + 7H₂O. The book notes the reduction requires hydrogen ions.', '{"0": "Green Cr³⁺ forms only when dichromate is reduced.", "1": "Dilute acid alone does not oxidize the alcohol.", "3": "Lower alcohols dissolve in water anyway."}'),
  ('CHE-0890', 'Alcohols and phenols', 'Phenol', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 92 (§22.5)', 'Phenol was historically known as', '["glycol", "wood spirit", "grain alcohol", "carbolic acid"]', 3, 'The book says phenol is also known as carbolic acid and was used in carbolic soap.', '{"0": "Glycol is ethane-1,2-diol.", "1": "Wood spirit is an old name for methanol.", "2": "Grain alcohol is ethanol."}'),
  ('CHE-0891', 'Alcohols and phenols', 'Phenol', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 92 (§22.6.1)', 'Phenol dissolves in aqueous NaOH but ethanol does not react with it because', '["phenol is acidic enough to form sodium phenoxide, while ethanol is a weaker acid than water.", "phenol is a base.", "ethanol is insoluble in water.", "NaOH oxidizes phenol."]', 0, 'Phenol reacts with NaOH to form soluble sodium phenoxide and water. Ethanol is less acidic than water, so it does not react with NaOH.', '{"1": "Phenol acts as an acid in this reaction.", "2": "Ethanol mixes completely with water.", "3": "This is an acid–base reaction, not oxidation."}'),
  ('CHE-0892', 'Alcohols and phenols', 'Phenol', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 92 (§22.6.1)', 'Phenol is made from phenylamine by first forming a diazonium salt with nitrous acid. The nitrous acid is prepared from', '["NaNO₂ and dilute HCl, below 10 °C", "concentrated HNO₃ and H₂SO₄", "NaNO₃ and NaOH", "HCl and Br₂"]', 0, 'HNO₂ is unstable, so it is made in situ from sodium nitrite and dilute HCl with ice. Warming the diazonium salt then gives phenol.', '{"1": "This mixture is used for nitration.", "2": "NaNO₃ and NaOH do not give nitrous acid.", "3": "This does not give nitrous acid."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0893', 'Alcohols and phenols', 'Phenol', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 93 (§22.6.1)', 'Phenol heated with ethanoyl chloride in the presence of NaOH gives', '["phenyl ethanoate, an ester", "methoxybenzene, an ether", "benzoic acid", "2-chlorophenol"]', 0, 'NaOH converts phenol to the better nucleophile phenoxide, which attacks the carbonyl carbon of ethanoyl chloride, giving phenyl ethanoate and HCl.', '{"1": "The product contains a C=O group; it is an ester, not an ether.", "2": "Benzoic acid is not formed.", "3": "The ring is not chlorinated."}'),
  ('CHE-0894', 'Alcohols and phenols', 'Phenol', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 93 (§22.6.2)', 'Phenol reacts with dilute nitric acid at room temperature to give', '["a mixture of 2-nitrophenol and 4-nitrophenol", "3-nitrophenol only", "2,4,6-trinitrophenol", "nitrobenzene"]', 0, 'The –OH group activates the ring and directs to the 2-, 4- and 6- positions, so dilute nitric acid gives the 2- and 4-nitro products.', '{"1": "–OH does not direct to the meta position.", "2": "Concentrated nitric acid gives 2,4,6-trinitrophenol.", "3": "The –OH group stays on the ring."}'),
  ('CHE-0895', 'Alcohols and phenols', 'Phenol', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 94 (§22.6.2)', 'Benzene needs concentrated HNO₃ and H₂SO₄ for nitration, but phenol nitrates with dilute HNO₃ at room temperature because', '["a lone pair on oxygen is delocalized into the ring, increasing its electron density.", "phenol is less reactive than benzene.", "phenol has no π electrons.", "dilute HNO₃ contains more NO₂⁺."]', 0, 'The –OH group donates electron density into the π system, activating the ring towards electrophiles, so milder conditions are enough.', '{"1": "Phenol is more reactive than benzene.", "2": "Phenol has an aromatic π system.", "3": "Dilute HNO₃ contains less NO₂⁺; the ring''s higher reactivity makes up for it."}'),
  ('CHE-0896', 'Alcohols and phenols', 'Phenol', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 94 (§22.6.2)', '1-Naphthol undergoes electrophilic substitution mainly at positions', '["2 and/or 4", "9 and 10", "5 and 8 only", "3 only"]', 0, 'Like phenol, the –OH group activates the ring and directs electrophiles to the 2 and 4 positions. Positions 9 and 10 carry no hydrogen.', '{"1": "Carbons 9 and 10 (the ring-fusion carbons) have no hydrogen to substitute.", "2": "The book directs substitution to positions 2 and 4.", "3": "Position 3 is meta to –OH and is not activated."}'),
  ('CHE-0897', 'Alcohols and phenols', 'Phenol', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 22 Hydroxy Compounds, p. 94 (§22.6.2)', 'Unlike benzene, phenol reacts with bromine water', '["only with an AlBr₃ catalyst", "at room temperature without a catalyst", "only under UV light", "only above 150 °C"]', 1, 'The activated ring of phenol reacts readily with aqueous bromine at room temperature. Benzene needs pure bromine and anhydrous AlBr₃.', '{"0": "Benzene, not phenol, needs the Lewis acid catalyst.", "2": "UV light is used for addition to benzene.", "3": "No heating is required."}'),
  ('CHE-0898', 'Aldehydes, ketones and carboxylic acids', 'Aldehyde preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 99–100 (§23.1.1)', 'When ethanal is made by oxidizing ethanol with acidified K₂Cr₂O₇, the ethanal is distilled off as soon as it forms in order to', '["prevent its further oxidation to ethanoic acid", "remove unreacted ethanol", "speed up the reduction of dichromate", "convert it into its hydrate"]', 0, 'Ethanal (lower b.p.) boils off while ethanol stays in the flask; removing it at once stops it being oxidized further to ethanoic acid.', '{"1": "Ethanol has the higher b.p. and remains in the flask.", "2": "Distillation is about protecting the product, not the rate of dichromate reduction.", "3": "No hydrate is formed or wanted."}'),
  ('CHE-0899', 'Aldehydes, ketones and carboxylic acids', 'Aldehyde preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 100 (§23.1.1)', 'During the distillation of ethanal from the oxidation of ethanol, the temperature is kept', '["below the b.p. of ethanal", "above the b.p. of ethanol", "above the b.p. of ethanal but below that of ethanol", "at the b.p. of ethanoic acid"]', 2, 'Ethanal boils lower than ethanol, so a temperature between the two lets ethanal escape while ethanol stays to react.', '{"0": "Then ethanal would not distil off.", "1": "Ethanol would distil off unreacted.", "3": "That would distil off the acid, the product to be avoided."}'),
  ('CHE-0900', 'Aldehydes, ketones and carboxylic acids', 'Aldehyde preparation', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 100 (margin)', 'Formalin, used for preserving biological specimens, is', '["an aqueous solution of propanone", "a 40% aqueous solution of methanal", "a 40% solution of methanol", "pure liquid ethanal"]', 1, 'Methanal (HCHO) is a gas at room temperature and is usually met as formalin, a 40% aqueous solution.', '{"0": "Propanone is used in nail polish remover.", "2": "Formalin contains methanal, the aldehyde, not the alcohol.", "3": "Ethanal is a separate compound, not formalin."}'),
  ('CHE-0901', 'Aldehydes, ketones and carboxylic acids', 'Structure and reactivity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 100–101 (§23.2.1)', 'Which statement about the carbonyl group is correct?', '["The carbon is sp³ hybridized and tetrahedral.", "The carbonyl oxygen is δ+ and is attacked by electrophiles only.", "The group is non-polar because C and O share electrons equally.", "The carbonyl carbon is δ+ and is attacked by nucleophiles."]', 3, 'Oxygen is more electronegative, so carbon carries δ+ and is electrophilic; nucleophiles attack it.', '{"0": "The carbonyl carbon is sp² and planar.", "1": "Oxygen carries δ−, not δ+.", "2": "The C=O bond is polar."}'),
  ('CHE-0902', 'Aldehydes, ketones and carboxylic acids', 'Structure and reactivity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 101 (§23.2.1)', 'Which is the correct order of reactivity towards nucleophilic addition?', '["R₂CO > HCHO > RCHO", "R₂CO > RCHO > HCHO", "HCHO > RCHO > R₂CO", "RCHO > HCHO > R₂CO"]', 2, 'Each alkyl group adds a +I effect (less δ+ on carbon) and more steric hindrance, so methanal is most reactive and ketones least.', '{"0": "Ketones are the least reactive.", "1": "This is the reverse order.", "3": "Methanal, with no alkyl groups, is more reactive than other aldehydes."}'),
  ('CHE-0903', 'Aldehydes, ketones and carboxylic acids', 'Structure and reactivity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 101 (§23.2.1)', 'The book gives two reasons why aldehydes are more reactive than ketones towards nucleophiles. They are', '["hydrogen bonding and higher polarity of ketones", "the −I effect of alkyl groups and lower molar mass of aldehydes", "resonance in aldehydes and sp³ carbon in ketones", "the +I effect of two alkyl groups and steric hindrance in ketones"]', 3, 'In ketones two electron-releasing alkyl groups reduce the δ+ on the carbonyl carbon and also crowd the approach of the nucleophile.', '{"0": "Neither is the book''s reason.", "1": "Alkyl groups have a +I (electron-releasing) effect.", "2": "Both carbonyl carbons are sp²."}'),
  ('CHE-0904', 'Aldehydes, ketones and carboxylic acids', 'Addition of HCN', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 101 (§23.3.1)', 'The product of the reaction of ethanal with HCN (KCN/HCl) is', '["ethanenitrile", "2-hydroxypropanenitrile", "2-hydroxy-2-methylpropanenitrile", "propanoic acid"]', 1, 'CN⁻ adds to the carbonyl carbon and H⁺ to oxygen, giving CH₃CH(OH)CN, 2-hydroxypropanenitrile, a cyanohydrin with one more carbon.', '{"0": "Ethanenitrile has no –OH and two carbons.", "2": "That is the product from propanone.", "3": "The acid forms only after hydrolysis of the nitrile."}'),
  ('CHE-0905', 'Aldehydes, ketones and carboxylic acids', 'Addition of HCN', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 102 (§23.3.1 mechanism)', 'In cyanohydrin formation, a slight excess of KCN is used rather than HCN alone because', '["excess KCN removes water from the product", "KCN neutralizes the carbonyl compound", "HCN is a weak acid and supplies too few CN⁻ ions to start the reaction", "HCN is a strong nucleophile that reacts too fast"]', 2, 'HCN barely ionizes and has no lone pair on carbon to act as nucleophile; free CN⁻ from excess KCN starts and catalyses the addition.', '{"0": "KCN has no dehydrating role here.", "1": "KCN does not neutralize the carbonyl compound.", "3": "HCN itself is not a good nucleophile."}'),
  ('CHE-0906', 'Aldehydes, ketones and carboxylic acids', 'Addition of HCN', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 102 (§23.3.1 mechanism)', 'The first step in the mechanism of addition of HCN to a carbonyl compound is', '["attack of H⁺ on the carbonyl carbon", "loss of water from the carbonyl compound", "attack of CN⁻ on the carbonyl oxygen", "attack of CN⁻ on the carbonyl carbon"]', 3, 'The nucleophile CN⁻ attacks the electrophilic carbonyl carbon to form an alkoxide ion, which then takes H⁺ from HCN.', '{"0": "H⁺ attaches to the negatively charged oxygen in the second step.", "1": "Nothing is eliminated; this is an addition.", "2": "Oxygen is δ−, so a nucleophile does not attack it."}'),
  ('CHE-0907', 'Aldehydes, ketones and carboxylic acids', 'Reduction', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 102 (§23.3.1)', 'Reduction of propanone with NaBH₄ gives', '["propan-1-ol", "propan-2-ol", "propanal", "propanoic acid"]', 1, 'Ketones are reduced to secondary alcohols; propanone gives CH₃CH(OH)CH₃, propan-2-ol.', '{"0": "Propan-1-ol would come from propanal.", "2": "Propanal is an aldehyde, not a reduction product.", "3": "An acid is an oxidation product."}'),
  ('CHE-0908', 'Aldehydes, ketones and carboxylic acids', 'Reduction', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 103 (§23.3.1 mechanism)', 'In the reduction of a carbonyl compound by NaBH₄, the nucleophile that attacks the carbonyl carbon is', '["atomic hydrogen", "H⁻ (hydride ion)", "H⁺", "OH⁻"]', 1, 'NaBH₄ delivers a hydride ion to the δ+ carbon, giving an alkoxide ion that takes H⁺ from water.', '{"0": "The book stresses [H] is not atomic hydrogen.", "2": "H⁺ is not a nucleophile.", "3": "OH⁻ is formed when the alkoxide takes H⁺ from water."}'),
  ('CHE-0909', 'Aldehydes, ketones and carboxylic acids', '2,4-DNPH test', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 103 (§23.3.1)', '2,4-Dinitrophenylhydrazine gives an orange crystalline precipitate with', '["ethanamide and propanone", "both ethanal and ethanoic acid", "ethanal but not with ethyl ethanoate", "ethanoyl chloride only"]', 2, '2,4-DNPH identifies aldehydes and ketones. Acids, esters, acyl halides and amides also contain C=O but do not give the test.', '{"0": "Amides do not give the test.", "1": "Ethanoic acid does not give the test.", "3": "Acyl chlorides do not give the test."}'),
  ('CHE-0910', 'Aldehydes, ketones and carboxylic acids', '2,4-DNPH test', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 103 (§23.3.1)', 'The reaction of a carbonyl compound with 2,4-dinitrophenylhydrazine is described as', '["a free-radical substitution", "a redox reaction", "an electrophilic addition", "an addition–elimination (condensation) reaction"]', 3, 'The reagent adds to C=O and water is then eliminated, giving a hydrazone; this is a condensation (addition–elimination).', '{"0": "No radicals are involved.", "1": "No oxidation states of carbon change overall in this sense.", "2": "The attacking species is a nucleophilic –NH₂ group."}'),
  ('CHE-0911', 'Aldehydes, ketones and carboxylic acids', 'Tollens'' and Fehling''s', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 103 (§23.3.2)', 'On gentle warming with an aldehyde, Tollens'' reagent gives', '["an orange precipitate", "a silver mirror", "a brick-red precipitate", "a yellow precipitate"]', 1, 'Ag⁺ in ammoniacal silver nitrate is reduced to silver metal, which coats the tube as a mirror.', '{"0": "Orange crystals come from 2,4-DNPH.", "2": "Brick-red Cu₂O comes from Fehling''s solution.", "3": "Yellow iodoform comes from the iodoform test."}'),
  ('CHE-0912', 'Aldehydes, ketones and carboxylic acids', 'Tollens'' and Fehling''s', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 104 (§23.3.2)', 'In Fehling''s test with an aldehyde, the brick-red precipitate is', '["Cu(OH)₂", "CuO, formed by oxidation of Cu⁺", "Cu₂O, formed by reduction of Cu²⁺ to Cu⁺", "metallic copper"]', 2, 'Blue Cu²⁺ (complexed with tartrate) is reduced to Cu⁺, which forms brick-red copper(I) oxide in alkali.', '{"0": "Cu(OH)₂ is blue and contains Cu²⁺.", "1": "CuO is black and contains Cu²⁺.", "3": "Copper metal is not the product."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0913', 'Aldehydes, ketones and carboxylic acids', 'Tollens'' and Fehling''s', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 103 (§23.3.2)', 'Ketones do not give Tollens'' or Fehling''s tests because', '["ketones have no carbonyl group", "ketones are insoluble in water", "ketones are reduced instead", "oxidation of a ketone requires breaking a C–C bond"]', 3, 'An aldehyde has an H on the carbonyl carbon and is easily oxidized; a ketone can only be oxidized by breaking a C–C bond, which needs strong oxidizing agents.', '{"0": "Ketones do contain C=O.", "1": "Small ketones such as propanone are water-soluble.", "2": "Ketones are not reduced by these mild reagents."}'),
  ('CHE-0914', 'Aldehydes, ketones and carboxylic acids', 'Iodoform test', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 104 (§23.3.2)', 'Ethanol gives a positive iodoform test but methanol does not, because ethanol', '["has a higher boiling point", "contains a CH₃–CH(OH)– unit that is oxidized to CH₃CO–", "is a stronger acid", "is a secondary alcohol"]', 1, 'I₂/NaOH first oxidizes CH₃CH₂OH to ethanal, which has CH₃CO–; methanol has no such methyl group next to the carbinol carbon.', '{"0": "B.p. is irrelevant to the test.", "2": "Acidity is not the reason.", "3": "Ethanol is a primary alcohol."}'),
  ('CHE-0915', 'Aldehydes, ketones and carboxylic acids', 'Iodoform test', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 104 (§23.3.2)', 'A compound C₃H₆O gives a yellow precipitate with I₂/NaOH but no silver mirror with Tollens'' reagent. It is', '["prop-2-en-1-ol", "propanal", "propanone", "propan-1-ol"]', 2, 'No Tollens'' reaction rules out an aldehyde; a positive iodoform test shows CH₃CO–. Propanone, CH₃COCH₃, fits.', '{"0": "It lacks a CH₃CO– or CH₃CH(OH)– group.", "1": "Propanal is an aldehyde and has no CH₃CO– group.", "3": "Propan-1-ol is C₃H₈O and gives neither test."}'),
  ('CHE-0916', 'Aldehydes, ketones and carboxylic acids', 'Carboxylic acid properties', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 105 (§23.4)', 'Pure ethanoic acid is called glacial acetic acid because', '["it is obtained from glaciers", "it is a very dilute solution", "it boils at 118 °C", "it freezes at about 17 °C, forming ice-like crystals in winter"]', 3, 'Its melting point (17 °C) is close to room temperature, so it solidifies in cold weather into an ice-like solid.', '{"0": "The name refers to its appearance, not its source.", "1": "Glacial acid is pure (anhydrous), not dilute.", "2": "The b.p. does not explain the name."}'),
  ('CHE-0917', 'Aldehydes, ketones and carboxylic acids', 'Carboxylic acid properties', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 105 (§23.4)', 'Ethanoic acid has a much higher boiling point than expected from its molar mass mainly because', '["it has a high dipole moment only", "its molecules form hydrogen-bonded dimers", "it is ionic", "it is a long-chain fatty acid"]', 1, 'Two acid molecules pair up through two O–H···O=C hydrogen bonds, raising the boiling point.', '{"0": "Hydrogen bonding, not dipole alone, is the book''s reason.", "2": "Ethanoic acid is covalent.", "3": "Ethanoic acid has only two carbons."}'),
  ('CHE-0918', 'Aldehydes, ketones and carboxylic acids', 'Preparation of acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 106 (§23.4.1 b)', 'Alkaline hydrolysis of ethanenitrile, CH₃CN, with NaOH(aq) directly gives', '["ethanol and HCN", "ethanoic acid and NH₄Cl", "sodium ethanoate and ammonia", "ethanamine"]', 2, 'In alkali, nitriles give the carboxylate salt and NH₃; acidification is needed to obtain the free acid.', '{"0": "Hydrolysis does not give the alcohol.", "1": "Ethanoic acid and NH₄Cl form in acid hydrolysis with HCl.", "3": "Amines form by reduction of nitriles, not hydrolysis."}'),
  ('CHE-0919', 'Aldehydes, ketones and carboxylic acids', 'Preparation of acids', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 106 (§23.4.1 d)', 'Benzoic acid can be made by oxidizing', '["benzene with KMnO₄", "chlorobenzene with water", "phenol with NaOH", "methylbenzene with KMnO₄"]', 3, 'The side chain of methylbenzene is oxidized to –COOH by KMnO₄ (or K₂Cr₂O₇); the ring is not attacked.', '{"0": "Benzene has no side chain to oxidize.", "1": "Chlorobenzene does not react with water.", "2": "Phenol and NaOH give sodium phenoxide."}'),
  ('CHE-0920', 'Aldehydes, ketones and carboxylic acids', 'Reactions of acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 107 (§23.5)', 'Ethanoic acid reacts with thionyl chloride, SOCl₂, to give ethanoyl chloride and', '["H₂O and SO₂", "HCl and SO₂", "POCl₃ and HCl", "SO₃ only"]', 1, 'CH₃COOH + SOCl₂ → CH₃COCl + HCl + SO₂. Both by-products are gases.', '{"0": "No water is formed.", "2": "POCl₃ comes from PCl₅.", "3": "SO₃ is not formed."}'),
  ('CHE-0921', 'Aldehydes, ketones and carboxylic acids', 'Reactions of acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 108 (§23.5 C)', 'Which reagent reduces ethanoic acid to ethanol?', '["Tollens'' reagent", "NaBH₄", "LiAlH₄", "H₂/Ni"]', 2, 'Only the powerful reducing agent LiAlH₄ reduces carboxylic acids to primary alcohols; NaBH₄ and H₂/Ni do not.', '{"0": "Tollens'' reagent is an oxidizing agent.", "1": "The book says NaBH₄ does not reduce carboxylic acids.", "3": "The book says H₂/Ni does not reduce them."}'),
  ('CHE-0922', 'Aldehydes, ketones and carboxylic acids', 'Methanoic acid', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 108 (§23.5)', 'Methanoic acid differs from ethanoic acid in that it', '["does not react with NaHCO₃", "has no acidic hydrogen", "cannot form esters", "gives a silver mirror with Tollens'' reagent"]', 3, 'Methanoic acid has an aldehyde-like H–C=O part, so it is a reducing agent and is the only monocarboxylic acid to give Tollens'' and Fehling''s tests.', '{"0": "It is an acid and releases CO₂ from NaHCO₃.", "1": "Its –COOH hydrogen is acidic.", "2": "It forms esters like other acids."}'),
  ('CHE-0923', 'Aldehydes, ketones and carboxylic acids', 'Acidity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 108–109 (§23.6, Table 23.1)', 'Using the book''s typical pKa values, which order of acid strength is correct?', '["ArOH > RCOOH > ROH > H₂O", "RCOOH > ArOH > H₂O > ROH", "ROH > H₂O > ArOH > RCOOH", "H₂O > RCOOH > ArOH > ROH"]', 1, 'pKa values are about 5 (RCOOH), 10 (ArOH), 14 (H₂O) and 16 (ROH); the lower the pKa, the stronger the acid.', '{"0": "Carboxylic acids are stronger than phenols.", "2": "This is the reverse order.", "3": "Water is weaker than carboxylic acids and phenols."}'),
  ('CHE-0924', 'Aldehydes, ketones and carboxylic acids', 'Acidity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 109 (§23.6)', 'Carboxylic acids are stronger acids than alcohols chiefly because', '["carboxylic acids are more volatile", "they have more hydrogen atoms", "the negative charge of the carboxylate ion is delocalized over two oxygen atoms", "the alkoxide ion is stabilized by resonance"]', 2, 'Delocalization spreads the charge in RCOO⁻, stabilizing the conjugate base so it is less likely to take back H⁺.', '{"0": "Volatility has nothing to do with acidity.", "1": "Number of H atoms does not decide acidity.", "3": "The alkoxide ion has no resonance stabilization."}'),
  ('CHE-0925', 'Aldehydes, ketones and carboxylic acids', 'Acidity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 109 (§23.6)', 'Methanoic acid (Ka ≈ 1.8 × 10⁻⁴) is about ten times stronger than ethanoic acid (Ka ≈ 1.8 × 10⁻⁵) because', '["the methanoate ion is not delocalized", "methanoic acid has two oxygen atoms", "ethanoic acid cannot form hydrogen bonds", "the CH₃ group in ethanoic acid has a +I effect that destabilizes the ethanoate ion"]', 3, 'An electron-donating group intensifies the negative charge on the carboxylate ion, lowering acidity; methanoic acid has only H on the carboxyl carbon.', '{"0": "Both carboxylate ions are delocalized.", "1": "Both acids have two oxygen atoms.", "2": "Ethanoic acid forms hydrogen bonds."}'),
  ('CHE-0926', 'Aldehydes, ketones and carboxylic acids', 'Chloro acids', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 109 (§23.6)', 'Which acid has the lowest pKa?', '["Cl₃C–COOH", "Cl₂CH–COOH", "ClCH₂–COOH", "CH₃–COOH"]', 0, 'Each Cl adds a −I effect that disperses the carboxylate charge. pKa values: trichloro 0.64, dichloro 1.26, chloro 2.86, ethanoic about 4.75.', '{"1": "pKa 1.26, higher than trichloroethanoic acid.", "2": "pKa 2.86.", "3": "pKa about 4.75, the weakest of the four."}'),
  ('CHE-0927', 'Aldehydes, ketones and carboxylic acids', 'Esters', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 109–110 (§23.7)', 'Ethyl ethanoate boils at 77 °C, lower than both ethanol and ethanoic acid, because', '["ester molecules cannot hydrogen bond with each other", "esters are ionic", "esters have lower molar masses", "esters are polymers"]', 0, 'Esters have no O–H group, so there is no intermolecular hydrogen bonding; they are more volatile and less water-soluble.', '{"1": "Esters are covalent.", "2": "Ethyl ethanoate (88 g mol⁻¹) is heavier than ethanoic acid (60) and ethanol (46).", "3": "Simple esters are small molecules."}'),
  ('CHE-0928', 'Aldehydes, ketones and carboxylic acids', 'Esters', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 110 (§23.7.1)', 'Compared with Fischer esterification, the reaction of ethanoyl chloride with ethanol to make ethyl ethanoate', '["is vigorous and goes to completion", "reaches an equilibrium mixture", "needs concentrated H₂SO₄ and reflux", "produces water as the by-product"]', 0, 'Acyl chlorides react vigorously with alcohols and the reaction goes to completion, giving the ester and HCl.', '{"1": "Equilibrium is a feature of the acid + alcohol reaction.", "2": "No acid catalyst or reflux is needed.", "3": "The by-product is HCl."}'),
  ('CHE-0929', 'Aldehydes, ketones and carboxylic acids', 'Esters', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 110 (§23.7.1)', 'The ester formed from propanoic acid and ethanol is', '["ethyl propanoate", "propyl ethanoate", "ethyl ethanoate", "propyl propanoate"]', 0, 'The alcohol gives the alkyl part (ethyl) and the acid gives the -oate part (propanoate): CH₃CH₂COOCH₂CH₃.', '{"1": "That would be made from ethanoic acid and propanol.", "2": "That would be made from ethanoic acid and ethanol.", "3": "That would need propanol."}'),
  ('CHE-0930', 'Aldehydes, ketones and carboxylic acids', 'Hydrolysis of chlorides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 111–112 (§23.9)', 'Which is the correct order of ease of hydrolysis?', '["ethanoyl chloride > chloroethane > chlorobenzene", "chlorobenzene > chloroethane > ethanoyl chloride", "chloroethane > ethanoyl chloride > chlorobenzene", "all three hydrolyse equally fast"]', 0, 'Ethanoyl chloride reacts at room temperature within minutes, chloroethane needs prolonged heating, and chlorobenzene does not react with water.', '{"1": "This is the reverse order.", "2": "Ethanoyl chloride is the most reactive.", "3": "Their rates are very different."}'),
  ('CHE-0931', 'Aldehydes, ketones and carboxylic acids', 'Hydrolysis of chlorides', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 112 (§23.9)', 'Chlorobenzene does not react with water because', '["a lone pair on Cl is delocalized into the ring, giving the C–Cl bond partial double-bond character", "chlorine is less electronegative than carbon", "the ring carbon has a large δ+ charge", "chlorobenzene is a gas"]', 0, 'Overlap of the Cl lone pair with the ring π electrons strengthens the C–Cl bond so it does not break.', '{"1": "Chlorine is more electronegative than carbon.", "2": "A large δ+ would make it more reactive, not less.", "3": "Chlorobenzene is a liquid."}'),
  ('CHE-0932', 'Aldehydes, ketones and carboxylic acids', 'Hydrolysis of chlorides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 23 Carbonyl Compounds and Carboxylic Acids, p. 112 (§23.9)', 'Ethanoyl chloride is hydrolysed much faster than chloroethane because its carbonyl carbon', '["is bonded to two electronegative atoms (O and Cl) and carries a large δ+", "is sp³ hybridized", "has no partial charge", "is shielded by the methyl group"]', 0, 'Both O and Cl withdraw electrons from the carbonyl carbon, so water attacks it rapidly.', '{"1": "The carbonyl carbon is sp².", "2": "It carries a large δ+ charge.", "3": "The methyl group does not block attack."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0933', 'Organic chemistry', 'Classification', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 116 (§24.1)', 'Whether an amine is primary, secondary or tertiary depends on', '["the length of the carbon chain", "the number of carbons bonded to the carbon carrying –NH₂", "the number of alkyl or aryl groups bonded to the nitrogen atom", "the number of nitrogen atoms in the molecule"]', 2, 'Amines are classified by how many H atoms of NH₃ are replaced. Unlike alcohols, branching at the nitrogen, not at the carbon, decides the class.', '{"0": "Chain length does not decide the class.", "1": "That is how alcohols and halogenoalkanes are classified.", "3": "Simple amines have one nitrogen."}'),
  ('CHE-0934', 'Organic chemistry', 'Classification', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 116 (§24.1)', 'N-methylethanamine, CH₃–NH–CH₂CH₃, is', '["a primary amine", "a secondary amine", "a tertiary amine", "a quaternary ammonium salt"]', 1, 'Two alkyl groups (methyl and ethyl) are attached to the nitrogen, so it is secondary.', '{"0": "A primary amine has one group on N.", "2": "A tertiary amine has three groups on N.", "3": "A quaternary salt has four groups and a positive charge."}'),
  ('CHE-0935', 'Organic chemistry', 'Classification', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 117 (§24.1)', '(CH₃)₄N⁺Cl⁻ is named', '["trimethylamine", "N,N-dimethylmethanamine", "methanamine hydrochloride", "tetramethylammonium chloride"]', 3, 'Four alkyl groups on nitrogen give a quaternary ammonium salt, tetramethylammonium chloride.', '{"0": "Trimethylamine is (CH₃)₃N.", "1": "That is (CH₃)₃N, a tertiary amine.", "2": "That is CH₃NH₃⁺Cl⁻."}'),
  ('CHE-0936', 'Organic chemistry', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 117 (§24.2 A)', 'When bromoethane is heated with ammonia in ethanol under pressure, excess ammonia is used to', '["convert ethanamine into a nitrile", "make ethanamine the main product and limit further substitution", "make the tertiary amine the main product", "neutralize the ethanol"]', 1, 'The product amine can itself react with more halogenoalkane. Excess NH₃ favours the primary amine; excess halogenoalkane gives mainly tertiary amine.', '{"0": "No nitrile is formed.", "2": "Excess halogenoalkane, not ammonia, favours the tertiary amine.", "3": "Ethanol is only the solvent."}'),
  ('CHE-0937', 'Organic chemistry', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 117 (§24.2 A)', 'Reduction of propanenitrile, CH₃CH₂CN, with LiAlH₄ or H₂/Ni gives', '["propanoic acid", "ethanamine", "propan-1-amine", "propanamide"]', 2, 'The C≡N group is reduced to –CH₂NH₂, so the carbon count is kept: CH₃CH₂CH₂NH₂.', '{"0": "Propanoic acid is the hydrolysis product.", "1": "Reduction keeps all three carbons.", "3": "Propanamide is a partial hydrolysis product, not a reduction product."}'),
  ('CHE-0938', 'Organic chemistry', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 118 (§24.2 A v)', 'The Hofmann reaction of ethanamide with Br₂ and NaOH gives', '["ethanenitrile", "ethanamine", "propanamine", "methanamine"]', 3, 'The Hofmann reaction gives an amine with one carbon fewer than the amide: CH₃CONH₂ → CH₃NH₂.', '{"0": "No nitrile forms.", "1": "Ethanamine has the same number of carbons; it comes from LiAlH₄ reduction of the amide.", "2": "Carbons are lost, not gained."}'),
  ('CHE-0939', 'Organic chemistry', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 118 (§24.2 B)', 'Bromoethane heated with methanamine in ethanol under pressure gives', '["propan-1-amine", "N-methylethanamine", "ethanamine", "N,N-dimethylethanamine"]', 1, 'The primary amine acts as nucleophile and is alkylated, giving the secondary amine CH₃CH₂NHCH₃.', '{"0": "That is a primary amine with a three-carbon chain.", "2": "Ethanamine would come from ammonia.", "3": "That would need two methyl groups."}'),
  ('CHE-0940', 'Organic chemistry', 'Preparation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 119 (§24.2 C)', 'Nitrobenzene is reduced to phenylamine using', '["NaNO₂ and HCl", "KMnO₄ and H₂SO₄", "Sn and concentrated HCl", "Br₂ water"]', 2, 'Tin and concentrated HCl supply 6[H] to convert –NO₂ to –NH₂.', '{"0": "NaNO₂/HCl diazotizes an amine.", "1": "KMnO₄ is an oxidizing agent.", "3": "Bromine water brominates the ring."}'),
  ('CHE-0941', 'Organic chemistry', 'Preparation', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 118 (§24.2 C)', 'Phenylamine is made from chlorobenzene by ammonolysis under which conditions?', '["NH₃ and AlCl₃ at 0 °C", "NH₃ in ethanol at room temperature", "NaOH(aq) at room temperature", "NH₃ with Cu₂O at about 250 °C and 50 atm"]', 3, 'Aryl chlorides are very unreactive, so the substitution needs a Cu₂O catalyst, high temperature and high pressure.', '{"0": "AlCl₃ is a Friedel–Crafts catalyst and the conditions are too mild.", "1": "Chlorobenzene does not react under mild conditions.", "2": "This would not give an amine."}'),
  ('CHE-0942', 'Organic chemistry', 'Basicity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 119–120 (§24.3.1, Table 24.1)', 'Using Table 24.1, the correct order of basic strength is', '["phenylamine > ammonia > ethanamine", "ethanamine > ammonia > phenylamine", "ammonia > ethanamine > phenylamine", "ammonia > phenylamine > ethanamine"]', 1, 'pKb values: ethanamine 3.29, ammonia 4.75, phenylamine 9.38. Smaller pKb means stronger base.', '{"0": "This is the reverse order.", "2": "Ethanamine is stronger than ammonia.", "3": "Phenylamine is the weakest."}'),
  ('CHE-0943', 'Organic chemistry', 'Basicity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 119 (§24.3.1)', 'Ethanamine is a stronger base than ammonia because', '["its lone pair is delocalized", "it has more hydrogen atoms", "the ethyl group is electron-donating, making the nitrogen lone pair more available", "it is less soluble in water"]', 2, 'The +I effect of the alkyl group increases electron density on nitrogen, so it accepts a proton more readily.', '{"0": "Delocalization lowers basicity, as in phenylamine.", "1": "The number of H atoms is not the reason.", "3": "Solubility does not set base strength."}'),
  ('CHE-0944', 'Organic chemistry', 'Basicity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 120 (§24.3.1)', 'Phenylamine is a much weaker base than ammonia because', '["phenylamine is ionic", "the phenyl group donates electrons", "phenylamine has no lone pair", "the nitrogen lone pair is delocalized into the benzene ring"]', 3, 'The planar nitrogen''s lone pair overlaps with the ring π system, so it is less available to accept a proton.', '{"0": "Phenylamine is covalent.", "1": "The ring withdraws electron density from N by delocalization.", "2": "The lone pair is present but delocalized."}'),
  ('CHE-0945', 'Organic chemistry', 'Basicity', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 120 (Did You Know?)', 'Lemon juice reduces the smell of fish because citric acid', '["oxidizes the amine to nitrogen", "converts the volatile amine into a non-volatile salt", "dissolves fat", "turns the amine into an amide"]', 1, 'The fishy smell is from trimethylamine; acid protonates it to a salt that does not evaporate.', '{"0": "No oxidation to nitrogen occurs.", "2": "The smell is from the amine, not fat.", "3": "Amides form from acyl chlorides, not citric acid."}'),
  ('CHE-0946', 'Organic chemistry', 'Nitrous acid tests', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 120–121 (§24.3.2)', 'An aliphatic amine gives a yellow oily liquid with nitrous acid. The amine is', '["tertiary", "primary", "secondary", "a quaternary salt"]', 2, 'Secondary amines form N-nitrosoamines, yellow oily liquids.', '{"0": "Tertiary amines form soluble nitrite salts with no visible change.", "1": "Primary amines give bubbles of nitrogen gas.", "3": "Quaternary salts are not tested this way in the book."}'),
  ('CHE-0947', 'Organic chemistry', 'Nitrous acid tests', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 121 (§24.3.2)', 'When N,N-dimethylethanamine is treated with nitrous acid,', '["a white precipitate forms", "nitrogen gas bubbles off", "a yellow oil separates", "a soluble salt forms with no visible change"]', 3, 'Tertiary amines just form soluble ammonium nitrite salts, so nothing is seen.', '{"0": "No precipitate forms.", "1": "Nitrogen bubbles show a primary amine.", "2": "A yellow oil shows a secondary amine."}'),
  ('CHE-0948', 'Organic chemistry', 'Nitrous acid tests', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 122 (§24.3.3 b)', 'Nitrous acid for diazotization is', '["bought as a stable pure liquid", "made in situ from NaNO₂ and HCl", "made from HNO₃ and H₂SO₄", "made from NH₃ and O₂"]', 1, 'Nitrous acid is unstable, so it is generated in the reaction mixture from sodium nitrite and hydrochloric acid.', '{"0": "HNO₂ is unstable and not stored.", "2": "That mixture is the nitrating mixture.", "3": "That relates to the Ostwald process, not diazotization."}'),
  ('CHE-0949', 'Organic chemistry', 'Bromination', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 121–122 (§24.3.3 a)', 'Phenylamine reacts with bromine water much faster than benzene does because', '["bromine water is a stronger electrophile than Br₂/FeBr₃", "–NH₂ is a meta-directing deactivating group", "the –NH₂ group activates the ring at the ortho and para positions", "phenylamine is an alkene"]', 2, 'The –NH₂ group feeds electron density into the ring, so all three o- and p-positions are substituted in one step without a catalyst.', '{"0": "No catalyst is needed because the ring is activated.", "1": "–NH₂ is ortho/para-directing and activating.", "3": "Phenylamine is aromatic, not an alkene."}'),
  ('CHE-0950', 'Organic chemistry', 'Diazonium salts', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 122 (§24.3.3 b)', 'Diazotization of phenylamine is carried out below 10 °C because', '["the reaction is endothermic", "nitrous acid freezes above 10 °C", "phenylamine boils at 10 °C", "the diazonium salt decomposes, giving off N₂, at higher temperatures"]', 3, 'Diazonium salts are unstable and lose nitrogen even near room temperature, so ice is used to keep them intact.', '{"0": "Cooling is for product stability, not because the reaction is endothermic.", "1": "Nitrous acid does not freeze above 10 °C.", "2": "Phenylamine boils far above 10 °C."}'),
  ('CHE-0951', 'Organic chemistry', 'Diazonium salts', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 122 (§24.3.3 b)', 'Aryl diazonium salts are more stable than alkyl diazonium salts because', '["aryl groups are electron-donating by +I only", "the positive charge is delocalized over the benzene ring", "alkyl diazonium ions have no nitrogen–nitrogen bond", "aryl diazonium salts are insoluble"]', 1, 'Delocalization of the + charge into the ring stabilizes ArN₂⁺, so it can be kept at low temperature; alkyl diazonium salts cannot be isolated.', '{"0": "The book''s reason is delocalization.", "2": "Both contain –N≡N⁺.", "3": "They are used in aqueous solution."}'),
  ('CHE-0952', 'Organic chemistry', 'Diazonium salts', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 122 (§24.3.3 b)', 'Warming an aqueous solution of benzenediazonium chloride gives', '["chlorobenzene only", "phenylamine", "phenol", "azobenzene"]', 2, 'The diazonium group is replaced by –OH with loss of N₂: C₆H₅N₂⁺Cl⁻ + H₂O → C₆H₅OH + N₂ + HCl.', '{"0": "Warming with water gives phenol.", "1": "Phenylamine is the starting amine.", "3": "Azo compounds need a coupling partner."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0953', 'Organic chemistry', 'Azo dyes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 122 (§24.3.3 b)', 'In the coupling of benzenediazonium ion with phenol, the diazonium ion acts as', '["a reducing agent", "a nucleophile adding to C=O", "a free radical", "an electrophile substituting at the para position"]', 3, 'The positive diazonium ion attacks the activated phenol ring, mainly at the para position, giving 4-hydroxyazobenzene.', '{"0": "It is not acting as a reducing agent.", "1": "It is positively charged and electrophilic; phenol has no C=O.", "2": "No radicals are involved."}'),
  ('CHE-0954', 'Organic chemistry', 'Azo dyes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 122 (margin)', 'Diazonium coupling with phenol is carried out in', '["concentrated sulfuric acid", "mild alkaline solution", "strongly acidic solution at 100 °C", "dry ether"]', 1, 'Coupling with phenol occurs in mild alkali (e.g. NaOH), while coupling with aromatic amines occurs in mildly acidic conditions.', '{"0": "This would not give coupling.", "2": "The diazonium salt would decompose.", "3": "The reaction is done in aqueous solution."}'),
  ('CHE-0955', 'Organic chemistry', 'Azo dyes', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 123 (margin)', 'The chromophore responsible for the colour of azo dyes is', '["the –OH group", "the –NH₂ group", "the –N=N– group linking aromatic rings", "the –SO₃Na group"]', 2, 'The azo group (Ph–N=N–Ph) gives colours from yellow to red, blue and green depending on other groups attached.', '{"0": "–OH is not the chromophore.", "1": "–NH₂ modifies colour but is not the chromophore.", "3": "–SO₃Na mainly improves water solubility."}'),
  ('CHE-0956', 'Organic chemistry', 'Azo dyes', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 123 (§24.3.3)', 'Butter yellow (p-dimethylaminoazobenzene) is no longer used in food because it', '["decomposes at room temperature", "is insoluble in fat", "is colourless", "is carcinogenic"]', 3, 'The book states butter yellow was used in food but is now forbidden because it causes cancer.', '{"0": "It is a stable dye.", "1": "Solubility is not the stated reason.", "2": "It is a yellow dye."}'),
  ('CHE-0957', 'Organic chemistry', 'Azo dyes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 123 (§24.3.3)', 'Methyl orange, an acid–base indicator, is made by coupling', '["benzenediazonium chloride with phenol", "diazotized sulfanilic acid with N,N-dimethylphenylamine", "phenylamine with bromine water", "nitrobenzene with Sn/HCl"]', 1, 'The diazonium salt of sulfanilic acid couples with N,N-dimethylphenylamine in ethanoic acid to give methyl orange.', '{"0": "That gives 4-hydroxyazobenzene.", "2": "That gives 2,4,6-tribromophenylamine.", "3": "That gives phenylamine."}'),
  ('CHE-0958', 'Organic chemistry', 'Nitriles', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 124 (§24.4)', 'Heating ethanenitrile with dilute NaOH and then acidifying with dilute HCl gives', '["ethanal", "ethanamine", "ethanoic acid", "ethanol"]', 2, 'Alkaline hydrolysis gives sodium ethanoate and NH₃; acidification frees ethanoic acid.', '{"0": "Ethanal is not the hydrolysis product.", "1": "Amines come from reduction of nitriles.", "3": "Ethanol is not formed."}'),
  ('CHE-0959', 'Organic chemistry', 'Amides', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 124–125 (§24.5)', 'Ethanoyl chloride reacts with ethanamine at room temperature to give', '["ethanoic acid and ethanamine", "ethyl ethanoate and NH₃", "ethanamide and chloroethane", "N-ethylethanamide and HCl"]', 3, 'The amine attacks the acyl chloride to give the N-substituted amide CH₃CONHCH₂CH₃, releasing HCl.', '{"0": "That would be hydrolysis with water.", "1": "An ester needs an alcohol.", "2": "The N–H of the amine, not NH₃, is used."}'),
  ('CHE-0960', 'Organic chemistry', 'Amides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 125 (§24.5)', 'An excess of ammonia or amine is used when making amides from acyl chlorides because', '["the HCl formed reacts with some of the ammonia or amine to form a salt", "ammonia is the catalyst", "the reaction is reversible and needs pushing", "excess ammonia reduces the amide"]', 0, 'Each HCl released turns another molecule of NH₃ or amine into an ammonium salt, so extra is needed for complete reaction.', '{"1": "Ammonia is a reactant, not a catalyst.", "2": "The book''s reason is the side reaction with HCl.", "3": "Ammonia does not reduce amides."}'),
  ('CHE-0961', 'Organic chemistry', 'Amides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 125 (§24.5)', 'Amides are much weaker bases than amines because', '["the nitrogen lone pair is delocalized onto the carbonyl oxygen", "amides have no nitrogen lone pair", "the C=O group donates electrons to nitrogen", "amides are ionic"]', 0, 'Resonance gives the C–N bond partial double-bond character and makes the lone pair less available; amides give neutral solutions in water.', '{"1": "The lone pair exists but is delocalized.", "2": "C=O withdraws electrons.", "3": "Amides are covalent."}'),
  ('CHE-0962', 'Organic chemistry', 'Amides', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 125 (§24.5)', 'The C–N bond length in an amide (about 132 pm) is shorter than in an amine (about 147 pm) because', '["delocalization gives the amide C–N bond partial double-bond character", "nitrogen is sp³ in amides", "amides are hydrogen-bonded", "the amide nitrogen carries a full negative charge"]', 0, 'Overlap of the nitrogen lone pair with C=O introduces double-bond character between C and N, shortening the bond.', '{"1": "Delocalization makes the amide nitrogen planar.", "2": "Hydrogen bonding is between molecules and does not shorten the C–N bond.", "3": "In the resonance form nitrogen is positive, not negative."}'),
  ('CHE-0963', 'Organic chemistry', 'Amino acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 126 (§24.6)', 'Which α-amino acid is not chiral?', '["glycine", "alanine", "lysine", "glutamic acid"]', 0, 'In glycine R = H, so the α-carbon carries two H atoms and is not a chiral centre. All other α-amino acids are chiral.', '{"1": "Alanine (R = CH₃) has four different groups on the α-carbon.", "2": "Lysine is chiral.", "3": "Glutamic acid is chiral."}'),
  ('CHE-0964', 'Organic chemistry', 'Amino acids', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 127 (§24.6.1)', 'In the zwitterion of an amino acid, the acidic group and the basic group are', '["–NH₃⁺ (acidic) and –COO⁻ (basic)", "–COOH (acidic) and –NH₂ (basic)", "–NH₂ (acidic) and –COOH (basic)", "–COO⁻ (acidic) and –NH₃⁺ (basic)"]', 0, 'In the dipolar ion, –NH₃⁺ donates a proton (pKa ≈ 10) and –COO⁻ accepts one (pKb ≈ 12), so amino acids are weaker acids and bases than RCOOH and amines.', '{"1": "These groups are not present as such in the zwitterion.", "2": "–NH₂ is basic, not acidic.", "3": "This reverses the roles."}'),
  ('CHE-0965', 'Organic chemistry', 'Amino acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 127 (§24.6.1)', 'At low pH, an amino acid exists mainly as', '["the cation H₃N⁺–CHR–COOH", "the anion H₂N–CHR–COO⁻", "the zwitterion H₃N⁺–CHR–COO⁻", "the neutral molecule H₂N–CHR–COOH"]', 0, 'Added H⁺ protonates the –COO⁻ group, leaving a net positive charge.', '{"1": "The anion predominates at high pH.", "2": "The zwitterion predominates at the isoelectric point.", "3": "The book shows the cation in acid solution."}'),
  ('CHE-0966', 'Organic chemistry', 'Electrophoresis', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 127 (§24.6.2, Fig. 24.2)', 'In electrophoresis at pH 6, lysine (pI 9.74), alanine (pI 6.02) and glutamic acid (pI 3.22) will', '["move to the cathode, stay near the origin, and move to the anode respectively", "all move to the cathode", "move to the anode, stay, and move to the cathode respectively", "all stay at the origin"]', 0, 'If pI > pH the amino acid is positive and goes to the cathode; if pI < pH it is negative and goes to the anode; at pI ≈ pH there is no net charge.', '{"1": "Glutamic acid is negative at pH 6.", "2": "This reverses the directions.", "3": "Only alanine has pI close to 6."}'),
  ('CHE-0967', 'Organic chemistry', 'Electrophoresis', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 128 (§24.6.2)', 'After electrophoresis, the positions of the colourless amino acids are shown by spraying', '["ninhydrin, which gives a purple product", "iodine solution, which gives a blue colour", "Tollens'' reagent", "2,4-DNPH, which gives orange crystals"]', 0, 'Ninhydrin is the locating agent for amino acids and gives a purple colour.', '{"1": "Iodine is a test for starch.", "2": "Tollens'' reagent tests aldehydes.", "3": "2,4-DNPH tests aldehydes and ketones."}'),
  ('CHE-0968', 'Organic chemistry', 'Peptides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 24 Organic Nitrogen Compounds, p. 128 (§24.6.3)', 'How many peptide bonds and how many water molecules are involved in forming a tripeptide from three amino acids?', '["2 peptide bonds; 2 water molecules eliminated", "3 peptide bonds; 3 water molecules eliminated", "2 peptide bonds; 3 water molecules eliminated", "3 peptide bonds; 2 water molecules eliminated"]', 0, 'Each amide (peptide) link joins two amino acids by condensation and releases one H₂O. Three units need two links.', '{"1": "A chain of three units has only two links.", "2": "One water is lost per peptide bond.", "3": "There are only two links."}'),
  ('CHE-0969', 'Organic chemistry', 'Synthesis basics', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 131 (§25.1)', 'According to the book, a good synthesis converts cheap, easily available starting materials to the product by a route with', '["the fewest steps and a high overall yield", "the most steps so each is easy", "the lowest temperature regardless of yield", "only one reagent"]', 0, 'The best route uses few steps and gives a high overall yield from cheap starting materials.', '{"1": "More steps lower the overall yield.", "2": "Temperature alone does not define a good route.", "3": "Most syntheses need several reagents."}'),
  ('CHE-0970', 'Organic chemistry', 'Synthesis basics', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 131–132 (§25.1)', 'Why are carbon–carbon bond-forming reactions especially important in synthesis?', '["They always change one functional group into another.", "The basic strategy is to assemble the target from smaller starting materials.", "They never need catalysts.", "They remove carbon atoms from the molecule."]', 1, 'Building the carbon skeleton from smaller pieces is the core of synthesis, so C–C bond formation is central.', '{"0": "That describes FGI.", "2": "Many C–C bond-forming reactions, like Friedel–Crafts, need catalysts.", "3": "They join carbons rather than remove them."}'),
  ('CHE-0971', 'Organic chemistry', 'Synthesis basics', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 132 (§25.1.1)', 'A primary amine R–CH₂–NH₂ is best made from the readily available alcohol R–CH₂–OH by', '["H₂/Ni, then HCl", "NaBH₄, then NH₃", "SOCl₂, then NH₃", "K₂Cr₂O₇/H₂SO₄, then NH₃"]', 2, 'Halogenoalkanes are less available, so the alcohol is first converted to R–CH₂Cl with SOCl₂, which then reacts with ammonia.', '{"0": "Neither step makes an amine.", "1": "NaBH₄ reduces carbonyls; it does not activate an alcohol.", "3": "This would oxidize the alcohol."}'),
  ('CHE-0972', 'Organic chemistry', 'Retrosynthesis terms', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 132 (§25.1.2)', 'Retrosynthesis is best described as', '["the reverse reaction of an equilibrium", "hydrolysis of the product", "breaking down a molecule in a mass spectrometer", "working backwards from the target molecule to simpler starting materials"]', 3, 'It is the opposite of synthesis: the target is imaginatively broken into simpler, readily available compounds by disconnections.', '{"0": "It is a planning method, not a reverse reaction.", "1": "No actual reaction is carried out.", "2": "That is fragmentation, not retrosynthesis."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0973', 'Organic chemistry', 'Retrosynthesis terms', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 132 (§25.1.2)', 'A synthetic equivalent is', '["an imaginary bond broken in the target", "a real reagent that does the job of a synthon, which is usually too unstable to use", "the target molecule itself", "the final yield of the synthesis"]', 1, 'Synthons are often ionic fragments that cannot be used directly; a stable reagent (e.g. HNO₃ for NO₂⁺) acts as the synthetic equivalent.', '{"0": "That is a disconnection.", "2": "The target molecule is what is being made.", "3": "Yield is not a synthetic equivalent."}'),
  ('CHE-0974', 'Organic chemistry', 'Retrosynthesis terms', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 133 (§25.1.2)', 'A diagram showing all possible disconnections and synthons from the target molecule back to the starting materials is called', '["a flow sheet of an industrial plant", "a reaction profile", "a retrosynthetic tree", "an energy level diagram"]', 2, 'The book defines a retrosynthetic tree as the diagram of all disconnections and synthons from TM to starting materials.', '{"0": "That shows plant units, not disconnections.", "1": "A reaction profile shows energy against reaction progress.", "3": "That shows energy levels."}'),
  ('CHE-0975', 'Organic chemistry', 'Retrosynthesis terms', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 132 (§25.1.2)', 'In retrosynthesis, a disconnection is chosen so that it', '["adds as many carbon atoms as possible", "produces radicals", "always breaks a C–H bond", "gives a considerable structural simplification"]', 3, 'Bonds are disconnected where this simplifies the structure, eventually reaching simple starting materials.', '{"0": "Disconnections simplify; they do not add carbons.", "1": "Synthons are usually ionic, not radicals.", "2": "C–H bonds are not usually disconnected."}'),
  ('CHE-0976', 'Organic chemistry', 'FGI', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 133 (Fig. 25.3)', 'In the aliphatic FGI scheme, a halogenoalkane is converted into an alkene by', '["NH₃", "KOH in alcohol", "KOH(aq)", "NaBH₄"]', 1, 'Ethanolic KOH causes elimination of HX, giving an alkene.', '{"0": "NH₃ gives an amine.", "2": "Aqueous KOH substitutes –OH, giving an alcohol.", "3": "NaBH₄ reduces carbonyl compounds."}'),
  ('CHE-0977', 'Organic chemistry', 'FGI', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 133 (Fig. 25.3)', 'In the aliphatic FGI scheme, ethanoic acid is converted to ethanoyl chloride by', '["KOH(aq)", "LiAlH₄", "SOCl₂", "NH₃"]', 2, 'Thionyl chloride replaces the –OH of the acid by –Cl.', '{"0": "KOH(aq) gives the salt.", "1": "LiAlH₄ reduces the acid to an alcohol.", "3": "NH₃ converts the acyl chloride into an amide."}'),
  ('CHE-0978', 'Organic chemistry', 'FGI', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 133 (Fig. 25.3)', 'Ethanoyl chloride gives ethanamide when treated with', '["C₂H₅OH", "LiAlH₄", "H₂O", "NH₃"]', 3, 'Ammonia replaces –Cl by –NH₂ (with HCl formed).', '{"0": "Ethanol gives the ester.", "1": "LiAlH₄ is a reducing agent.", "2": "Water gives the acid."}'),
  ('CHE-0979', 'Organic chemistry', 'FGI', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 134 (Fig. 25.4)', 'In the aromatic FGI scheme, methylbenzene is converted to benzyl alcohol by', '["CH₃Cl/AlCl₃", "Cl₂ in light, then KOH(aq)", "KMnO₄/H₂SO₄", "Sn/HCl"]', 1, 'Free-radical chlorination in light gives C₆H₅CH₂Cl, which aqueous KOH hydrolyses to C₆H₅CH₂OH.', '{"0": "This would add another methyl group.", "2": "KMnO₄ oxidizes the side chain all the way to benzoic acid.", "3": "Sn/HCl reduces nitro groups."}'),
  ('CHE-0980', 'Organic chemistry', 'FGI', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 134 (Fig. 25.4)', 'In the aromatic FGI scheme, phenol is obtained from benzenesulfonic acid by', '["reacting with SO₃", "warming with Sn/HCl", "fusing with NaOH, then acidifying with HCl", "nitrating with HNO₃/H₂SO₄"]', 2, 'The scheme shows (i) NaOH then (ii) HCl converting C₆H₅SO₃H into C₆H₅OH.', '{"0": "SO₃ makes the sulfonic acid from benzene.", "1": "Sn/HCl reduces nitrobenzene.", "3": "Nitration gives nitrobenzene."}'),
  ('CHE-0981', 'Organic chemistry', 'Worked examples', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 134–135 (Example 25.2.1)', 'In the retrosynthesis of ethyl acetate, disconnecting the ester C–O bond leads to the synthetic equivalents', '["benzene and nitric acid", "acetyl chloride and benzene", "ethanal and methanol", "acetic acid and ethanol"]', 3, 'Neutralizing the acyl and ethoxy synthons gives acetic acid and ethanol, which are esterified with H₂SO₄.', '{"0": "These are for nitrobenzene/aniline.", "1": "These give acetophenone.", "2": "They would not give ethyl acetate."}'),
  ('CHE-0982', 'Organic chemistry', 'Worked examples', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 135 (Example 25.2.2)', 'In the retrosynthesis of aniline, the first step is FGI of –NH₂ to –NO₂ because', '["–NH₂ is a meta director", "a nitro group is easily put on benzene by electrophilic substitution, but an amino group cannot be added directly", "nitro compounds are more basic", "aniline cannot be reduced"]', 1, 'Benzene undergoes electrophilic nitration readily; the nitro group is then reduced with Sn/HCl to –NH₂.', '{"0": "–NH₂ is ortho/para-directing.", "2": "Nitro compounds are not basic.", "3": "The point is to make aniline by reduction of nitrobenzene."}'),
  ('CHE-0983', 'Organic chemistry', 'Worked examples', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 135 (Example 25.2.3)', 'Disconnecting the C–C bond in acetophenone (C₆H₅COCH₃) gives an aryl synthon and the synthon CH₃CO⁺, whose synthetic equivalent is', '["methane", "ethanol", "ethanoyl chloride, used with AlCl₃", "ethanoic acid with NaBH₄"]', 2, 'The acylium ion comes from CH₃COCl and AlCl₃ in Friedel–Crafts acylation of benzene.', '{"0": "Methane has no carbonyl group.", "1": "Ethanol cannot supply an acylium ion.", "3": "NaBH₄ is a reducing agent."}'),
  ('CHE-0984', 'Organic chemistry', 'Paracetamol', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 136–137 (Example 25.3.1)', 'In the book''s synthesis of paracetamol from phenol, the correct order of steps is', '["reaction with CH₃COCl, nitration, then reduction", "Kolbe reaction with CO₂, then acetylation", "reduction, nitration, then hydrolysis", "nitration, reduction with Sn/HCl, then reaction with CH₃COCl"]', 3, 'Phenol → 4-nitrophenol (HNO₃/H₂SO₄) → 4-aminophenol (Sn/HCl) → paracetamol (CH₃COCl, forming the amide).', '{"0": "The amino group must be present before acylation.", "1": "That is the route to aspirin.", "2": "Phenol has no group to reduce first."}'),
  ('CHE-0985', 'Organic chemistry', 'Paracetamol', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 137 (Example 25.3.1)', 'The amide bond of paracetamol is disconnected in retrosynthesis because 4-aminophenol and ethanoyl chloride', '["are both electrophiles", "are known to react by nucleophilic addition–elimination", "react by free-radical substitution", "react only under high pressure"]', 1, 'The amino group adds to the acyl chloride carbonyl, then Cl⁻ is lost; this well-known reaction forms the amide.', '{"0": "The amine is a nucleophile.", "2": "No radicals are involved.", "3": "Acyl chlorides react with amines at room temperature."}'),
  ('CHE-0986', 'Organic chemistry', 'Aspirin', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 138 (Example 25.3.2)', 'In the book''s synthesis of aspirin, salicylic acid is made from phenol using', '["KMnO₄", "CH₃COCl and AlCl₃", "CO₂ at high temperature and pressure, then acid", "HNO₃ and H₂SO₄"]', 2, 'The C–C bond of the carboxyl group is disconnected to phenol + CO₂; in the forward direction phenol is carboxylated with CO₂ under high T and P.', '{"0": "KMnO₄ oxidizes side chains; phenol has none.", "1": "That gives an acylation, not a carboxylic acid group.", "3": "That nitrates the ring."}'),
  ('CHE-0987', 'Organic chemistry', 'Aspirin', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 138 (Example 25.3.2)', 'Salicylic acid is converted into aspirin by reaction with', '["NH₃", "ethanol and H₂SO₄", "NaBH₄", "ethanoic anhydride, with an acid catalyst"]', 3, 'The phenolic –OH is acetylated by ethanoic anhydride (H₂SO₄/H₃PO₄, heat) to form the ester group of aspirin.', '{"0": "NH₃ would give an amide or salt.", "1": "This would esterify the –COOH, not the phenolic –OH.", "2": "NaBH₄ is a reducing agent."}'),
  ('CHE-0988', 'Organic chemistry', 'Aspirin', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 137–138 (§25.3)', 'Aspirin and paracetamol are both made from phenol. In aspirin the acetyl group is part of an ester; in paracetamol it is part of', '["an amide", "a ketone", "an ether", "an aldehyde"]', 0, 'Paracetamol''s CH₃CO– is bonded to N (–NHCOCH₃), an amide; aspirin''s is bonded to O (an ester).', '{"1": "The acetyl group is bonded to N, not C.", "2": "There is no C–O–C ether link involving the acetyl group.", "3": "There is no –CHO group."}'),
  ('CHE-0989', 'Organic chemistry', 'AI drug design', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 139 (§25.4)', 'In the MIT study described in the book, the machine-learning model was trained to look for chemical features that make molecules effective at', '["killing E. coli bacteria", "lowering blood pressure", "killing viruses", "dissolving kidney stones"]', 0, 'The algorithm searched for features linked to killing E. coli and then picked out halicin, which has a structure unlike existing antibiotics.', '{"1": "The study was about antibacterial activity.", "2": "Halicin is antibacterial, not antiviral.", "3": "Not mentioned."}'),
  ('CHE-0990', 'Organic chemistry', 'AI drug design', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 139 (§25.4)', 'After identifying halicin, the researchers screened more than 100 million molecules. According to the book, this took about', '["three days", "three years", "ten years", "three months"]', 0, 'The screen of over 100 million molecules was completed in only three days, picking out 23 more candidates.', '{"1": "The point is how fast the computer screen was.", "2": "Ten years relates to the vitamin B₁₂ synthesis.", "3": "The book says three days."}'),
  ('CHE-0991', 'Organic chemistry', 'History', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 25 Organic Synthesis, p. 139 (Interesting Information)', 'The total synthesis of vitamin B₁₂, completed in 1972 after over 100 steps, was achieved by', '["R. B. Woodward and A. Eschenmoser", "Robert Robinson alone", "Kekulé and Faraday", "the MIT halicin team"]', 0, 'Woodward and Eschenmoser collaborated for over ten years on the B₁₂ synthesis.', '{"1": "Robinson is mentioned for cholesterol.", "2": "They are associated with benzene, not B₁₂.", "3": "That team found halicin."}'),
  ('CHE-0992', 'Macromolecules', 'Addition polymerization', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 143 (§26.1.1)', 'A monomer for addition polymerization must contain', '["a C=C (or C≡C) bond", "two –OH groups", "an –NH₂ and a –COOH group", "a benzene ring"]', 0, 'The multiple bond opens up so monomers can join end to end; no small molecule is lost.', '{"1": "Two –OH groups suit condensation (polyesters).", "2": "These groups suit condensation (polyamides).", "3": "A benzene ring alone does not allow addition polymerization."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-0993', 'Macromolecules', 'Addition polymerization', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 143 (§26.1.1)', 'Which statement about addition polymerization is correct?', '["The monomers need two different functional groups.", "A molecule of water is lost at each step.", "All atoms of the monomers end up in the polymer.", "It always needs HCl as a catalyst."]', 2, 'Monomers add one by one by a chain reaction (often started by a free-radical initiator), and nothing is lost.', '{"0": "Addition needs a C=C bond, not two functional groups.", "1": "Loss of a small molecule marks condensation.", "3": "An initiator, not HCl, starts the chain."}'),
  ('CHE-0994', 'Macromolecules', 'Poly(ethene)', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 143–144 (§26.1.1)', 'LDPE is softer and less dense than HDPE because', '["it is a condensation polymer", "it contains chlorine atoms", "it has cross-links between chains", "its chains are more branched and cannot pack closely"]', 3, 'Branching stops LDPE chains packing tightly; HDPE has linear chains that pack closely into a dense, tough material.', '{"0": "Both are addition polymers of ethene.", "1": "Neither form contains chlorine.", "2": "Cross-links would make it harder."}'),
  ('CHE-0995', 'Macromolecules', 'Poly(ethene)', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 143–144 (§26.1.1, Did You Know?)', 'HDPE is made from ethene using', '["high pressure without any catalyst", "a Ziegler–Natta catalyst at low pressure and temperature", "concentrated H₂SO₄", "UV light and chlorine"]', 1, 'Ziegler''s catalyst (1953) first allowed low-pressure polymerization of ethene into linear HDPE.', '{"0": "This is not the book''s route for HDPE.", "2": "H₂SO₄ is not the catalyst.", "3": "That would chlorinate, not polymerize."}'),
  ('CHE-0996', 'Macromolecules', 'Poly(ethene)', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 144 (Did You Know?)', 'Giulio Natta extended the Ziegler catalyst family to make', '["PVC", "nylon-6,6", "stereoregular polymers such as crystalline polypropylene", "Kevlar"]', 2, 'Natta used the catalysts to make stereoregular polymers such as crystalline poly(propene).', '{"0": "PVC is not the example given.", "1": "Nylon-6,6 is a condensation polymer.", "3": "Kevlar is a polyamide."}'),
  ('CHE-0997', 'Macromolecules', 'PVC', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 144 (§26.1.1)', 'The monomer of PVC is', '["propene, CH₂=CHCH₃", "ethene, CH₂=CH₂", "tetrafluoroethene, CF₂=CF₂", "chloroethene, CH₂=CHCl"]', 3, 'Addition polymerization of chloroethene gives poly(chloroethene), –[CH₂–CHCl]ₙ–.', '{"0": "Propene gives poly(propene).", "1": "Ethene gives poly(ethene).", "2": "Tetrafluoroethene gives PTFE."}'),
  ('CHE-0998', 'Macromolecules', 'PVC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 144 (§26.1.1)', 'Rigid PVC resists burning and is self-extinguishing because of', '["added plasticizers", "the chlorine atoms in its chains", "its ester links", "its benzene rings"]', 1, 'The book attributes PVC''s natural fire resistance to its chlorine atoms.', '{"0": "Rigid PVC has no plasticizer.", "2": "PVC has no ester links.", "3": "PVC has no benzene rings."}'),
  ('CHE-0999', 'Macromolecules', 'PVC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 144 (§26.1.1)', 'PVC is widely used for water and sewage pipes mainly because it', '["dissolves slowly in water", "conducts electricity", "resists corrosion and is durable", "is biodegradable"]', 2, 'Pipes and fittings use PVC for its corrosion resistance and long life.', '{"0": "PVC does not dissolve in water.", "1": "PVC is an insulator.", "3": "PVC is not readily biodegradable."}'),
  ('CHE-1000', 'Macromolecules', 'Condensation polymerization', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 145 (§26.1.2)', 'A monomer for condensation polymerization must have', '["a chlorine atom", "a C=C double bond", "a free-radical initiator", "at least two reactive functional groups"]', 3, 'Groups such as –OH, –COOH and –NH₂ at both ends let the chain grow step by step, with a small molecule lost each time.', '{"0": "Chlorine is not required.", "1": "A C=C bond is needed for addition.", "2": "Initiators start addition polymerization."}'),
  ('CHE-1001', 'Macromolecules', 'Polyesters', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 145 (§26.1.2 a)', 'Terylene (PET) is formed from', '["hexane-1,6-diamine and hexanedioic acid", "ethane-1,2-diol and benzene-1,4-dicarboxylic acid", "caprolactam", "chloroethene"]', 1, 'The diol''s –OH groups react with the diacid''s –COOH groups, forming ester links and releasing water.', '{"0": "These form nylon-6,6.", "2": "Caprolactam forms nylon-6.", "3": "Chloroethene forms PVC."}'),
  ('CHE-1002', 'Macromolecules', 'Polyesters', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 146 (§26.1.2 a)', 'Polyester fibre is used as an alternative to cotton because it', '["is a natural polymer", "absorbs a lot of water", "is cheap and resists creases", "melts at body temperature"]', 2, 'The book gives low cost and crease resistance (and high tensile strength) as reasons.', '{"0": "Polyester is synthetic.", "1": "This is not the stated reason.", "3": "It does not melt at body temperature."}'),
  ('CHE-1003', 'Macromolecules', 'Polyamides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 146 (§26.1.2 b)', 'When a diamine reacts with a dicarboxylic acid to form a polyamide, the small molecule eliminated is', '["CO₂", "HCl", "NH₃", "water"]', 3, '–NH₂ and –COOH join to form –CONH– and H₂O is lost.', '{"0": "CO₂ is not formed.", "1": "HCl is lost when a dioyl chloride is used.", "2": "Ammonia is not eliminated here."}'),
  ('CHE-1004', 'Macromolecules', 'Polyamides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 146 (§26.1.2 b)', 'A dioyl chloride is sometimes used in place of a dicarboxylic acid to make a polyamide because', '["it gives an ester link", "acyl chlorides are more reactive than carboxylic acids", "it removes water as by-product", "it gives an addition polymer"]', 1, 'The book notes dioyl chlorides are more reactive; acyl chlorides react with amines at room temperature.', '{"0": "With a diamine the link formed is an amide.", "2": "HCl is lost, not water.", "3": "It is still condensation."}'),
  ('CHE-1005', 'Macromolecules', 'Polyamides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 146 (§26.1.2 b)', 'Proteins are classed as natural', '["addition polymers", "polyesters", "polyamides", "poly(alkene)s"]', 2, 'Amino acids join by peptide bonds, a type of amide link, so proteins are polyamides.', '{"0": "Proteins form by condensation.", "1": "Proteins have no ester backbone.", "3": "Proteins are not hydrocarbons."}'),
  ('CHE-1006', 'Macromolecules', 'Nylon', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 146–147 (§26.2)', 'Nylon-6,6 is made from hexamethylenediamine and', '["caprolactam", "ethane-1,2-diol", "terephthalic acid only", "adipic (hexanedioic) acid"]', 3, 'Nylon-6,6 forms from 1,6-diaminohexane and hexanedioic acid; each monomer has six carbons.', '{"0": "Caprolactam gives nylon-6.", "1": "A diol gives a polyester.", "2": "Not the book''s monomer for nylon-6,6."}'),
  ('CHE-1007', 'Macromolecules', 'Nylon', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 147 (§26.2)', 'Nylon-6 is classified as a condensation polymer even though no small molecule is lost because', '["it contains C=C bonds", "its chain is joined by amide linkages, as in condensation polyamides", "it is made from two monomers", "it is made by a free-radical chain reaction"]', 1, 'Caprolactam''s ring opens without losing water, but the polymer is classified by its amide (–CONH–) linkage.', '{"0": "Nylon-6 has no C=C bonds in the monomer that react.", "2": "Nylon-6 has a single monomer, caprolactam.", "3": "That would be addition polymerization."}'),
  ('CHE-1008', 'Macromolecules', 'Nylon', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 147 (§26.2)', 'Nylon-6 is named so because its monomer, caprolactam,', '["forms six amide links", "has six nitrogen atoms", "has six carbon atoms", "melts at 6 °C"]', 2, 'The number indicates the six-carbon cyclic monomer.', '{"0": "The name does not count links.", "1": "Caprolactam has one nitrogen.", "3": "Not related to melting point."}'),
  ('CHE-1009', 'Macromolecules', 'Nylon', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 148 (§26.2.2)', 'Nylon is used for ropes and fishing nets mainly because of its', '["low melting point", "solubility in water", "electrical conductivity", "high tensile strength and resistance to water wear"]', 3, 'Its strength, elasticity and resistance to wear in water suit ropes, nets and lines.', '{"0": "The book lists a high melting point as a property.", "1": "Nylon is insoluble in water.", "2": "Nylon is an insulator."}'),
  ('CHE-1010', 'Macromolecules', 'Identifying polymers', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 149 (§26.3)', 'If the backbone of a polymer section contains only carbon atoms, the polymer is', '["a polyester", "an addition polymer made from alkenes", "a polyamide", "a condensation polymer of amino acids"]', 1, 'A purely –C–C–C– backbone shows an addition polymer; O or N in the chain shows a condensation polymer.', '{"0": "Polyesters have –COO– in the chain.", "2": "Polyamides have –CONH– in the chain.", "3": "These have –CONH– in the chain."}'),
  ('CHE-1011', 'Macromolecules', 'Identifying polymers', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 149 (§26.3, Table 26.1)', 'Which pair are both polyamides?', '["PVC and PTFE", "PET and PLA", "Nylon-6,6 and Kevlar", "Terylene and nylon-6,6"]', 2, 'Both contain –CONH– links in their chains.', '{"0": "Both are addition polymers.", "1": "Both are polyesters.", "3": "Terylene is a polyester."}'),
  ('CHE-1012', 'Macromolecules', 'Identifying polymers', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 150 (§26.3)', 'To find the monomers of a condensation polymer from a section of its chain, you', '["add HCl across every C=O", "turn each C–C bond back into C=C", "remove all oxygen atoms", "break the ester or amide link, adding –OH to the C=O side and –H to the O or N side"]', 3, 'Adding back water reverses the condensation and gives the diacid and diol or diamine.', '{"0": "This is not how monomers are found.", "1": "That is done for addition polymers.", "2": "Monomers keep their oxygen atoms."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1013', 'Macromolecules', 'Predicting polymer type', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 151 (§26.4.2)', 'Lactic acid (2-hydroxypropanoic acid) can form a polymer on its own because', '["it has a C=C bond", "it has both –OH and –COOH groups in one molecule", "it is an amino acid", "it has two –COOH groups"]', 1, 'With both groups in one molecule, it can condense with itself to form a polyester, PLA.', '{"0": "Lactic acid has no C=C bond.", "2": "It has no amino group.", "3": "It has one –COOH."}'),
  ('CHE-1014', 'Macromolecules', 'Predicting polymer type', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 151 (§26.4.2)', 'A diol reacting with a dioyl chloride gives', '["a polyamide and H₂O", "a polyester and HCl", "a polyester and H₂O", "a polyamide and HCl"]', 1, '–OH and –COCl form ester links, eliminating HCl.', '{"0": "A polyamide needs an amine.", "2": "With an acyl chloride, HCl rather than water is lost.", "3": "A polyamide needs an amine."}'),
  ('CHE-1015', 'Macromolecules', 'Predicting polymer type', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 151 (§26.4.1)', 'Ethene and propenoic acid (H₂C=CH–COOH) can polymerize together to form', '["an addition copolymer", "a polyester", "a polyamide", "no polymer, since they are different"]', 0, 'Both monomers contain C=C, so they can undergo addition copolymerization.', '{"1": "Only one –COOH, and no –OH partner, is available.", "2": "There is no amine group.", "3": "Different alkenes can copolymerize."}'),
  ('CHE-1016', 'Macromolecules', 'Degradation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 152 (§26.5)', 'Microplastics are', '["tiny pieces formed when large non-degradable plastics break down", "biodegradable starch beads", "monomers released from PVC", "natural polymers in soil"]', 0, 'Large plastic debris breaks into tiny pieces that spread through soil, water and air and can enter the food chain.', '{"1": "They come from non-degradable plastics.", "2": "They are pieces of polymer, not monomers.", "3": "They are man-made pollution."}'),
  ('CHE-1017', 'Macromolecules', 'Degradation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 152–153 (§26.5.2)', 'A limitation of photodegradable plastics noted in the book is that', '["they cannot degrade when buried in landfills where there is no light", "they never break down", "they contain no carbonyl groups", "they are made of starch"]', 0, 'They depend on UV light; buried waste receives none. They also cannot be used for long or recycled efficiently.', '{"1": "They do break down in light.", "2": "Carbonyl groups are added to absorb UV.", "3": "That describes some biodegradable plastics."}'),
  ('CHE-1018', 'Macromolecules', 'Degradation', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 153 (§26.5.2)', 'Dissolvable stitches can be made from polyesters because polyesters', '["slowly break down in the body by hydrolysis", "are very inert", "are addition polymers", "conduct electricity"]', 0, 'The ester links are hydrolysed over time, so the stitches break down after healing.', '{"1": "Inertness would stop them dissolving.", "2": "Polyesters are condensation polymers.", "3": "This is irrelevant."}'),
  ('CHE-1019', 'Macromolecules', 'Artificial organs', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 153–154 (§26.6, Table 26.2)', 'Which polymer is used for artificial hip and knee joints for its smooth, low-friction surface?', '["Ultra-high molecular weight polyethylene (UHMWPE)", "PMMA", "Collagen", "PVC"]', 0, 'UHMWPE gives a smooth, wear-resistant bearing surface in joints.', '{"1": "PMMA is used for artificial corneas.", "2": "Collagen is used for artificial skin.", "3": "Not listed for joints."}'),
  ('CHE-1020', 'Macromolecules', 'Artificial organs', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 26 Polymers, p. 154 (Table 26.2)', 'An artificial cornea is made from PMMA or hydrogels because the material must be', '["transparent and biocompatible", "electrically conducting", "magnetic", "biodegradable within days"]', 0, 'To restore vision, the material must be perfectly clear and accepted by the body.', '{"1": "Conductivity is not needed.", "2": "Not relevant.", "3": "A cornea must last."}'),
  ('CHE-1021', 'Macromolecules', 'Carbohydrates', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 158 (§27.1)', 'Chemically, carbohydrates are', '["esters of fatty acids and glycerol", "polyhydroxy aldehydes or ketones, or compounds derived from them", "polymers of amino acids", "polymers of nucleotides"]', 1, 'The book defines carbohydrates as polyhydroxy aldehydes or ketones or their derivatives.', '{"0": "That describes fats and oils.", "2": "That describes proteins.", "3": "That describes nucleic acids."}'),
  ('CHE-1022', 'Macromolecules', 'Carbohydrates', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 158 (§27.1)', 'A monosaccharide with five carbon atoms is called a', '["hexose", "tetrose", "pentose", "triose"]', 2, 'Trioses have 3 C, tetroses 4, pentoses 5 and hexoses 6.', '{"0": "A hexose has six carbons.", "1": "A tetrose has four carbons.", "3": "A triose has three carbons."}'),
  ('CHE-1023', 'Macromolecules', 'Carbohydrates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 158 (§27.1)', 'In their ring forms, glucose and fructose form respectively', '["two five-membered furanose rings", "a five-membered furanose and a six-membered pyranose", "two six-membered pyranose rings", "a six-membered pyranose and a five-membered furanose"]', 3, 'Glucose (an aldohexose) cyclizes to a six-membered pyranose ring, fructose (a ketohexose) to a five-membered furanose ring.', '{"0": "Glucose forms a six-membered ring.", "1": "This is reversed.", "2": "Fructose forms a five-membered ring."}'),
  ('CHE-1024', 'Macromolecules', 'Carbohydrates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 158–159 (§27.1, margin)', 'The thickness of honey and the high water solubility of monosaccharides are both due to', '["ionic bonds in the sugars", "extensive hydrogen bonding through their many –OH groups", "the presence of glycosidic bonds", "their high molar masses"]', 1, 'Many –OH groups give strong hydrogen bonding between sugar molecules and with water.', '{"0": "Sugars are covalent, not ionic.", "2": "Monosaccharides have no glycosidic bonds.", "3": "Monosaccharides are small molecules."}'),
  ('CHE-1025', 'Macromolecules', 'Carbohydrates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 159 (§27.1)', 'Sucrose is formed from', '["glucose and galactose joined by an ester bond", "two glucose units joined by a peptide bond", "glucose and fructose joined by a glycosidic bond, with loss of water", "fructose and glycerol"]', 2, 'Sucrose is a disaccharide of glucose and fructose formed by condensation; the C–O–C link is a glycosidic bond.', '{"0": "That pairing gives lactose, and the link is glycosidic.", "1": "Peptide bonds join amino acids.", "3": "Glycerol is not a sugar unit of sucrose."}'),
  ('CHE-1026', 'Macromolecules', 'Carbohydrates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 159 (§27.1)', 'Which statement about starch is correct?', '["Starch is the main structural material of plant cell walls.", "Amylose is highly branched; amylopectin is unbranched.", "Starch is made of fructose units.", "Amylose is unbranched; amylopectin is highly branched."]', 3, 'Starch has two glucose polymers: unbranched amylose and compact, branched amylopectin.', '{"0": "That is cellulose.", "1": "This is reversed.", "2": "Starch is made of glucose units."}'),
  ('CHE-1027', 'Macromolecules', 'Carbohydrates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 159 (§27.1)', 'Cellulose is rigid and insoluble in water because', '["it is highly branched like glycogen", "its long unbranched glucose chains form strong hydrogen bonds with each other", "it contains peptide bonds", "it is made of fructose units"]', 1, 'Long straight chains line up and hydrogen-bond strongly to each other, giving rigid, insoluble fibres.', '{"0": "Cellulose is unbranched.", "2": "Cellulose has glycosidic bonds.", "3": "Cellulose is made of glucose."}'),
  ('CHE-1028', 'Macromolecules', 'Carbohydrates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 159 (§27.1)', 'Glycogen differs from amylopectin in that glycogen', '["is made of fructose", "is unbranched", "is more highly branched and is stored in the liver and muscles of animals", "is found in plant cell walls"]', 2, 'Glycogen (''animal starch'') is a glucose polymer like amylopectin but even more branched.', '{"0": "Glycogen is made of glucose.", "1": "Glycogen is highly branched.", "3": "Cellulose is found in plant cell walls."}'),
  ('CHE-1029', 'Macromolecules', 'Carbohydrates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 160 (§27.1.1)', 'According to the book, normal blood glucose lies between', '["70 and 110 mg/dL", "7 and 11 mg/dL", "700 and 1100 mg/dL", "15 and 16 mg/dL"]', 0, 'Normal values are about 70–110 mg/dL, controlled by insulin and glucagon.', '{"1": "Too low by a factor of ten.", "2": "Too high by a factor of ten.", "3": "15.6 is the energy value of glucose in kJ g⁻¹."}'),
  ('CHE-1030', 'Macromolecules', 'Carbohydrates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 160 (§27.1.1)', 'Diabetes occurs when', '["the body makes too much glucagon only", "the liver stores too much glycogen", "fructose replaces glucose in the blood", "the pancreas makes too little insulin or the body cannot use it well"]', 3, 'Insulin moves glucose from the blood into cells; too little insulin, or poor response to it, leads to high blood glucose.', '{"0": "The book links diabetes to insulin.", "1": "Glycogen storage is not the cause given.", "2": "This does not happen."}'),
  ('CHE-1031', 'Macromolecules', 'Proteins', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 161 (§27.2.1)', 'The primary structure of a protein is', '["the α-helix and β-pleated sheet", "the sequence of amino acids linked by peptide bonds", "the overall 3D folding of one chain", "the association of several chains"]', 1, 'The amino-acid sequence is the primary structure; it determines how the chain folds.', '{"0": "That is secondary structure.", "2": "That is tertiary structure.", "3": "That is quaternary structure."}'),
  ('CHE-1032', 'Macromolecules', 'Proteins', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 161 (margin)', 'Sickle cell anaemia shows that', '["red blood cells contain no protein", "proteins are not affected by their sequence", "a small change in the amino-acid sequence of haemoglobin can change the protein''s shape and function", "haemoglobin is a carbohydrate"]', 2, 'Abnormal haemoglobin deforms red cells into sickle shapes that clog vessels; a change in primary structure alters function.', '{"0": "Red cells are full of haemoglobin, a protein.", "1": "The example shows the opposite.", "3": "Haemoglobin is a protein."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1033', 'Macromolecules', 'Proteins', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 162 (§27.2.1)', 'The α-helix and β-pleated sheet are held in shape mainly by', '["phosphodiester bonds", "disulfide bridges only", "glycosidic bonds", "hydrogen bonds between backbone atoms"]', 3, 'Secondary structure comes from hydrogen bonding between backbone N–H and C=O groups, within one chain (α-helix) or between strands (β-sheet).', '{"0": "Phosphodiester bonds are in nucleic acids.", "1": "Disulfide bridges are R-group interactions in tertiary structure.", "2": "Glycosidic bonds are in carbohydrates."}'),
  ('CHE-1034', 'Macromolecules', 'Proteins', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 162 (§27.2.1)', 'Which pair matches the book''s examples of secondary structure?', '["α-helix: silk fibroin; β-pleated sheet: keratin", "α-helix: keratin; β-pleated sheet: silk fibroin", "α-helix: insulin; β-pleated sheet: haemoglobin", "α-helix: cellulose; β-pleated sheet: starch"]', 1, 'Keratin is coiled into α-helices; silk fibroin forms β-pleated sheets.', '{"0": "This is reversed.", "2": "Not the examples given.", "3": "These are carbohydrates."}'),
  ('CHE-1035', 'Macromolecules', 'Proteins', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 162 (§27.2.1)', 'Tertiary structure results from interactions between', '["separate polypeptide subunits only", "only the peptide bonds", "side chains (R groups): hydrogen bonds, ionic bonds, hydrophobic interactions and disulfide bridges", "sugar and phosphate groups"]', 2, 'R-group interactions fold the chain into its overall 3D shape, which sets its function.', '{"0": "Association of subunits is quaternary structure.", "1": "Peptide bonds define the primary sequence.", "3": "Sugar–phosphate is in nucleic acids."}'),
  ('CHE-1036', 'Macromolecules', 'Proteins', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 163 (§27.2.1)', 'Fibrous proteins such as collagen and keratin are', '["easily denatured by mild heat", "spherical and water-soluble", "mainly enzymes and hormones", "insoluble, mechanically strong and structural"]', 3, 'Long, parallel chains linked by hydrogen bonds or disulfide bonds give strong, insoluble fibres.', '{"0": "Globular proteins are the more heat-sensitive ones.", "1": "That describes globular proteins.", "2": "Enzymes and hormones are mostly globular."}'),
  ('CHE-1037', 'Macromolecules', 'Proteins', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 163 (§27.2.1)', 'Milk protein (casein) curdles when lemon juice is added because', '["lemon juice hydrolyses the peptide bonds", "the change in pH denatures the protein", "lemon juice adds sugar", "casein is a lipid"]', 1, 'Lowering the pH disrupts the bonds holding the protein''s shape, so it coagulates (denatures).', '{"0": "Denaturation does not break peptide bonds.", "2": "Sugar is not the cause.", "3": "Casein is a protein."}'),
  ('CHE-1038', 'Macromolecules', 'Proteins', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 164 (§27.2.2)', 'Ferritin is an example of a', '["hormonal protein", "contractile protein", "storage protein that stores iron", "defensive protein"]', 2, 'Ferritin is found in bacteria, plants and animals, where it stores iron.', '{"0": "Insulin is a hormonal protein.", "1": "Actin and myosin are contractile proteins.", "3": "Antibodies are defensive proteins."}'),
  ('CHE-1039', 'Macromolecules', 'Proteins', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 164 (§27.2.2)', 'Actin and myosin are', '["receptor proteins in cell membranes", "storage proteins of seeds", "carrier proteins in the blood", "contractile proteins of muscle filaments"]', 3, 'They form the thin and thick filaments that slide during muscle contraction.', '{"0": "Not receptor proteins.", "1": "Not storage proteins.", "2": "Haemoglobin is a carrier protein."}'),
  ('CHE-1040', 'Macromolecules', 'Enzymes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 164–165 (§27.3)', 'Enzymes are highly specific because', '["they are used up in the reaction", "the active site has a particular shape into which only a specific substrate fits", "they raise the activation energy", "they are carbohydrates"]', 1, 'The lock-and-key model (Fischer, 1894): the substrate (key) fits the active site (lock).', '{"0": "Enzymes are unchanged at the end.", "2": "Catalysts lower activation energy.", "3": "Enzymes are proteins."}'),
  ('CHE-1041', 'Macromolecules', 'Enzymes', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 164 (§27.3)', 'Which enzyme does the book use to show how fast enzymes work, converting about a million molecules of CO₂ and water per minute?', '["amylase", "pepsin", "carbonic anhydrase", "transpeptidase"]', 2, 'One molecule of carbonic anhydrase in blood converts about one million CO₂ and water molecules to carbonic acid per minute.', '{"0": "Not the example used.", "1": "Not the example used.", "3": "Transpeptidase is the target of penicillin."}'),
  ('CHE-1042', 'Macromolecules', 'Enzymes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 165 (§27.3.1)', 'If the temperature is raised well above the optimum, an enzyme''s activity falls because', '["more enzyme–substrate complex forms", "the substrate stops moving", "the enzyme becomes a carbohydrate", "the protein''s shape, including the active site, is disrupted"]', 3, 'Moving far from the optimum temperature or pH denatures the enzyme and deactivates it.', '{"0": "Fewer, not more, complexes form.", "1": "Higher temperature makes molecules move faster.", "2": "The enzyme remains a protein."}'),
  ('CHE-1043', 'Macromolecules', 'Enzymes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 165 (§27.3.2)', 'Malonate inhibits succinate dehydrogenase because it', '["permanently changes the shape of the enzyme", "resembles succinate and competes for the active site", "destroys the substrate", "raises the pH"]', 1, 'Malonate (propanedioate) is similar in shape to butanedioate (succinate), so it is a competitive inhibitor.', '{"0": "That describes non-competitive inhibition.", "2": "It does not destroy succinate.", "3": "pH change is not its mechanism."}'),
  ('CHE-1044', 'Macromolecules', 'Enzymes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 166 (§27.3.2)', 'Penicillin kills bacteria by', '["hydrolysing bacterial DNA", "competing with glucose for insulin", "irreversibly inhibiting transpeptidase, needed to build the bacterial cell wall", "acting as a substrate for bacterial enzymes"]', 2, 'Penicillin permanently blocks transpeptidase, so the cell wall cannot be made.', '{"0": "It does not hydrolyse DNA.", "1": "Unrelated to insulin.", "3": "It blocks, rather than feeds, the enzyme."}'),
  ('CHE-1045', 'Macromolecules', 'Lipids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 166 (§27.4)', 'Unlike polysaccharides and proteins, lipids are', '["made of amino acids", "polymers of glucose", "soluble in water", "not polymers and are soluble in organic solvents"]', 3, 'Lipids lack a repeating monomer unit; they are hydrophobic but dissolve in organic solvents.', '{"0": "Amino acids make proteins.", "1": "Glucose polymers are polysaccharides.", "2": "Lipids are hydrophobic."}'),
  ('CHE-1046', 'Macromolecules', 'Lipids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 166–167 (§27.4.1)', 'Fats are solid at room temperature while oils are liquid because', '["fats contain no glycerol", "fats contain mainly saturated fatty acids; oils contain unsaturated fatty acids with C=C bonds", "oils are polymers", "fats contain phosphate groups"]', 1, 'Both are triglycerides; saturated chains pack well (solid), while C=C bonds in oils prevent close packing.', '{"0": "Both contain glycerol.", "2": "Neither is a polymer.", "3": "Phosphate is in phospholipids."}'),
  ('CHE-1047', 'Macromolecules', 'Lipids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 167 (§27.4.2)', 'A phospholipid differs from a triglyceride in having', '["a steroid nucleus", "three fatty acids and no glycerol", "two fatty acids and a phosphate group on glycerol", "a peptide bond"]', 2, 'The third –OH of glycerol carries a phosphate group, giving a polar head and two hydrophobic tails.', '{"0": "Steroids have a four-ring nucleus.", "1": "Phospholipids contain glycerol.", "3": "No peptide bond is present."}'),
  ('CHE-1048', 'Macromolecules', 'Lipids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 168 (§27.4.3)', 'The steroid nucleus consists of', '["a glycerol unit and three fatty acids", "four benzene rings", "two glucose rings", "three cyclohexane rings and one cyclopentane ring fused together"]', 3, 'The four fused rings are labelled A, B, C and D; examples include cholesterol, bile salts and vitamin D.', '{"0": "That is a triglyceride.", "1": "The rings are not benzene rings.", "2": "Steroids are not sugars."}'),
  ('CHE-1049', 'Macromolecules', 'Lipids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 168 (§27.4.3)', 'Terpenes are built from', '["glucose units", "isoprene units", "amino acids", "nucleotides"]', 1, 'Terpenes are plant hydrocarbons made of isoprene units; those with 40 carbons are carotenoids.', '{"0": "Glucose units make polysaccharides.", "2": "Amino acids make proteins.", "3": "Nucleotides make nucleic acids."}'),
  ('CHE-1050', 'Macromolecules', 'Lipids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 168–169 (§27.4.4)', 'Hibernating animals store fat rather than relying mainly on glycogen because fat', '["is stored in the liver only", "dissolves easily in blood", "releases more energy per gram when oxidized", "contains nitrogen"]', 2, 'Fat is a more concentrated energy source than glycogen, giving more energy per gram on oxidation to CO₂ and water.', '{"0": "Fat is stored in adipose tissue, not only liver.", "1": "Fats are hydrophobic.", "3": "Fats contain C, H and O."}'),
  ('CHE-1051', 'Macromolecules', 'Lipids', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 168 (§27.4.4)', 'Which group of vitamins depends on lipids for absorption?', '["C only", "B and C", "B₁ and B₁₂ only", "A, D, E and K"]', 3, 'Lipids act as solvents for the fat-soluble vitamins A, D, E and K.', '{"0": "Vitamin C is water-soluble.", "1": "These are water-soluble.", "2": "These are water-soluble."}'),
  ('CHE-1052', 'Macromolecules', 'Nucleic acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 169 (§27.5)', 'In nucleic acids, nucleotides are joined by', '["phosphodiester links between the 5′ and 3′ carbons of the sugars", "peptide bonds between bases", "glycosidic bonds between phosphate groups", "hydrogen bonds between sugars"]', 0, 'Strong covalent phosphodiester links form the sugar–phosphate backbone.', '{"1": "Peptide bonds are in proteins.", "2": "Not how the backbone is linked.", "3": "Hydrogen bonds join bases on opposite strands."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1053', 'Macromolecules', 'Nucleic acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 170 (§27.5.1)', 'In DNA, the number of hydrogen bonds is', '["two between A and T, and three between G and C", "three between A and T, and two between G and C", "two in each base pair", "three in each base pair"]', 0, 'A pairs with T by two hydrogen bonds and G with C by three.', '{"1": "This is reversed.", "2": "G–C has three.", "3": "A–T has two."}'),
  ('CHE-1054', 'Macromolecules', 'Nucleic acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 170 (§27.5.1)', 'The double-helix structure of DNA was proposed in 1953 by', '["Watson and Crick", "Emil Fischer", "Woodward and Eschenmoser", "Ziegler and Natta"]', 0, 'Watson and Crick showed DNA is two right-handed polynucleotide chains coiled into a double helix.', '{"1": "Fischer proposed the lock-and-key model.", "2": "They synthesized vitamin B₁₂.", "3": "They developed polymerization catalysts."}'),
  ('CHE-1055', 'Macromolecules', 'Nucleic acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 170 (Fig. 27.14)', 'A codon is', '["a group of three bases that codes for one amino acid", "a section of a chromosome that makes one protein", "a pair of chromosomes", "the sugar–phosphate backbone"]', 0, 'Genome → chromosome → gene → DNA → codon; a codon is a three-base code for an amino acid.', '{"1": "That is a gene.", "2": "Humans have 23 pairs of chromosomes.", "3": "The backbone carries the bases but is not a codon."}'),
  ('CHE-1056', 'Macromolecules', 'Nucleic acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 171 (§27.5.2)', 'Which type of RNA carries amino acids and matches them to the mRNA code during translation?', '["tRNA", "mRNA", "rRNA", "DNA"]', 0, 'Transfer RNA translates the nucleotide sequence in mRNA into the matching sequence of amino acids.', '{"1": "mRNA carries the code copied from DNA.", "2": "rRNA helps make up the ribosome.", "3": "DNA stays in the nucleus."}'),
  ('CHE-1057', 'Macromolecules', 'Nucleic acids', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 171 (§27.5.3)', 'Copying a gene''s instructions from DNA into mRNA in the nucleus is called', '["transcription", "translation", "replication", "denaturation"]', 0, 'Transcription makes mRNA; translation at the ribosome turns the code into a protein.', '{"1": "Translation happens at ribosomes.", "2": "Replication copies DNA itself.", "3": "Denaturation is loss of protein shape."}'),
  ('CHE-1058', 'Macromolecules', 'Minerals', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 172 (Table 27.1)', 'Which mineral is needed for normal blood clotting as well as bones and teeth?', '["calcium", "iron", "zinc", "sodium"]', 0, 'Calcium is needed for bones and teeth, blood clotting, muscle contraction and nerve function.', '{"1": "Iron is for haemoglobin and oxygen transport.", "2": "Zinc is in enzymes and insulin.", "3": "Sodium is for fluid balance and nerves."}'),
  ('CHE-1059', 'Macromolecules', 'Minerals', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 172 (Table 27.1)', 'Which mineral is found in the hormone insulin and in many enzyme systems?', '["zinc", "calcium", "phosphorus", "iron"]', 0, 'Table 27.1 lists zinc as part of many enzymes and found in insulin.', '{"1": "Calcium is for bones, clotting and muscles.", "2": "Phosphorus is in bones, ATP and phospholipids.", "3": "Iron is in haemoglobin and myoglobin."}'),
  ('CHE-1060', 'Macromolecules', 'Minerals', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 27 Biochemistry, p. 172 (Table 27.1)', 'Phosphorus is involved in', '["ATP and the release of body energy, and in phospholipids", "haemoglobin synthesis", "the hormone insulin", "blood clotting only"]', 0, 'Phosphorus forms bones and teeth, regulates energy use through ATP, is part of phospholipids and helps acid–base balance.', '{"1": "That is iron.", "2": "That is zinc.", "3": "That is a role of calcium."}'),
  ('CHE-1061', 'Experimental techniques and lab safety', 'Basics', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 175 (§28.1)', 'Chromatography separates the components of a mixture on the basis of their', '["different affinities for a stationary phase and a mobile phase", "different colours only", "different densities", "different melting points"]', 0, 'Components are distributed differently between the two phases, so they move at different rates.', '{"1": "Colourless substances can also be separated.", "2": "Density is not the basis.", "3": "Melting point is not the basis."}'),
  ('CHE-1062', 'Experimental techniques and lab safety', 'Basics', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 175 (§28.1)', 'Activated charcoal is used in gas filters because it', '["reacts chemically with all gases", "adsorbs gases and impurities onto its surface", "dissolves gases completely", "absorbs water into its interior only"]', 1, 'Adsorption is a surface effect: particles accumulate on the outer surface of the charcoal.', '{"0": "It is a physical surface effect.", "2": "Adsorption is not dissolving.", "3": "Adsorption happens at the surface."}'),
  ('CHE-1063', 'Experimental techniques and lab safety', 'Paper chromatography', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 176 (§28.2)', 'In paper chromatography, the stationary phase is', '["an inert gas", "the organic solvent", "silica gel", "water held by the cellulose of the paper"]', 3, 'The paper''s cellulose holds water; the solvent moving up is the mobile phase. Separation depends on relative solubility (partition).', '{"0": "An inert gas is the mobile phase in GC.", "1": "The solvent is the mobile phase.", "2": "Silica is used in TLC."}'),
  ('CHE-1064', 'Experimental techniques and lab safety', 'Rf value', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 176 (§28.2)', 'The Rf value of a substance is', '["distance moved by the solvent ÷ distance moved by the substance", "time taken for the substance to leave the column", "distance moved by the substance ÷ distance moved by the solvent front", "the area under its peak"]', 2, 'Rf is a ratio of distances from the baseline, so it has no unit and is always ≤ 1.', '{"0": "This is the inverse.", "1": "That is retention time in GC.", "3": "Peak area measures amount in GC."}'),
  ('CHE-1065', 'Experimental techniques and lab safety', 'Rf value', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 176 (§28.2)', 'In a chromatogram the solvent front is 12.0 cm and a spot is 4.8 cm from the baseline. The Rf value of the spot is', '["2.5", "0.40", "0.25", "7.2"]', 1, 'Rf = 4.8 ÷ 12.0 = 0.40.', '{"0": "This is 12.0 ÷ 4.8, the inverse.", "2": "Incorrect division.", "3": "This is the difference in cm, not a ratio."}'),
  ('CHE-1066', 'Experimental techniques and lab safety', 'Rf value', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 176 (§28.2)', 'A spot has Rf = 0.65 and the solvent front moved 8.0 cm. How far did the spot travel?', '["5.2 cm", "12.3 cm", "0.65 cm", "7.35 cm"]', 0, 'Distance = Rf × solvent distance = 0.65 × 8.0 = 5.2 cm.', '{"1": "This is 8.0 ÷ 0.65; a spot cannot move further than the solvent.", "2": "Rf has no unit; it is not a distance.", "3": "Subtracting is not correct."}'),
  ('CHE-1067', 'Experimental techniques and lab safety', 'Rf value', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 176 (§28.2)', 'The Rf value of a given substance stays the same only if', '["the same solvent and the same temperature are used", "the spot is made larger", "the paper is longer", "the solvent is allowed to run off the top"]', 0, 'Rf is constant under the same conditions, which lets it be compared with standard values.', '{"1": "Spot size does not set Rf.", "2": "Rf is a ratio, independent of paper length.", "3": "The solvent front must be marked, so it must not run off."}'),
  ('CHE-1068', 'Experimental techniques and lab safety', 'Paper chromatography', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 176 (§28.2)', 'A colourless substance on a chromatogram can be made visible by', '["using a longer paper", "heating the solvent", "adding more sample", "spraying a locating agent"]', 3, 'Locating agents (e.g. ninhydrin for amino acids) give colour to colourless spots.', '{"0": "Paper length does not reveal spots.", "1": "Heating does not reveal spots.", "2": "More sample does not give colour."}'),
  ('CHE-1069', 'Experimental techniques and lab safety', 'TLC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 176 (§28.3)', 'The stationary phase in TLC is made by', '["soaking filter paper in water", "coating a column with a non-volatile liquid", "spreading a slurry of alumina or silica on a glass slide and drying it", "using helium gas"]', 2, 'A thin, dried white layer of Al₂O₃ or SiO₂ on glass is the stationary phase.', '{"0": "That is paper chromatography.", "1": "That describes GC.", "3": "Helium is a GC carrier gas."}'),
  ('CHE-1070', 'Experimental techniques and lab safety', 'TLC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 177 (§28.3)', 'Using TLC on alumina with a non-polar solvent, a mixture of butanone (polar) and pentane (non-polar) separates because', '["both move the same distance", "butanone is adsorbed more strongly and moves less; pentane moves further", "pentane is adsorbed more strongly and moves less", "butanone reacts with alumina"]', 1, 'Polar compounds are held more strongly by the polar solid and travel slowly; non-polar compounds stay in the non-polar solvent and travel further.', '{"0": "Different polarities give different distances.", "2": "Non-polar pentane is adsorbed less.", "3": "No reaction occurs; it is adsorption."}'),
  ('CHE-1071', 'Experimental techniques and lab safety', 'TLC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 177 (§28.3)', 'Which locating method is mentioned for colourless spots on a TLC plate?', '["litmus paper", "Fehling''s solution", "flame test", "UV light or iodine vapour"]', 3, 'Some colourless substances glow under UV light; others turn brown with iodine vapour. Ninhydrin is used for amino acids.', '{"0": "Litmus tests acidity.", "1": "Fehling''s tests aldehydes in solution.", "2": "Flame tests identify metal ions."}'),
  ('CHE-1072', 'Experimental techniques and lab safety', 'TLC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 177 (§28.3)', 'Which is an application of TLC given in the book?', '["large-scale purification of drugs", "measuring molar mass exactly", "following the progress of a reaction", "separating proteins by size in a gas stream"]', 2, 'TLC shows whether reactants are used up and products formed; it is also used for purity checks and forensic work.', '{"0": "TLC is not suitable for large-scale separation.", "1": "TLC does not give molar mass.", "3": "That is not TLC."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1073', 'Experimental techniques and lab safety', 'TLC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 177–178 (§28.3)', 'A limitation of TLC is that it', '["only works for volatile compounds", "cannot clearly separate compounds with very similar Rf values", "needs a gas as the mobile phase", "requires large samples"]', 1, 'Close Rf values give poorly resolved spots. TLC is also mainly qualitative and sensitive to humidity and temperature.', '{"0": "Volatility is a GC requirement.", "2": "TLC uses a liquid mobile phase.", "3": "TLC uses only small samples."}'),
  ('CHE-1074', 'Experimental techniques and lab safety', 'GC', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 178 (§28.4)', 'In gas chromatography, the mobile phase is', '["solid silica", "water held in paper", "a polar organic solvent", "an inert carrier gas such as helium or nitrogen"]', 3, 'An inert carrier gas carries the vaporized sample through the column.', '{"0": "Silica supports the stationary liquid.", "1": "That is the stationary phase in paper chromatography.", "2": "GC uses a gas mobile phase."}'),
  ('CHE-1075', 'Experimental techniques and lab safety', 'GC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 178 (§28.4)', 'In GC with a non-polar stationary liquid, non-polar components', '["pass through fastest", "are not detected", "interact more with the stationary phase and have longer retention times", "react with the carrier gas"]', 2, 'Substances that interact more strongly with the stationary phase move more slowly through the column.', '{"0": "Strong interaction slows them down.", "1": "All components reach the detector.", "3": "The carrier gas is inert."}'),
  ('CHE-1076', 'Experimental techniques and lab safety', 'GC', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 179 (§28.4)', 'Retention time in GC is', '["the area of a peak", "the time a substance takes to pass through the column", "the distance a spot travels", "the time to vaporize the sample"]', 1, 'The detector records the time each component takes to travel through the column.', '{"0": "Peak area shows amount.", "2": "That relates to Rf.", "3": "Vaporization in the injector is very quick."}'),
  ('CHE-1077', 'Experimental techniques and lab safety', 'GC', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 179 (§28.4)', 'A gas chromatogram of esters A, B and C gives peak areas of 30, 50 and 20 units. The percentage of A is', '["20%", "50%", "30%", "60%"]', 2, '% A = 30 ÷ (30 + 50 + 20) × 100 = 30%.', '{"0": "That is the percentage of C.", "1": "That is the percentage of B.", "3": "This is 30 ÷ 50 × 100, which ignores C."}'),
  ('CHE-1078', 'Experimental techniques and lab safety', 'GC', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 179 (§28.4)', 'A triangular GC peak has a base of 0.8 cm and height of 5.0 cm. Its area is', '["2.0 cm²", "4.0 cm²", "5.8 cm²", "6.25 cm²"]', 0, 'Area = ½ × base × height = ½ × 0.8 × 5.0 = 2.0 cm².', '{"1": "This forgets the ½.", "2": "This adds base and height.", "3": "Incorrect formula."}'),
  ('CHE-1079', 'Experimental techniques and lab safety', 'GC', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 180 (§28.4)', 'Which cannot be analysed by GC?', '["ethanol in blood", "a mixture of gases", "volatile esters", "proteins"]', 3, 'Large biomolecules such as proteins do not vaporize; GC needs volatile, thermally stable samples.', '{"0": "GC is used for blood alcohol tests.", "1": "Gas mixtures separate easily by GC.", "2": "Volatile esters suit GC."}'),
  ('CHE-1080', 'Experimental techniques and lab safety', 'GC', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 179 (§28.4)', 'Which is a forensic use of GC mentioned in the book?', '["blood alcohol content tests", "DNA sequencing", "fingerprint dusting", "measuring blood pressure"]', 0, 'Forensic laboratories use GC for blood alcohol tests and to detect drugs, poisons and performance enhancers.', '{"1": "Not done by GC.", "2": "Not a chromatographic method.", "3": "Not a chemical analysis."}'),
  ('CHE-1081', 'Experimental techniques and lab safety', 'Comparison', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 180 (§28.5)', 'Which correctly lists the three methods from slowest to fastest, according to the comparison table?', '["TLC < paper < GC", "paper < TLC < GC", "GC < TLC < paper", "paper < GC < TLC"]', 1, 'The table gives paper as slow, TLC faster and GC very fast.', '{"0": "TLC is faster than paper.", "2": "This is reversed.", "3": "GC is the fastest."}'),
  ('CHE-1082', 'Experimental techniques and lab safety', 'Comparison', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 28 Chromatography, p. 180 (§28.5)', 'In gas chromatography the stationary phase is', '["dry silica alone", "water in paper", "a non-volatile liquid on solid particles", "helium"]', 2, 'A high-boiling, non-volatile liquid coated on silica or alumina is the stationary phase (gas–liquid partition).', '{"0": "Dry silica is the TLC stationary phase.", "1": "That is paper chromatography.", "3": "Helium is the mobile phase."}'),
  ('CHE-1083', 'Spectroscopy', 'Radiation', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 183–184', 'Which relation between energy, frequency and wavelength of radiation is correct?', '["E = h/ν", "E = hν = hc/λ", "E = hλ/c", "E = c/hλ"]', 1, 'Energy is directly proportional to frequency (E = hν) and, since c = λν, inversely proportional to wavelength.', '{"0": "E is proportional to ν, not inversely.", "2": "E is inversely proportional to λ.", "3": "Incorrect rearrangement."}'),
  ('CHE-1084', 'Spectroscopy', 'Radiation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 184 (Fig. 29.1)', 'Which type of radiation has the highest energy per photon?', '["infrared", "ultraviolet", "gamma rays", "radio waves"]', 2, 'Gamma rays have the shortest wavelength and highest frequency, so the highest energy.', '{"0": "IR is lower in energy than visible light.", "1": "UV has less energy than X-rays and gamma rays.", "3": "Radio waves have the lowest energy."}'),
  ('CHE-1085', 'Spectroscopy', 'IHD', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 184–185 (§29.1)', 'Hex-1-ene and cyclohexane (both C₆H₁₂) each have an IHD of', '["6", "0", "2", "1"]', 3, 'Each has two H fewer than hexane (C₆H₁₄): one C=C in hexene, one ring in cyclohexane.', '{"0": "That is the number of carbons.", "1": "IHD 0 would be C₆H₁₄.", "2": "IHD 2 would be C₆H₁₀."}'),
  ('CHE-1086', 'Spectroscopy', 'IHD', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 185 (§29.1)', 'The IHD of benzene, C₆H₆, is', '["4", "3", "6", "1"]', 0, 'Saturated C₆H₁₄ has 8 more H; 8 ÷ 2 = 4 (three C=C and one ring).', '{"1": "This counts only the three double bonds and misses the ring.", "2": "This is the number of carbons.", "3": "Benzene is far more unsaturated."}'),
  ('CHE-1087', 'Spectroscopy', 'IHD', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 185 (§29.1, Quick Check)', 'A hopane, C₃₀H₅₂, has an IHD of', '["5", "0", "4", "10"]', 0, 'Saturated C₃₀H₆₂ has 10 more H; 10 ÷ 2 = 5 (hopanes are ring compounds).', '{"1": "That would need C₃₀H₆₂.", "2": "Miscounted.", "3": "This is the H deficit, not pairs."}'),
  ('CHE-1088', 'Spectroscopy', 'IHD', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 185 (§29.1)', 'A compound has IHD = 2. Which structure is not possible?', '["one ring and one C=C bond", "one triple bond", "two rings", "one ring and two C=C bonds"]', 3, 'A ring or a double bond each count 1 and a triple bond counts 2. One ring + two C=C gives 3.', '{"0": "One ring + one double bond gives 2.", "1": "A triple bond counts as 2.", "2": "Two rings give 2."}'),
  ('CHE-1089', 'Spectroscopy', 'Atomic spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 186 (§29.2)', 'An atomic emission spectrum consists of', '["dark lines on a coloured background", "coloured lines on a black background, from electrons falling to lower levels", "a continuous rainbow", "a single broad band"]', 1, 'Excited electrons drop to lower energy levels and emit photons of definite wavelengths, seen as bright lines.', '{"0": "That is an absorption spectrum.", "2": "Atomic spectra are line spectra.", "3": "Atomic spectra have separate lines."}'),
  ('CHE-1090', 'Spectroscopy', 'Atomic spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 186 (§29.2)', 'An absorption spectrum is produced by', '["passing electrons through a magnet", "heating a low-pressure gas until it glows", "passing white light through a cool, low-pressure gas", "burning the element in air only"]', 2, 'Only photons with exactly the energy to excite electrons are absorbed, giving dark lines at the same positions as the emission lines.', '{"0": "That is not how absorption spectra form.", "1": "That gives an emission spectrum.", "3": "Burning gives emission."}'),
  ('CHE-1091', 'Spectroscopy', 'Atomic spectra', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 187 (§29.3)', 'The yellow flame of sodium is due to its strong emission line at about', '["589 nm", "656 nm", "410 nm", "217 nm"]', 0, 'Sodium''s strong lines at 589 nm are in the yellow part of the visible spectrum.', '{"1": "656 nm is hydrogen''s red line.", "2": "410 nm is a violet hydrogen line.", "3": "217 nm is λmax of buta-1,3-diene."}'),
  ('CHE-1092', 'Spectroscopy', 'Atomic spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 187 (§29.3)', 'Elements can be identified by their atomic emission spectra because', '["only metals give spectra", "all elements give the same lines", "the lines depend only on temperature", "each element produces a unique set of spectral lines"]', 3, 'Emission line spectra are like fingerprints; they even reveal the composition of stars.', '{"0": "Hydrogen, a non-metal, gives a well-known spectrum.", "1": "No two elements give the same set.", "2": "Line positions depend on the element''s energy levels."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1093', 'Spectroscopy', 'UV-Vis', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 187 (§29.4)', 'In UV-Vis spectroscopy, absorbance A is obtained from transmittance T by', '["A = log T", "A = −log T", "A = 1/T", "A = 100 − T"]', 1, 'The book gives A = −log(T).', '{"0": "The sign is wrong.", "2": "Not the relation.", "3": "Not the relation."}'),
  ('CHE-1094', 'Spectroscopy', 'UV-Vis', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 187 (§29.4, Fig. 29.4)', 'Which order of orbital energies is given in the book (lowest first)?', '["π < σ < n < σ* < π*", "n < π < σ < π* < σ*", "σ < π < n < π* < σ*", "σ < n < π < σ* < π*"]', 2, 'σ bonding is lowest, then π bonding, then non-bonding n; the empty antibonding π* lies below σ*.', '{"0": "σ is the lowest.", "1": "n lies above the bonding orbitals.", "3": "π lies below n, and π* below σ*."}'),
  ('CHE-1095', 'Spectroscopy', 'UV-Vis', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 188 (§29.4)', 'Buta-1,3-diene has λmax = 217 nm and no non-bonding electrons. Its absorption is due to', '["d–d transitions", "n → π* transitions, giving a blue colour", "σ → σ* transitions in the visible region", "π → π* transitions, and the compound is colourless"]', 3, 'Only π → π* jumps occur in the measured range; 217 nm is in the UV, so no visible light is absorbed.', '{"0": "There are no d electrons.", "1": "It has no non-bonding electrons.", "2": "217 nm is in the UV, and σ → σ* needs even shorter wavelengths."}'),
  ('CHE-1096', 'Spectroscopy', 'UV-Vis', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 188 (§29.4)', 'λmax values are 217 nm for butadiene, 257 nm for hexatriene and 290 nm for octatetraene. This shows that more conjugation', '["raises the energy gap", "lowers the energy gap so longer wavelengths are absorbed", "has no effect on λmax", "makes compounds absorb only X-rays"]', 1, 'Each extra conjugated C=C shrinks the HOMO–LUMO gap and moves λmax up by about 30–40 nm.', '{"0": "The gap decreases.", "2": "λmax clearly increases.", "3": "Absorption shifts toward the visible."}'),
  ('CHE-1097', 'Spectroscopy', 'UV-Vis', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 189 (Interesting Information)', 'Green and red tomatoes differ in colour because chlorophyll and lycopene', '["both absorb only in the UV", "absorb only infrared", "have different λmax values in the visible region", "are not conjugated"]', 2, 'Each pigment absorbs a different visible wavelength (different λmax), so each shows a different colour.', '{"0": "UV-only absorbers are colourless.", "1": "Colour comes from visible absorption.", "3": "Both are highly conjugated."}'),
  ('CHE-1098', 'Spectroscopy', 'IR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 189 (§29.5)', 'A molecule absorbs infrared radiation only if', '["it has unpaired electrons", "it contains a metal", "it is symmetrical and non-polar", "its dipole moment changes as it vibrates"]', 3, 'IR absorption needs a vibration that changes the dipole; O₂ and H₂ are IR inactive.', '{"0": "Not required.", "1": "Not required.", "2": "Symmetrical non-polar molecules like H₂ are inactive."}'),
  ('CHE-1099', 'Spectroscopy', 'IR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 189 (§29.5)', 'Bonds such as O–H and C≡C absorb at higher wavenumbers mainly because they are', '["longer and weaker", "stronger, needing more energy to vibrate", "ionic", "non-polar"]', 1, 'Strong, short or multiple bonds have higher vibrational frequencies.', '{"0": "Longer, weaker bonds absorb lower.", "2": "They are covalent.", "3": "O–H is polar."}'),
  ('CHE-1100', 'Spectroscopy', 'IR', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 189 (§29.5)', 'The fingerprint region of an IR spectrum lies', '["between 2200 and 2250 cm⁻¹", "above 3000 cm⁻¹ only", "below 1500 cm⁻¹", "in the UV region"]', 2, 'Below 1500 cm⁻¹ is the fingerprint region; above 1500 cm⁻¹ is the functional-group region.', '{"0": "That is the C≡N range.", "1": "That is part of the functional-group region.", "3": "IR is not UV."}'),
  ('CHE-1101', 'Spectroscopy', 'IR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 190 (Table 29.2)', 'A strong, sharp absorption near 1710 cm⁻¹ and no broad band at 3200–3600 cm⁻¹ suggests', '["a nitrile", "an alcohol such as propan-2-ol", "an alkane", "a ketone such as propanone"]', 3, '1710 cm⁻¹ is a C=O stretch; the missing broad O–H band rules out an alcohol.', '{"0": "Nitriles absorb at 2200–2250 cm⁻¹.", "1": "An alcohol shows a broad O–H at 3200–3600 cm⁻¹.", "2": "Alkanes have no C=O."}'),
  ('CHE-1102', 'Spectroscopy', 'IR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 190–191 (Table 29.2)', 'A carboxylic acid is recognized in IR by', '["a sharp peak at 2200 cm⁻¹ only", "a C=O peak near 1700 cm⁻¹ and a very broad O–H band from 2500 to 3300 cm⁻¹", "two weak peaks at 3300 and 3400 cm⁻¹ only", "no peaks above 1500 cm⁻¹"]', 1, 'The acid O–H band is broad and overlaps the C–H peaks; C=O is near 1700 cm⁻¹.', '{"0": "That is C≡N.", "2": "That is a primary amine N–H.", "3": "Acids have strong peaks above 1500 cm⁻¹."}'),
  ('CHE-1103', 'Spectroscopy', 'IR', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 190 (Table 29.2)', 'The C≡N stretch of a nitrile appears at about', '["2200–2250 cm⁻¹", "1710–1750 cm⁻¹", "3200–3600 cm⁻¹", "2850–2950 cm⁻¹"]', 0, 'Table 29.2 lists nitriles at 2200–2250 cm⁻¹.', '{"1": "That is an ester C=O.", "2": "That is an alcohol O–H.", "3": "That is alkane C–H."}'),
  ('CHE-1104', 'Spectroscopy', 'IR', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 189 (Did You Know?)', 'Modern roadside breathalysers measure ethanol in breath using', '["mass spectrometry", "UV absorption by conjugated systems", "infrared absorption by ethanol''s bonds", "paper chromatography"]', 2, 'IR radiation passed through the breath is absorbed by the characteristic bonds of ethanol; more absorption means more ethanol.', '{"0": "Not the method described.", "1": "Ethanol has no conjugated system.", "3": "Not the method described."}'),
  ('CHE-1105', 'Spectroscopy', 'Mass spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 192 (§29.6.1)', 'Boron has 19.9% ¹⁰B and 80.1% ¹¹B. Its relative atomic mass is', '["10.80", "10.50", "10.20", "11.00"]', 0, 'Ar = (19.9 × 10 + 80.1 × 11) ÷ 100 = 10.80.', '{"1": "This is a simple average of 10 and 11.", "2": "This gives too much weight to ¹⁰B.", "3": "Ignores ¹⁰B."}'),
  ('CHE-1106', 'Spectroscopy', 'Mass spectra', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 192 (§29.6.1)', 'Chlorine is 75% ³⁵Cl and 25% ³⁷Cl. Its relative atomic mass is', '["35.5", "36.0", "35.0", "36.5"]', 0, 'Ar = (75 × 35 + 25 × 37) ÷ 100 = (2625 + 925) ÷ 100 = 35.5.', '{"1": "This is a simple average.", "2": "Ignores ³⁷Cl.", "3": "Weights the isotopes the wrong way round."}'),
  ('CHE-1107', 'Spectroscopy', 'Mass spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 193 (§29.6.2)', 'The molecular ion M⁺ in a mass spectrum is', '["always the tallest peak", "the smallest fragment", "the molecule that has gained a proton", "the whole molecule that has lost one electron"]', 3, 'Electron bombardment removes one electron from the molecule, giving a radical cation whose m/e equals Mr.', '{"0": "The tallest peak is often a fragment.", "1": "Fragments come from breaking M⁺.", "2": "M⁺ forms by losing an electron."}'),
  ('CHE-1108', 'Spectroscopy', 'Mass spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 193 (Example 29.4)', 'A mass spectrum has its molecular ion peak at m/e = 72. Which aldehyde could it be?', '["propanal, CH₃CH₂CHO", "butanal, CH₃CH₂CH₂CHO", "ethanal, CH₃CHO", "pentanal, C₄H₉CHO"]', 1, 'C₄H₈O has Mr = 4(12) + 8(1) + 16 = 72.', '{"0": "Propanal''s M⁺ is 58.", "2": "Ethanal''s M⁺ is 44.", "3": "Pentanal''s M⁺ is 86."}'),
  ('CHE-1109', 'Spectroscopy', 'Mass spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 194 (Table 29.3)', 'In the mass spectrum of hexane, the fragment at m/e = 43 is', '["CH₃⁺", "CH₃CH₂⁺", "CH₃CH₂CH₂⁺", "C₄H₉⁺"]', 2, 'C₃H₇⁺ = 3(12) + 7 = 43. Other hexane fragments are 86, 71, 57, 29 and 15.', '{"0": "CH₃⁺ is 15.", "1": "C₂H₅⁺ is 29.", "3": "C₄H₉⁺ is 57."}'),
  ('CHE-1110', 'Spectroscopy', 'Mass spectra', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 194 (§29.6.2 c)', 'A compound''s M⁺ peak has relative abundance 40 and its [M+1] peak has abundance 2.2. The number of carbon atoms is', '["5", "4", "2", "11"]', 0, 'n = (100 × 2.2) ÷ (1.1 × 40) = 220 ÷ 44 = 5.', '{"1": "Miscalculated.", "2": "Miscalculated.", "3": "Forgets the abundance of M⁺."}'),
  ('CHE-1111', 'Spectroscopy', 'Mass spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 194 (§29.6.2 c)', 'The [M+1] peak arises because', '["chlorine has two isotopes", "the molecule gains a hydrogen atom", "deuterium is very common", "about 1.1% of carbon atoms are ¹³C"]', 3, '¹³C (about 1.1% of carbon) makes some molecules one unit heavier; more carbons give a larger [M+1] peak.', '{"0": "Chlorine gives [M+2] peaks.", "1": "It is an isotope effect, not added H.", "2": "Deuterium is rare."}'),
  ('CHE-1112', 'Spectroscopy', 'Mass spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 195 (§29.6.2 c)', 'A compound with one bromine atom shows M and [M+2] peaks in the ratio', '["1 : 1", "3 : 1", "9 : 6 : 1", "1 : 2 : 1"]', 0, '⁷⁹Br and ⁸¹Br are almost equally abundant, so the two peaks are of similar height.', '{"1": "3 : 1 is for one Cl.", "2": "That is for two Cl atoms.", "3": "That is for two Br atoms."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1113', 'Spectroscopy', 'Mass spectra', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 195 (§29.6.2 c)', 'A compound shows molecular ion peaks at M, M+2 and M+4 in the ratio 9 : 6 : 1. It contains', '["one chlorine atom", "two chlorine atoms", "two bromine atoms", "one bromine atom"]', 1, 'With two Cl atoms the combinations ³⁵Cl³⁵Cl, ³⁵Cl³⁷Cl and ³⁷Cl³⁷Cl give 9 : 6 : 1.', '{"0": "One Cl gives two peaks, 3 : 1.", "2": "Two Br give 1 : 2 : 1.", "3": "One Br gives 1 : 1."}'),
  ('CHE-1114', 'Spectroscopy', 'Mass spectra', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 29 Spectroscopy-1, p. 196 (Quick Check 29.3)', 'CH₃Br shows two molecular ion peaks at m/e 94 and 96 because', '["carbon has two isotopes in equal amounts", "the molecule fragments into two pieces", "bromine has two isotopes, ⁷⁹Br and ⁸¹Br", "hydrogen is lost"]', 2, 'CH₃⁷⁹Br = 94 and CH₃⁸¹Br = 96, in about a 1 : 1 ratio.', '{"0": "¹³C is only 1.1%.", "1": "Fragments have lower m/e than M⁺.", "3": "Losing H would lower m/e."}'),
  ('CHE-1115', 'Spectroscopy', 'Principle', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 199 (§30.1)', 'When nuclei such as ¹H are placed in a strong magnetic field, they', '["align with or against the field, giving a lower and a higher energy spin state", "all align with the field in one energy state", "lose their spin", "emit X-rays"]', 0, 'Two spin states arise; radio waves of the right energy flip nuclei from the lower to the higher state.', '{"1": "There are two orientations, not one.", "2": "The spin is what makes them magnetic.", "3": "NMR uses radio waves."}'),
  ('CHE-1116', 'Spectroscopy', 'Principle', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 200 (§30.1)', 'In NMR, nuclei are flipped between spin states by absorbing', '["UV light", "radio waves", "X-rays", "infrared radiation"]', 1, 'Radio-frequency radiation supplies the small energy needed for spin flipping.', '{"0": "UV excites electrons.", "2": "Far too energetic.", "3": "IR excites bond vibrations."}'),
  ('CHE-1117', 'Spectroscopy', 'Principle', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 200, 209 (§30.1, §30.7)', '¹²C gives no NMR signal because', '["it has no electrons", "it has an odd mass number", "it is radioactive", "its nucleus has even numbers of protons and neutrons, so it has no net magnetic spin"]', 3, '¹²C has 6 protons and 6 neutrons whose magnetic effects cancel; ¹³C, with an odd neutron count, is NMR active.', '{"0": "Carbon atoms have electrons; the issue is nuclear spin.", "1": "Its mass number, 12, is even.", "2": "¹²C is stable."}'),
  ('CHE-1118', 'Spectroscopy', 'Solvents', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 200 (§30.2)', 'In CDCl₃, deuterium does not give a peak in the ¹H NMR spectrum because', '["deuterium has no neutron", "CDCl₃ is a gas", "deuterium needs a different radio frequency for spin flipping", "deuterium is more electronegative than chlorine"]', 2, 'D absorbs at a different frequency from ¹H, so the solvent is ''silent'' in the ¹H spectrum.', '{"0": "Deuterium has one neutron.", "1": "CDCl₃ is a liquid.", "3": "Electronegativity is not the reason."}'),
  ('CHE-1119', 'Spectroscopy', 'Chemical shift', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 200 (§30.3)', 'The reference compound for chemical shift, assigned δ = 0.0 ppm, is', '["benzene", "tetramethylsilane, Si(CH₃)₄", "CDCl₃", "water"]', 1, 'TMS is the standard; all other signals are measured relative to it.', '{"0": "Benzene appears at 6.5–9.0 ppm.", "2": "CDCl₃ is the solvent.", "3": "Water is not the standard."}'),
  ('CHE-1120', 'Spectroscopy', 'Chemical shift', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 201 (Did You Know?)', 'Which is not a reason given for using TMS as the NMR standard?', '["It is inert and volatile, so it is easily removed.", "All 12 of its protons are equivalent and give one sharp peak.", "Its signal is at the far right, away from most organic signals.", "It is strongly acidic and reacts with the sample."]', 3, 'TMS is chemically inert, not acidic or reactive.', '{"0": "This is a reason given.", "1": "This is a reason given.", "2": "This is a reason given (low electronegativity of Si)."}'),
  ('CHE-1121', 'Spectroscopy', 'Chemical shift', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 202 (§30.3)', 'In methanol, the O–H proton appears at 4.80 ppm and the CH₃ protons at 3.35 ppm because', '["the CH₃ protons have lower electron density", "the O–H proton is bonded to carbon", "the O–H proton is next to electronegative oxygen and has lower electron density around it", "TMS shifts the O–H signal"]', 2, 'Protons with less electron density around them (near F, O, N, Cl) appear at higher δ.', '{"0": "The CH₃ protons have higher electron density.", "1": "It is bonded to oxygen.", "3": "TMS is only the reference."}'),
  ('CHE-1122', 'Spectroscopy', 'Chemical shift', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 201 (§30.3)', 'Which compound gives only one peak in its ¹H NMR spectrum?', '["1-chloropropane", "propanone, CH₃COCH₃", "ethanol", "methanol"]', 1, 'All six H atoms of propanone are equivalent (two identical CH₃ groups on C=O).', '{"0": "1-Chloropropane has three environments.", "2": "Ethanol has three environments.", "3": "Methanol has two environments."}'),
  ('CHE-1123', 'Spectroscopy', 'Chemical shift', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 202–203 (Table 30.1)', 'A ¹H NMR signal at δ 9.5 ppm most likely belongs to', '["a vinylic proton", "an alkyl CH₃", "an alkyl group next to C=O", "an aldehyde proton, RCHO"]', 3, 'Table 30.1 gives aldehyde protons at 9.0–10.0 ppm.', '{"0": "Vinylic: 4.5–6.0 ppm.", "1": "Alkyl protons: 0.5–1.5 ppm.", "2": "Alkyl next to C=O: 2.0–2.6 ppm."}'),
  ('CHE-1124', 'Spectroscopy', 'Chemical shift', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 203 (Table 30.1)', 'Protons on a benzene ring (Ar–H) appear at about', '["2.0–2.6 ppm", "0.5–1.5 ppm", "6.5–9.0 ppm", "3.0–4.5 ppm"]', 2, 'Aromatic protons appear at 6.5–9.0 ppm.', '{"0": "Alkyl next to C=O.", "1": "Alkyl protons.", "3": "Alkyl next to an electronegative atom."}'),
  ('CHE-1125', 'Spectroscopy', 'Low resolution', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 203–204 (§30.4.1)', 'The low-resolution ¹H NMR spectrum of ethanol shows', '["three peaks with areas in the ratio 1 : 2 : 3", "two peaks with areas 3 : 3", "one peak", "six peaks of equal area"]', 0, 'OH (1H), CH₂ (2H) and CH₃ (3H) are three environments; peak areas are proportional to the numbers of protons.', '{"1": "Ethanol has three environments.", "2": "There are three environments.", "3": "Equivalent protons share a peak."}'),
  ('CHE-1126', 'Spectroscopy', 'Low resolution', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 204 (§30.4.1)', 'In ethanol''s ¹H NMR spectrum, the peaks at about 1.2, 3.7 and 5.4 ppm are due to', '["CH₂, CH₃ and OH respectively", "CH₃, CH₂ next to O, and OH respectively", "OH, CH₂ and CH₃ respectively", "TMS, CH₃ and CH₂ respectively"]', 1, 'The methyl is furthest from oxygen (lowest δ); CH₂ is next to O; OH is at the highest δ here.', '{"0": "CH₃ is at lowest δ.", "2": "This is reversed.", "3": "TMS is at 0.0 ppm."}'),
  ('CHE-1127', 'Spectroscopy', 'Splitting', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 204 (§30.4.2)', 'In a high-resolution spectrum, a signal is split into a quartet. The number of protons on the adjacent carbon is', '["2", "4", "3", "1"]', 2, 'By the n + 1 rule, 4 sub-peaks means n = 3 neighbouring protons.', '{"0": "Two neighbours give a triplet.", "1": "n + 1 = 4, so n = 3.", "3": "One neighbour gives a doublet."}'),
  ('CHE-1128', 'Spectroscopy', 'Splitting', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 205 (§30.4.2)', 'In the high-resolution ¹H NMR spectrum of ethanol, the CH₃, CH₂ and OH signals are', '["doublet, quartet and triplet", "quartet, triplet and doublet", "singlet, singlet and singlet", "triplet, quartet and singlet"]', 3, 'CH₃ has 2 neighbours (triplet), CH₂ has 3 neighbours on carbon (quartet), and OH is not split.', '{"0": "The CH₃ is not a doublet.", "1": "The CH₃ is next to CH₂, so a triplet.", "2": "These signals are split."}'),
  ('CHE-1129', 'Spectroscopy', 'Splitting', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 205 (§30.4.2)', 'The ¹H NMR signal of ethane, CH₃–CH₃, is a singlet because', '["all its protons are chemically equivalent, and equivalent protons do not split each other", "it has no adjacent carbon", "deuterium replaces the hydrogens", "TMS hides the splitting"]', 0, 'Although each CH₃ has a neighbouring CH₃, the protons are equivalent, so no splitting is seen.', '{"1": "Each carbon has an adjacent carbon.", "2": "No deuterium is involved.", "3": "TMS does not affect splitting."}'),
  ('CHE-1130', 'Spectroscopy', 'Splitting', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 207 (Example 30.1)', 'The predicted ¹H NMR spectrum of chloroethane, CH₃CH₂Cl, is', '["two singlets in ratio 3 : 2", "a triplet (3H, 0.5–1.5 ppm) and a quartet (2H, 3.0–4.5 ppm)", "a quartet (3H, 0.5–1.5 ppm) and a triplet (2H, 3.0–4.5 ppm)", "one singlet"]', 1, 'CH₃ (next to CH₂) gives a triplet at low δ; CH₂ (next to CH₃ and Cl) gives a quartet at higher δ; areas 3 : 2.', '{"0": "Neighbouring protons cause splitting.", "2": "The splitting patterns are reversed.", "3": "There are two environments."}'),
  ('CHE-1131', 'Spectroscopy', 'Splitting', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 208 (Example 30.2)', 'An ester''s ¹H NMR spectrum shows: 1.3 ppm (3H, triplet), 2.2 ppm (3H, singlet), 3.9 ppm (2H, quartet). The ester is', '["propyl methanoate", "methyl propanoate, CH₃CH₂COOCH₃", "methyl ethanoate", "ethyl ethanoate, CH₃COOCH₂CH₃"]', 3, 'The 2.2 ppm singlet is CH₃ next to C=O; the CH₂ at 3.9 ppm is next to O and split by CH₃ (quartet); CH₃ at 1.3 ppm is split by CH₂ (triplet).', '{"0": "That has an HCOO proton near 8 ppm and three environments in the chain.", "1": "Here the CH₂ would be next to C=O (about 2.0–2.6 ppm) and the OCH₃ a singlet.", "2": "Methyl ethanoate has only two singlets."}'),
  ('CHE-1132', 'Spectroscopy', 'D₂O shake', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 206 (§30.4.3)', 'After a few drops of D₂O are shaken with a sample of ethanol, the peak that disappears from the ¹H NMR spectrum is the', '["CH₃ peak", "CH₂ peak", "O–H peak", "TMS peak"]', 2, 'The O–H proton exchanges with deuterium (R–OH + D₂O ⇌ R–OD + HOD) and D gives no ¹H signal.', '{"0": "C–H protons do not exchange.", "1": "C–H protons do not exchange.", "3": "TMS is unaffected."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1133', 'Spectroscopy', 'D₂O shake', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 206 (§30.4.3)', 'O–H and N–H protons are exchanged by D₂O because', '["they are the most shielded protons", "they are bonded to highly electronegative atoms and are easily exchangeable", "they are bonded to carbon", "they have no neighbouring protons"]', 1, 'H on O or N exchanges rapidly, which also explains their variable shifts and lack of splitting.', '{"0": "They are not the most shielded.", "2": "They are bonded to O or N.", "3": "Exchange, not lack of neighbours, is the reason."}'),
  ('CHE-1134', 'Spectroscopy', '¹³C NMR', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 209 (§30.7)', 'The chemical shift range of ¹³C NMR is about', '["200–800 nm", "0–12 ppm", "0–220 ppm", "4000–500 cm⁻¹"]', 2, '¹³C shifts span 0–220 ppm, much wider than ¹H (about 0–12 ppm).', '{"0": "That is the UV-Vis range.", "1": "That is roughly the ¹H range.", "3": "That is the IR range."}'),
  ('CHE-1135', 'Spectroscopy', '¹³C NMR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 209 (§30.7.1)', 'How many peaks does 2-methylpropane, (CH₃)₃CH, give in its ¹³C NMR spectrum?', '["2", "4", "1", "3"]', 0, 'The three CH₃ carbons are equivalent; the central CH carbon is different. Two environments, two peaks.', '{"1": "Equivalent carbons share a peak.", "2": "The central carbon differs from the methyls.", "3": "There are only two environments."}'),
  ('CHE-1136', 'Spectroscopy', '¹³C NMR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 210 (§30.7.2)', 'In the ¹³C NMR spectrum of ethanol, the peak near 57 ppm is due to', '["a C=O carbon", "the CH₃ carbon", "TMS", "the CH₂ carbon bonded to oxygen"]', 3, 'Carbon next to oxygen appears at 50–70 ppm; the CH₃ carbon is at about 18 ppm.', '{"0": "Ethanol has no C=O.", "1": "The CH₃ is at about 18 ppm.", "2": "TMS is at 0 ppm."}'),
  ('CHE-1137', 'Spectroscopy', '¹³C NMR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 210 (Table 30.3)', 'A ¹³C peak at 205 ppm indicates', '["a carbonyl carbon of an aldehyde or ketone", "an alkyl carbon", "a carbon next to a halogen", "a nitrile carbon"]', 0, 'Aldehyde and ketone C=O carbons appear at 190–220 ppm.', '{"1": "Alkyl carbons: 0–50 ppm.", "2": "C–X carbons: 30–60 ppm.", "3": "Nitrile carbons: 100–125 ppm."}'),
  ('CHE-1138', 'Spectroscopy', '¹³C NMR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 210 (§30.7.2)', 'Compared with ¹H NMR, ¹³C NMR spectra', '["have peak areas exactly proportional to numbers of carbons", "show no splitting, and peak areas are not proportional to numbers of carbons", "always show quartets", "use 0–12 ppm only"]', 1, '¹³C peaks appear as single lines whose areas do not reliably count the carbons.', '{"0": "Peak areas are not proportional.", "2": "¹³C peaks are not split.", "3": "The range is 0–220 ppm."}'),
  ('CHE-1139', 'Spectroscopy', '¹³C NMR', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 211 (§30.7.3)', 'A compound C₄H₁₀O shows three peaks in its ¹³C NMR spectrum. Of butan-1-ol, butan-2-ol and 2-methoxypropane, it is', '["butan-2-ol", "butan-1-ol", "2-methoxypropane", "either butanol"]', 2, 'Both butanols have four carbon environments; 2-methoxypropane, CH₃OCH(CH₃)₂, has three.', '{"0": "Butan-2-ol has four environments.", "1": "Butan-1-ol has four environments.", "3": "Each butanol gives four peaks."}'),
  ('CHE-1140', 'Spectroscopy', '¹³C NMR', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 30 Spectroscopy-2 (NMR), p. 213 (Q5)', '2,2-Dimethylpropane, C(CH₃)₄, gives how many ¹³C NMR peaks?', '["2", "5", "1", "3"]', 0, 'The four CH₃ carbons are equivalent and the central quaternary carbon is different.', '{"1": "Equivalent carbons give one peak.", "2": "The central carbon is different from the methyls.", "3": "There are only two environments."}'),
  ('CHE-1141', 'Industrial chemistry', 'Metals', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 215 (§31.1.1)', 'Gold and platinum are found in the free (native) state because they are', '["unreactive and seldom form compounds", "very reactive", "always found as sulfides", "liquids at room temperature"]', 0, 'Less reactive metals exist as the metal in nature; more reactive ones such as Na, Al and Fe occur combined in ores.', '{"1": "Reactive metals are found combined.", "2": "They occur as the free metal.", "3": "Both are solids."}'),
  ('CHE-1142', 'Industrial chemistry', 'Metals', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 215 (§31.1.1)', 'The earthy impurities mixed with a metal compound in an ore are called', '["flux", "gangue", "slag", "alloy"]', 1, 'Ores are mixtures of the useful metal compound with impurities and earthy materials called gangue.', '{"0": "A flux is added to remove gangue.", "2": "Slag forms when gangue reacts with a flux in a furnace.", "3": "An alloy is a mixture of metals."}'),
  ('CHE-1143', 'Industrial chemistry', 'Metallurgy', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 216 (§31.1.1 iii)', 'Roasting differs from calcination in that roasting', '["adds carbon to the ore", "heats a carbonate ore with little or no air", "uses electricity to reduce the oxide", "heats a sulfide ore in excess air, giving the oxide and SO₂"]', 3, '2ZnS + 3O₂ → 2ZnO + 2SO₂ (roasting); ZnCO₃ → ZnO + CO₂ (calcination, limited air).', '{"0": "That is reduction with carbon.", "1": "That is calcination.", "2": "That is electrolytic reduction."}'),
  ('CHE-1144', 'Industrial chemistry', 'Metallurgy', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 216 (§31.1.1 iv)', 'In the extraction of iron from haematite, the species that actually removes oxygen from Fe₂O₃ is', '["carbon dioxide", "oxygen", "carbon monoxide", "zinc"]', 2, 'Carbon burns to CO, and Fe₂O₃ + 3CO → 2Fe + 3CO₂.', '{"0": "CO₂ is a product.", "1": "Oxygen is what is being removed.", "3": "Zinc is not used."}'),
  ('CHE-1145', 'Industrial chemistry', 'Metallurgy', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 216 (§31.1.1 iv)', 'In electrolytic extraction of a reactive metal from its molten compound, the metal is formed', '["in the gangue", "at the cathode, as positive ions gain electrons", "at the anode, as positive ions lose electrons", "as a gas at the anode"]', 1, 'Metal ions move to the negative electrode (cathode) and are reduced to the metal.', '{"0": "Gangue is removed before reduction.", "2": "Positive ions go to the cathode.", "3": "Metals are not released at the anode."}'),
  ('CHE-1146', 'Industrial chemistry', 'Metallurgy', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 216 (§31.1.1 v)', 'Copper for electrical wiring is refined to about', '["50% purity", "90% purity", "99.99% purity", "75% purity"]', 2, 'Even small impurities lower conductivity, so wiring copper must be about 99.99% pure.', '{"0": "Far too impure.", "1": "Too impure for wiring.", "3": "Far too impure."}'),
  ('CHE-1147', 'Industrial chemistry', 'Alloys', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 216 (Table 31.1)', 'Brass is an alloy of', '["aluminium and magnesium", "copper and tin", "iron and carbon", "copper and zinc"]', 3, 'Brass is 60–90% copper with 10–40% zinc.', '{"0": "That is part of duralumin.", "1": "That is bronze.", "2": "That is steel."}'),
  ('CHE-1148', 'Industrial chemistry', 'Alloys', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 217 (Table 31.1)', 'Duralumin is used for aircraft bodies because it is', '["light, strong and corrosion-resistant", "heavy and brittle", "a good electrical insulator", "liquid at room temperature"]', 0, 'Duralumin is mainly aluminium with a little Cu, Mg and Mn, giving a light, strong alloy.', '{"1": "It is light, not heavy.", "2": "It is a metal and conducts.", "3": "It is a solid."}'),
  ('CHE-1149', 'Industrial chemistry', 'Alloys', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 216 (§31.1.1 vi)', 'Metals are alloyed mainly to', '["turn them into ceramics", "change the microstructure and improve properties such as strength and corrosion resistance", "make them pure", "lower their density to below water"]', 1, 'Mixing in other metals or non-metals alters the microstructure, improving strength, corrosion resistance and electrical or magnetic properties.', '{"0": "Alloys remain metallic.", "2": "Alloying adds other elements, so it does not purify.", "3": "Not the purpose."}'),
  ('CHE-1150', 'Industrial chemistry', 'Ceramics', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 217 (§31.1.2)', 'Ceramics are hard but brittle, have high melting points and are good insulators. Chemically they are mostly', '["ionic halides", "pure metals", "long-chain hydrocarbons", "silicates and oxides of metals such as Na, K, Ca and Al"]', 3, 'Strong bonds in silicates and metal oxides give ceramics their hardness and heat resistance.', '{"0": "Not the book''s description.", "1": "Metals are malleable conductors.", "2": "Those are polymers or fuels."}'),
  ('CHE-1151', 'Industrial chemistry', 'Ceramics', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 217 (Table 31.2)', 'Silicon carbide is used in sandpaper because ceramics are', '["good conductors", "flexible", "extremely hard and wear-resistant", "soluble in water"]', 2, 'Hardness and wear resistance make ceramics useful as abrasives and cutting tools.', '{"0": "Most ceramics are insulators.", "1": "Ceramics are brittle.", "3": "Ceramics are chemically inert."}'),
  ('CHE-1152', 'Industrial chemistry', 'Composites', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 217–218 (§31.1.4)', 'In a composite material, the reinforcement agent', '["makes the material heavier", "provides high strength", "only holds the matrix together", "conducts electricity"]', 1, 'The matrix holds the reinforcement (e.g. glass or carbon fibres), which provides strength.', '{"0": "Composites have good strength-to-weight ratio.", "2": "Holding is the job of the matrix.", "3": "Not its role."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1153', 'Industrial chemistry', 'Semiconductors', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 218 (§31.1.5)', 'The most common semiconductor, used in microchips and solar panels, is', '["aluminium", "copper", "gallium nitride", "silicon"]', 3, 'Silicon is effective and abundant.', '{"0": "Aluminium is a conductor.", "1": "Copper is a conductor.", "2": "GaN is used in fast chargers for electric cars."}'),
  ('CHE-1154', 'Industrial chemistry', 'Semiconductors', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 218 (§31.1.5)', 'Gallium arsenide (GaAs) is used in', '["aircraft bodies", "sandpaper", "wireless communication such as 5G devices", "fertilizers"]', 2, 'GaAs is a semiconductor for wireless and 5G devices; GaN is used for fast charging in electric cars.', '{"0": "Duralumin is used there.", "1": "Silicon carbide is used there.", "3": "Not relevant."}'),
  ('CHE-1155', 'Industrial chemistry', 'Toxicity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 219 (§31.2.2)', 'Which group of heavy metals is found in electronics, batteries and fluorescent lights and can leach into groundwater?', '["gold, silver and platinum", "lead, mercury and cadmium", "sodium, potassium and calcium", "aluminium, magnesium and silicon"]', 1, 'Pb, Hg and Cd can enter groundwater and then living organisms.', '{"0": "Not the toxic examples given.", "2": "These are not heavy metals.", "3": "Not the toxic examples given."}'),
  ('CHE-1156', 'Industrial chemistry', 'Toxicity', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 219 (§31.2.2)', 'Phthalates and bisphenol A (BPA) are plastic additives that are harmful because they', '["cause plastics to dissolve in water", "make plastics radioactive", "are heavy metals", "interfere with hormones"]', 3, 'The book names them as toxic additives that disrupt hormones.', '{"0": "Not the hazard described.", "1": "They are not radioactive.", "2": "They are organic compounds."}'),
  ('CHE-1157', 'Industrial chemistry', 'Recycling', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 219 (§31.2.3)', 'Recycling aluminium uses about how much less energy than extracting it from its ore?', '["5% less", "50% less", "95% less", "No less"]', 2, 'The book quotes a 95% energy saving.', '{"0": "Far too small.", "1": "Too small.", "3": "Recycling saves a great deal."}'),
  ('CHE-1158', 'Industrial chemistry', 'Recycling', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 220 (Table 31.3)', 'Chemical recycling (depolymerization) of plastics', '["removes ink with NaOH", "breaks polymer chains back into monomers or simple chemicals", "melts and reshapes the plastic", "crushes and melts cullet"]', 1, 'Using heat, solvents or catalysts, it produces purer starting materials.', '{"0": "That is paper deinking.", "2": "That is mechanical recycling.", "3": "That is glass recycling."}'),
  ('CHE-1159', 'Industrial chemistry', 'Recycling', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 220 (Table 31.3)', 'Scrap glass crushed for recycling is called', '["slag", "pulp", "gangue", "cullet"]', 3, 'Cullet is cleaned, crushed and melted to make new glass.', '{"0": "Slag is a furnace by-product.", "1": "Pulp is from paper.", "2": "Gangue is ore impurity."}'),
  ('CHE-1160', 'Industrial chemistry', 'X-ray crystallography', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 220–221 (§31.3)', 'X-ray crystallography can locate atoms in a crystal because X-rays', '["are absorbed only by hydrogen", "are a type of radio wave", "have very short wavelengths and are diffracted by the regular layers of atoms", "make the crystal emit visible light"]', 2, 'The diffraction pattern is analysed to map atomic positions, bond lengths, bond angles and electron density.', '{"0": "X-rays are scattered by electrons of all atoms.", "1": "X-rays have much shorter wavelengths.", "3": "Not the principle."}'),
  ('CHE-1161', 'Industrial chemistry', 'X-ray crystallography', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 221 (§31.3)', 'The best-known use of X-ray diffraction mentioned in the book is', '["separating amino acids", "finding the double-helix structure of DNA", "measuring blood alcohol", "making ammonia"]', 1, 'XRD helped determine DNA''s double helix and is still used for proteins, enzymes and drug design.', '{"0": "That uses electrophoresis or chromatography.", "2": "That uses IR or GC.", "3": "That is the Haber process."}'),
  ('CHE-1162', 'Industrial chemistry', 'Fossil fuels', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 221 (§31.4)', 'Natural gas methane is mainly used as a chemical feedstock to make', '["TNT", "benzene and toluene", "polystyrene", "ammonia and methanol"]', 3, 'Methane is used to make ammonia (for fertilizers) and methanol.', '{"0": "TNT comes from toluene.", "1": "BTX comes from coal and reforming.", "2": "Polystyrene comes from benzene."}'),
  ('CHE-1163', 'Industrial chemistry', 'Fractional distillation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 222 (§31.5)', 'In fractional distillation of crude oil, hydrocarbons with the highest boiling points', '["rise to the top", "are cracked in the column", "condense near the bottom of the column", "remain as gases"]', 2, 'The column is cooler higher up; heavy, high-boiling fractions condense low down and light ones rise further.', '{"0": "Light, low-boiling fractions rise to the top.", "1": "Distillation is a physical separation.", "3": "They condense to liquids."}'),
  ('CHE-1164', 'Industrial chemistry', 'Petrochemicals', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 223 (Table 31.5)', 'Which petrochemical is the starting material for TNT?', '["butadiene", "toluene", "ethene", "xylene"]', 1, 'Toluene (methylbenzene) is nitrated to trinitrotoluene.', '{"0": "Butadiene gives synthetic rubber.", "2": "Ethene gives poly(ethene).", "3": "Xylene gives polyester fibres."}'),
  ('CHE-1165', 'Industrial chemistry', 'Cracking', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 223–224 (§31.6.1)', 'Compared with thermal cracking, catalytic cracking', '["turns alkanes into aromatic rings", "uses no catalyst and 450–750 °C", "joins small molecules into larger ones", "uses zeolite catalysts and lower temperatures (about 500 °C)"]', 3, 'The catalyst lowers the activation energy, saving energy and giving better control over products.', '{"0": "That is reforming.", "1": "That is thermal cracking.", "2": "Cracking breaks molecules."}'),
  ('CHE-1166', 'Industrial chemistry', 'Cracking', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 224 (§31.6.1)', 'Thermal cracking of decane, C₁₀H₂₂, gives octane and', '["ethane, C₂H₆", "methane, CH₄", "ethene, C₂H₄", "hydrogen only"]', 2, 'C₁₀H₂₂ → C₈H₁₈ + C₂H₄. Carbon: 10 = 8 + 2; hydrogen: 22 = 18 + 4.', '{"0": "C₈H₁₈ + C₂H₆ would need 24 H.", "1": "The carbon count would not balance.", "3": "The carbon count would not balance."}'),
  ('CHE-1167', 'Industrial chemistry', 'Reforming', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 224 (§31.6.1 b)', 'The main purpose of reforming is to', '["remove sulfur from fuel", "convert straight-chain alkanes into branched or aromatic hydrocarbons of higher octane number", "break large molecules into small alkenes", "make polymers"]', 1, 'Branched and aromatic fuels reduce engine knocking; reforming also supplies benzene, toluene and xylene.', '{"0": "Not the purpose described.", "2": "That is cracking.", "3": "Polymerization is a separate process."}'),
  ('CHE-1168', 'Industrial chemistry', 'Reforming', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 224 (§31.6.1 b)', 'When hexane is reformed into benzene over a Pt catalyst, the number of H₂ molecules released per hexane is', '["1", "3", "4", "7"]', 2, 'C₆H₁₄ → C₆H₆ + 4H₂: 14 H = 6 + 8.', '{"0": "That is for hexane → cyclohexane.", "1": "This would leave H unbalanced.", "3": "Too many."}'),
  ('CHE-1169', 'Industrial chemistry', 'Energy', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 225 (§31.7)', 'Energy density and specific energy are measured respectively in', '["MJ/L and MJ/kg", "MJ/kg and MJ/L", "kJ/mol and J/K", "W and J"]', 0, 'Energy density is energy per unit volume; specific energy is energy per unit mass.', '{"1": "This is reversed.", "2": "Those are other quantities.", "3": "Those are power and energy."}'),
  ('CHE-1170', 'Industrial chemistry', 'Energy', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 225 (§31.7)', 'Hydrogen is attractive for aerospace because it has', '["a very high specific energy (about 120 MJ/kg), though a low energy density", "a very high energy density per litre", "no energy content", "a higher density than diesel"]', 0, 'Hydrogen stores a lot of energy per kilogram but little per litre.', '{"1": "Its energy density is low.", "2": "It is an excellent fuel per kg.", "3": "Hydrogen is very light."}'),
  ('CHE-1171', 'Industrial chemistry', 'Energy', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 225 (Interesting Information)', 'CNG cars need larger fuel tanks than petrol cars for the same distance because CNG has', '["a lower energy density", "a higher specific energy", "no carbon", "a higher boiling point"]', 0, 'Less energy per unit volume means more storage volume is needed, so CNG suits local commuting.', '{"1": "This would not explain the larger tanks.", "2": "Methane contains carbon.", "3": "Not the reason."}'),
  ('CHE-1172', 'Industrial chemistry', 'Nuclear energy', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 226 (§31.8)', 'In the fission U-235 + ¹n → Ba-141 + Kr-92 + 3¹n + energy, the extra neutrons', '["can cause further fission in a chain reaction", "are absorbed by barium only", "turn into protons immediately", "stop the reaction"]', 0, 'Each fission releases more neutrons than it uses, so a chain reaction can follow.', '{"1": "Not stated, and not what drives the process.", "2": "Not stated.", "3": "They sustain the reaction."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1173', 'Industrial chemistry', 'Nuclear energy', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 225 (§31.8)', 'Nuclear fusion is the process in which', '["light nuclei combine", "heavy nuclei split", "molecules break bonds", "electrons are removed from atoms"]', 0, 'Fission splits heavy nuclei; fusion combines light nuclei. Both release far more energy than chemical reactions.', '{"1": "That is fission.", "2": "That is a chemical change.", "3": "That is ionization."}'),
  ('CHE-1174', 'Industrial chemistry', 'Solar energy', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 31 Materials and Energy, p. 226 (§31.8)', 'In a solar PV system, the inverter', '["converts DC from the panels into AC", "stores electricity for the night", "converts AC into DC", "concentrates sunlight"]', 0, 'Panels make direct current; the inverter turns it into alternating current for homes and industry. Batteries store energy.', '{"1": "Batteries store energy.", "2": "It converts DC to AC.", "3": "Not its job."}'),
  ('CHE-1175', 'Industrial chemistry', 'Therapeutic window', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 230 (§32.1.1)', 'The therapeutic window of a drug is the range of plasma concentrations', '["between the minimum effective concentration and the minimum toxic concentration", "below the minimum effective concentration", "above the minimum toxic concentration", "at which half of patients die"]', 0, 'It is the ''sweet spot'': high enough to work (above MEC), low enough to be safe (below MTC).', '{"1": "Below MEC the drug has no clinical effect.", "2": "Above MTC the drug is harmful.", "3": "That is not the definition."}'),
  ('CHE-1176', 'Industrial chemistry', 'Therapeutic window', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 230 (§32.1.1)', 'A drug with a narrow therapeutic window', '["has no toxic dose", "is always safe at double the dose", "needs careful dosing and often blood-level monitoring", "cannot be given to anyone"]', 2, 'The effective dose is close to the toxic dose, so levels must be watched to stay in range.', '{"0": "Every drug can be toxic at some dose.", "1": "That describes a wide window.", "3": "Such drugs are used, with care."}'),
  ('CHE-1177', 'Industrial chemistry', 'Therapeutic index', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 230–231 (§32.1.2)', 'Drug X has ED₅₀ = 20 mg and TD₅₀ = 80 mg. Its therapeutic index is', '["0.25", "4", "60", "100"]', 1, 'TI = TD₅₀ ÷ ED₅₀ = 80 ÷ 20 = 4.', '{"0": "This is ED₅₀ ÷ TD₅₀, the inverse.", "2": "This is the difference, not the ratio.", "3": "This is the sum."}'),
  ('CHE-1178', 'Industrial chemistry', 'Therapeutic index', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 231 (§32.1.2)', 'Which drugs does the book give as examples of a low therapeutic index, needing blood monitoring?', '["codeine and caffeine", "penicillin and paracetamol", "aspirin and vitamin C", "warfarin and digoxin"]', 3, 'Warfarin (blood thinner) and digoxin (heart medicine) have low TI; penicillin and paracetamol have high TI.', '{"0": "Not the examples given.", "1": "These have high TI.", "2": "Not the examples given."}'),
  ('CHE-1179', 'Industrial chemistry', 'Stomach pH', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 231 (§32.2)', 'Some medicines are given with a protective coating that dissolves only in the small intestine because', '["the low pH of the stomach can break down the drug before absorption", "the stomach is alkaline", "the small intestine is more acidic than the stomach", "coating makes the drug toxic"]', 0, 'Stomach acid (pH about 1.5–3.5) can cause non-specific reactions that destroy some drugs.', '{"1": "The stomach is strongly acidic.", "2": "The small intestine is less acidic.", "3": "Coating protects the drug."}'),
  ('CHE-1180', 'Industrial chemistry', 'Stomach pH', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 231 (§32.2)', 'The stomach lining is protected from its own acid by', '["chlorophyll", "a layer of fat", "a thick layer of mucus and bicarbonate ions", "a layer of cellulose"]', 2, 'Mucus and bicarbonate neutralize acid at the cell surface. Parietal cells pump H⁺ into the stomach.', '{"0": "Not present.", "1": "Not the protection described.", "3": "Not present."}'),
  ('CHE-1181', 'Industrial chemistry', 'Penicillin', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 231 (§32.3.1)', 'The penicillin structure contains a four-membered β-lactam ring fused to a', '["seven-membered ring", "six-membered benzene ring", "three-membered epoxide ring", "five-membered thiazolidine ring"]', 3, 'The two core rings are the β-lactam and the thiazolidine ring.', '{"0": "Not present.", "1": "Not the fused ring.", "2": "Not present."}'),
  ('CHE-1182', 'Industrial chemistry', 'Penicillin', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 231–232 (§32.3.1)', 'Bacteria become resistant to penicillin when they produce β-lactamases, enzymes that', '["repair the cell wall", "attack and open the β-lactam ring, deactivating penicillin", "build a thicker DNA", "neutralize stomach acid"]', 1, 'The β-lactam ring is essential for activity and is the site attacked by β-lactamases.', '{"0": "Not the action of β-lactamase.", "2": "Not related.", "3": "Not related."}'),
  ('CHE-1183', 'Industrial chemistry', 'Penicillin', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 232 (§32.3.1)', 'Penicillin does not harm human cells because', '["penicillin cannot enter the blood", "human cells have extra β-lactam rings", "human cells have no cell wall", "human cells make penicillin"]', 2, 'Penicillin blocks the enzyme that builds the bacterial cell wall; human cells do not have one.', '{"0": "It is carried in the blood.", "1": "Not true.", "3": "It comes from Penicillium mould."}'),
  ('CHE-1184', 'Industrial chemistry', 'Penicillin', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 232 (Did You Know?)', 'Penicillin was discovered in 1928 by', '["Fritz Haber", "Emil Fischer", "R. B. Woodward", "Alexander Fleming"]', 3, 'Fleming noticed that mould (Penicillium) on a contaminated dish had killed the surrounding bacteria.', '{"0": "Haber is known for ammonia synthesis.", "1": "Fischer proposed the lock-and-key model.", "2": "Woodward is known for total syntheses."}'),
  ('CHE-1185', 'Industrial chemistry', 'Opiates', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 232 (§32.3.2)', 'The main target of morphine, responsible for its pain relief and also for respiratory depression and euphoria, is the', '["kappa (κ) receptor", "mu (μ) opioid receptor", "delta (δ) receptor", "COX enzyme"]', 1, 'μ receptors in the brain and spinal cord are the primary target of most opioids.', '{"0": "κ receptors are linked to spinal analgesia and sedation, with less euphoria.", "2": "δ receptors relate to mood and emotion.", "3": "COX is the target of aspirin."}'),
  ('CHE-1186', 'Industrial chemistry', 'Opiates', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 232 (§32.3.2)', 'When an opiate binds its receptor, the neuron becomes less able to send pain signals because', '["the neuron is destroyed", "sodium channels open widely", "calcium channels close and potassium channels open, hyperpolarizing the neuron", "dopamine release stops"]', 2, 'Hyperpolarization makes firing harder. Opiates also increase dopamine release in the reward centre.', '{"0": "Neurons are not destroyed.", "1": "Not the mechanism described.", "3": "Opiates increase dopamine release."}'),
  ('CHE-1187', 'Industrial chemistry', 'Opiates', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 232 (§32.3.2)', 'The body''s own painkillers, which bind to opioid receptors, are', '["β-lactamases", "interferons", "enzymes such as COX", "endorphins"]', 3, 'Endorphins are natural painkillers; opiates ''hijack'' this system.', '{"0": "β-lactamases destroy penicillin.", "1": "Interferons boost immunity to viruses.", "2": "COX is targeted by aspirin."}'),
  ('CHE-1188', 'Industrial chemistry', 'Antivirals', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 233 (§32.4)', 'Antiviral drugs are hard to design mainly because viruses', '["have thick cell walls", "replicate inside our cells using our cell machinery, and mutate quickly", "are always killed by antibiotics", "are larger than bacteria"]', 1, 'A drug that stops the virus may also harm host cells; rapid mutation also makes drugs and vaccines go out of date.', '{"0": "Viruses have no cell walls.", "2": "Antibiotics do not kill viruses.", "3": "Viruses are much smaller."}'),
  ('CHE-1189', 'Industrial chemistry', 'Antivirals', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 233 (§32.4)', 'Protease inhibitors used against HIV and hepatitis C work by', '["boosting the immune system as interferons do", "breaking the bacterial cell wall", "inhibiting a viral enzyme so viral proteins cannot be processed", "neutralizing stomach acid"]', 2, 'Enzyme inhibition is a common antiviral mechanism; protease inhibitors stop the virus making its proteins from one long strand.', '{"0": "Interferons are a different class.", "1": "That is penicillin''s action.", "3": "Not relevant."}'),
  ('CHE-1190', 'Industrial chemistry', 'Fertilizers', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 234 (§32.5)', 'The three primary macronutrients shown on a fertilizer label are', '["iron, zinc and copper", "carbon, hydrogen and oxygen", "calcium, magnesium and sulfur", "nitrogen, phosphorus and potassium"]', 3, 'Commercial fertilizers carry an N–P–K ratio.', '{"0": "These are micronutrients.", "1": "These come from air and water.", "2": "These are secondary macronutrients."}'),
  ('CHE-1191', 'Industrial chemistry', 'Fertilizers', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 234 (§32.5)', 'Phosphorus is important for plants mainly because it is', '["an osmoregulator only", "a structural part of ATP, which stores and releases energy", "part of chlorophyll''s metal centre", "a micronutrient"]', 1, 'Phosphorus is supplied as superphosphates or ammonium phosphates and is a component of ATP.', '{"0": "That describes potassium.", "2": "Chlorophyll contains magnesium.", "3": "It is a primary macronutrient."}'),
  ('CHE-1192', 'Industrial chemistry', 'Fertilizers', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 234 (§32.5)', 'Unlike nitrogen and phosphorus, potassium', '["is part of ATP", "is part of every amino acid", "does not become part of plant structure but acts as an osmoregulator and enzyme activator", "is a micronutrient"]', 2, 'Potassium regulates water balance and activates over sixty enzymes.', '{"0": "That is phosphorus.", "1": "That is nitrogen.", "3": "It is a primary macronutrient."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1193', 'Industrial chemistry', 'Fertilizers', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 234 (§32.5)', 'Excess fertilizer washed into lakes is harmful because it', '["turns water into acid rain", "kills all algae", "makes water radioactive", "causes overgrowth of algae, harming aquatic life"]', 3, 'Nutrient runoff causes algal overgrowth. Long-term overuse can also change soil pH and kill soil microbes.', '{"0": "Not the effect.", "1": "Nutrients feed algae.", "2": "Not true."}'),
  ('CHE-1194', 'Industrial chemistry', 'Pesticides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 234 (§32.6)', 'Organophosphates and neonicotinoids kill insects by', '["blocking photosynthesis", "acting as neurotoxins on the nervous system", "destroying fungal cell membranes", "dissolving the exoskeleton"]', 1, 'These insecticides damage the insect nervous system, causing paralysis and death.', '{"0": "Some herbicides do that.", "2": "Fungicides do that.", "3": "Not the mechanism."}'),
  ('CHE-1195', 'Industrial chemistry', 'Pesticides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 235 (§32.6)', 'Many fungicides kill fungi by', '["inhibiting photosynthesis", "acting as neurotoxins", "blocking ergosterol synthesis so the cell membrane leaks", "adding nitrogen"]', 2, 'Without stable ergosterol-containing membranes the fungal cells leak and die.', '{"0": "That is how some herbicides act.", "1": "That is how insecticides act.", "3": "Not a pesticide action."}'),
  ('CHE-1196', 'Industrial chemistry', 'Pesticides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 235 (§32.6)', 'Neonicotinoids have been linked to', '["golden rice", "acid rain", "ozone depletion", "colony collapse disorder in honeybees"]', 3, 'Harm to pollinators threatens crop pollination worldwide.', '{"0": "A GM crop.", "1": "Caused by SOₓ and NOₓ.", "2": "Caused by CFCs."}'),
  ('CHE-1197', 'Industrial chemistry', 'Acid rain', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 235 (§32.7)', 'Rain is considered acid rain when its pH is below', '["7.0", "5.6", "3.0", "8.5"]', 1, 'Normal rain is about pH 5.6 because of dissolved CO₂ (carbonic acid).', '{"0": "Normal rain is already below 7.", "2": "Acid rain can be pH 3 but the threshold is 5.6.", "3": "That is alkaline."}'),
  ('CHE-1198', 'Industrial chemistry', 'Acid rain', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 235 (§32.7)', 'When acid rain falls on soil, H⁺ ions', '["replace K⁺, Ca²⁺ and Mg²⁺ held by soil, which are leached away, and release toxic Al³⁺", "add K⁺ and Ca²⁺ to the soil", "raise the soil pH", "combine with nitrogen to make ammonia"]', 0, 'K⁺–soil + H⁺ → H⁺–soil + K⁺, and similarly for Ca²⁺; Al³⁺ is also released and damages roots.', '{"1": "Nutrients are lost, not added.", "2": "Acid lowers pH.", "3": "Not the reaction."}'),
  ('CHE-1199', 'Industrial chemistry', 'Acid rain', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 236 (Did You Know?)', 'Fish die in acidified lakes because', '["algae make the water too alkaline", "the water freezes", "Al³⁺ released from soil clogs their gills, reducing oxygen uptake", "CO₂ is removed from the water"]', 2, 'Acid rain releases Al³⁺, which damages gills so fish suffocate.', '{"0": "The water becomes acidic.", "1": "Not related.", "3": "Not the cause."}'),
  ('CHE-1200', 'Industrial chemistry', 'Climate and crops', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 237 (§32.8)', '"Sub1 rice" was developed to', '["grow without nitrogen", "produce beta-carotene", "make its own insecticide", "survive being submerged under water for about two weeks"]', 3, 'Sub1 rice is a flood-tolerant variety.', '{"0": "Not the trait.", "1": "That is golden rice.", "2": "That is Bt cotton."}'),
  ('CHE-1201', 'Industrial chemistry', 'Genetic engineering', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 237 (§32.9)', 'Golden rice is engineered to contain', '["a bacterial insecticide", "beta-carotene, to help prevent blindness", "herbicide resistance only", "extra starch"]', 1, 'Golden rice provides beta-carotene (a vitamin A precursor); Bt cotton makes its own pesticide.', '{"0": "That is Bt cotton.", "2": "Not its purpose.", "3": "Not its purpose."}'),
  ('CHE-1202', 'Industrial chemistry', 'Genetic engineering', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 237 (§32.9)', 'A concern about GM crops mentioned in the book is', '["they always lower yields", "they cannot be eaten", "herbicide-resistant genes spreading to weeds, creating superweeds", "they need more pesticide sprays"]', 2, 'Outcrossing to wild plants, superweeds, resistant insects and unknown long-term effects are the concerns.', '{"0": "GM crops can raise yields.", "1": "Not stated.", "3": "Bt crops reduce spraying."}'),
  ('CHE-1203', 'Industrial chemistry', 'Pakistan raw materials', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 238 (§32.10)', 'In Pakistan, natural gas is the main raw material for producing', '["stainless steel", "cement", "soda ash", "urea fertilizer"]', 3, 'Methane supplies hydrogen for ammonia, which is converted into urea, keeping fertilizer costs low.', '{"0": "Stainless steel uses chromite.", "1": "Cement uses limestone and clay.", "2": "Soda ash uses brine and limestone."}'),
  ('CHE-1204', 'Industrial chemistry', 'Pakistan raw materials', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 238 (§32.10)', 'Chromite, used in stainless steel and pigments, is found in Pakistan at', '["Khewra", "Muslim Bagh", "Thar", "Kalabagh"]', 1, 'The book names Muslim Bagh for chromite; Khewra is famous for rock salt.', '{"0": "Khewra is a rock-salt mine.", "2": "Not named for chromite.", "3": "Not named for chromite."}'),
  ('CHE-1205', 'Industrial chemistry', 'Industrial processes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 239 (§32.12)', 'In the Contact process, sulfur dioxide is oxidized to sulfur trioxide using', '["iron crystals", "V₂O₅ or Pt as catalyst", "zeolites", "nickel"]', 1, 'SO₂ → SO₃ over V₂O₅ (or Pt); SO₃ is converted to oleum and then sulfuric acid.', '{"0": "Iron is the Haber process catalyst.", "2": "Zeolites are used in cracking.", "3": "Nickel is used in hydrogenation."}'),
  ('CHE-1206', 'Industrial chemistry', 'Industrial processes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 239 (§32.12)', 'The Solvay process makes sodium carbonate from brine and limestone. Its by-product is', '["calcium chloride", "chlorine gas", "sulfur trioxide", "urea"]', 0, 'Ammonia is recovered with lime, leaving CaCl₂ as the by-product.', '{"1": "Chlorine is made in the chlor-alkali process.", "2": "SO₃ is in the Contact process.", "3": "Urea is a fertilizer."}'),
  ('CHE-1207', 'Industrial chemistry', 'Industrial processes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 239–240 (§32.12)', 'The chlor-alkali process electrolyses brine to give', '["chlorine, sodium hydroxide and hydrogen", "sodium carbonate and calcium chloride", "ammonia and urea", "sulfuric acid"]', 0, 'Electrolysis of NaCl brine gives Cl₂, NaOH and H₂, often in membrane cells.', '{"1": "Those are Solvay products.", "2": "Those come from the Haber process and urea plants.", "3": "That comes from the Contact process."}'),
  ('CHE-1208', 'Industrial chemistry', 'Applications', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 240 (§32.13)', 'In cement manufacture, limestone and clay are heated in a rotary kiln to about', '["1500 °C, and the product is ground with gypsum", "150 °C, and the product is ground with salt", "500 °C over a zeolite", "37 °C with enzymes"]', 0, 'The kiln product (clinker) is ground with gypsum to make cement.', '{"1": "Far too low.", "2": "That is catalytic cracking.", "3": "Body temperature, not a kiln."}'),
  ('CHE-1209', 'Industrial chemistry', 'Applications', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 240 (§32.13)', 'In the food industry, hydrogenation is used to', '["turn edible oils into solid fats such as margarine", "preserve food with sodium benzoate", "add iodine to salt", "make bread rise"]', 0, 'Adding H₂ across C=C bonds of oils raises their melting point.', '{"1": "Sodium benzoate is a preservative.", "2": "That is fortification.", "3": "Baking soda is the leavening agent."}'),
  ('CHE-1210', 'Industrial chemistry', 'Applications', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 240 (Did You Know?)', 'Freshly mixed cement becomes warm because', '["its hydration reaction with water is exothermic", "it absorbs heat from the air", "it is radioactive", "it undergoes fission"]', 0, 'Cement reacts with water and releases heat.', '{"1": "It releases heat.", "2": "Not true.", "3": "Not a nuclear process."}'),
  ('CHE-1211', 'Industrial chemistry', 'Safety', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 32 Medicine, Agriculture and Industry, p. 240 (§32.14)', 'Flammable, toxic and corrosive chemicals in a factory should be', '["labelled and stored separately in suitable containers", "stored together to save space", "kept in unlabelled bottles", "poured down drains"]', 0, 'Separate storage prevents leaks, contamination and dangerous reactions.', '{"1": "Mixing storage risks reactions.", "2": "Labelling is essential.", "3": "Unsafe disposal."}'),
  ('CHE-1212', 'Environmental chemistry', 'Properties', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 244–245 (§33.1)', 'Water is a good solvent for ionic substances such as nitrates and phosphates because', '["its polar molecules surround and stabilize the ions", "it is non-polar", "it has a low boiling point", "it is a strong acid"]', 0, 'Water is a permanent dipole; its δ+ and δ− ends surround ions. This is also how nutrients and some pesticides enter the water cycle.', '{"1": "Water is polar.", "2": "Water''s boiling point is unusually high.", "3": "Water is amphoteric, not a strong acid."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1213', 'Environmental chemistry', 'Properties', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 245 (§33.1 iii)', 'Water is described as amphoteric because it', '["is both a solid and a liquid", "can act both as an acid and as a base", "dissolves both acids and bases", "contains both H and O"]', 1, 'Water self-ionizes (Kw = 1.0 × 10⁻¹⁴ at 25 °C), donating or accepting protons; this sets the baseline of the pH scale.', '{"0": "Not the meaning.", "2": "Dissolving is not what amphoteric means.", "3": "Not the meaning."}'),
  ('CHE-1214', 'Environmental chemistry', 'Properties', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 245 (§33.1 iii)', 'Acid rain makes lakes more toxic partly because the extra H₃O⁺', '["adds dissolved oxygen", "removes all metal ions from the water", "increases the solubility of heavy-metal compounds such as aluminium hydroxide and lead salts in sediments", "raises the pH"]', 2, 'Protonation and displacement mobilize toxic metals from sediments into the water.', '{"0": "Acid does not add oxygen.", "1": "It releases metals rather than removing them.", "3": "Acid lowers pH."}'),
  ('CHE-1215', 'Environmental chemistry', 'Oxygen demand', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 245 (§33.1 iv)', 'Biochemical oxygen demand (BOD) is usually measured over', '["one hour at 100 °C", "thirty days at 0 °C", "one day at 37 °C", "five days at 20 °C"]', 3, 'BOD is the oxygen used by microorganisms to break down organic matter in the standard 5-day test at 20 °C.', '{"0": "Not the standard conditions.", "1": "Not the standard conditions.", "2": "Not the standard conditions."}'),
  ('CHE-1216', 'Environmental chemistry', 'Oxygen demand', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 245 (§33.1 iv)', 'Chemical oxygen demand (COD) differs from BOD in that COD', '["measures dissolved oxygen directly", "measures oxygen needed to oxidize organic and inorganic matter chemically, using agents such as K₂Cr₂O₇", "measures only the oxygen used by bacteria", "is always lower than BOD"]', 1, 'COD uses strong oxidizing agents and so reflects the total oxidizable pollution load.', '{"0": "That is DO.", "2": "That is BOD.", "3": "COD is usually higher, since more substances are oxidized."}'),
  ('CHE-1217', 'Environmental chemistry', 'Oxygen demand', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 245–246 (Table 33.1)', 'According to Table 33.1, drinking water should have', '["DO 0–2 mg/L and BOD over 500 mg/L", "DO below 1 mg/L and BOD above 100 mg/L", "DO above 6 mg/L and BOD below 2 mg/L", "DO 2–4 mg/L and BOD 10–30 mg/L"]', 2, 'High DO and low BOD mean little organic pollution.', '{"0": "That describes industrial waste.", "1": "That describes raw sewage.", "3": "That describes treated sewage."}'),
  ('CHE-1218', 'Environmental chemistry', 'Oxygen demand', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 245 (§33.1 iv)', 'A high level of dissolved oxygen (DO) in a river generally indicates', '["heavy organic pollution", "a dead zone", "raw sewage", "clean, unpolluted water"]', 3, 'Low DO suggests pollution or decomposing organic matter; high DO indicates healthy water.', '{"0": "Organic pollution lowers DO.", "1": "Dead zones have very low DO.", "2": "Raw sewage has DO below 1 mg/L."}'),
  ('CHE-1219', 'Environmental chemistry', 'Redox', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 246 (§33.1 v)', 'In stagnant, oxygen-depleted water, the reducing conditions lead to the formation of', '["O₃ and H₂O₂", "H₂S and NH₃", "SO₄²⁻ and CO₂", "NO₃⁻ and O₂"]', 1, 'Without oxygen, species are reduced: sulfur to H₂S and nitrogen to NH₃.', '{"0": "These are oxidizing disinfectants.", "2": "These are the oxidized forms found in well-oxygenated water.", "3": "These are oxidized forms."}'),
  ('CHE-1220', 'Environmental chemistry', 'Pollution sources', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 246 (§33.2)', 'Which is an example of point-source pollution?', '["acid rain over a whole region", "rain washing fertilizer off many farms", "a factory pipe discharging mercury salts into a river", "stormwater carrying oil and tyre zinc off roads"]', 2, 'A point source enters from a single, identifiable location and is most concentrated near the outlet.', '{"0": "That is diffuse, not from one point.", "1": "That is non-point (diffuse) pollution.", "3": "That is non-point pollution."}'),
  ('CHE-1221', 'Environmental chemistry', 'Pollution sources', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 247 (§33.2)', 'Non-point source pollution typically produces', '["a single pollutant at very high concentration at one spot", "only radioactive waste", "no pollution after rain", "a mixture of pollutants at lower concentrations over a wide area"]', 3, 'Runoff collects pollutants from large areas and delivers them diffusely, mainly after storms.', '{"0": "That describes a point-source plume.", "1": "Not specific to radioactivity.", "2": "Rain drives NPS pollution."}'),
  ('CHE-1222', 'Environmental chemistry', 'Microbes', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 247 (§33.3)', 'Which is a water-borne disease caused by microbiological pollution?', '["itai-itai disease", "cholera", "Minamata disease", "blue baby syndrome"]', 1, 'Cholera, typhoid, dysentery and hepatitis A spread through water contaminated with pathogens.', '{"0": "Caused by cadmium.", "2": "Caused by methylmercury.", "3": "Caused by nitrates."}'),
  ('CHE-1223', 'Environmental chemistry', 'Microbes', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 247 (margin)', 'Boiling water at 100 °C', '["removes all dissolved salts", "removes heavy metals", "kills most bacteria, viruses and protozoa but does not remove other pollutants", "removes pesticides"]', 2, 'Boiling makes water microbiologically safe but leaves chemical pollutants behind.', '{"0": "Salts are concentrated, not removed.", "1": "Metals stay in the water.", "3": "Pesticides are not removed."}'),
  ('CHE-1224', 'Environmental chemistry', 'Heavy metals', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 248 (§33.3)', 'In aquatic sediments, bacteria convert inorganic mercury into', '["harmless mercury oxide", "calcium mercurate", "mercury vapour only", "methylmercury, [CH₃Hg]⁺, which is more dangerous"]', 3, 'Methylmercury is fat-soluble, crosses membranes, biomagnifies and is a potent neurotoxin.', '{"0": "The product is more toxic, not harmless.", "1": "Not a real compound here.", "2": "Not the conversion described."}'),
  ('CHE-1225', 'Environmental chemistry', 'Heavy metals', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 248 (Did You Know?)', 'The Minamata disaster in Japan in the 1950s was caused by', '["nitrates in wells", "methylmercury released into the water", "cadmium in rice fields", "an oil spill"]', 1, 'Methylmercury poisoning caused neurological damage, birth defects and deaths.', '{"0": "Nitrates cause blue baby syndrome.", "2": "Cadmium caused itai-itai disease.", "3": "Not the cause."}'),
  ('CHE-1226', 'Environmental chemistry', 'Heavy metals', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 248 (§33.3)', 'Lead in drinking water causes anaemia because it', '["kills bacteria", "replaces calcium in bones", "interferes with the production of haemoglobin", "reduces nitrates"]', 2, 'Lead blocks haemoglobin production; in children it also causes irreversible neurological damage.', '{"0": "Not relevant.", "1": "That is cadmium.", "3": "Not the effect."}'),
  ('CHE-1227', 'Environmental chemistry', 'Heavy metals', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 248 (margin)', 'Cd²⁺ can replace Ca²⁺ in bones because Cd²⁺', '["has a larger charge", "is lighter than Ca²⁺", "is an anion", "has a higher charge density"]', 3, 'Both ions are 2+, but Cd²⁺ has the higher charge density, so it displaces Ca²⁺, making bones brittle.', '{"0": "Both have a 2+ charge.", "1": "Cd is much heavier than Ca.", "2": "It is a cation."}'),
  ('CHE-1228', 'Environmental chemistry', 'Heavy metals', 'hard', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 248 (Table 33.2)', 'Which heavy metal has the lowest WHO limit in drinking water in Table 33.2?', '["chromium (0.05 mg/L)", "cadmium (0.003 mg/L)", "copper (2.0 mg/L)", "lead (0.01 mg/L)"]', 1, 'Cadmium''s limit is 0.003 mg/L; mercury 0.006, lead and arsenic 0.01, chromium 0.05, copper 2.0.', '{"0": "Higher than Cd.", "2": "Copper has the highest limit.", "3": "Higher than Cd."}'),
  ('CHE-1229', 'Environmental chemistry', 'Pesticides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 249 (§33.3)', 'DDT accumulates in fish and birds because it is', '["rapidly biodegradable", "very soluble in water and quickly excreted", "non-polar and highly soluble in fatty tissue, and persistent", "a heavy metal"]', 2, 'DDT is a persistent organic pollutant that dissolves in fat and builds up in food chains.', '{"0": "It is persistent.", "1": "It is not water-soluble.", "3": "It is an organochlorine compound."}'),
  ('CHE-1230', 'Environmental chemistry', 'Pesticides', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 249 (§33.3)', 'PCBs (polychlorinated biphenyls) entered water mainly from', '["fertilizer runoff", "natural gas", "boiling water", "their use as coolants in electrical transformers"]', 3, 'PCBs leak from hazardous waste sites; they are probable carcinogens and cause chloracne.', '{"0": "Not their source.", "1": "Not a source.", "2": "Not a source."}'),
  ('CHE-1231', 'Environmental chemistry', 'Eutrophication', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 250 (§33.3)', 'Eutrophication leads to ''dead zones'' because', '["algae produce mercury", "algae that bloom on excess N and P die and their decomposition uses up dissolved oxygen", "nitrogen is toxic to fish directly", "sunlight increases"]', 1, 'Algal blooms block light; decay of the algae consumes oxygen, making water hypoxic.', '{"0": "Algae do not make mercury.", "2": "Oxygen depletion, not direct N toxicity, causes dead zones.", "3": "Blooms block sunlight."}'),
  ('CHE-1232', 'Environmental chemistry', 'Eutrophication', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 250 (§33.3)', 'High nitrate in drinking water is dangerous for infants because it causes', '["chloracne", "itai-itai disease", "blue baby syndrome (methaemoglobinaemia)", "Minamata disease"]', 2, 'Nitrates reduce the blood''s capacity to carry oxygen.', '{"0": "Caused by PCBs.", "1": "Caused by cadmium.", "3": "Caused by methylmercury."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

INSERT OR IGNORE INTO questions
  (id, subject, chapter, topic, difficulty, source, stem, options, answer, why, wrong, stage, free, checks, writer_id, created_at, updated_at)
SELECT s.column1, 'Chemistry', s.column2, s.column3, s.column4, s.column5, s.column6, s.column7, s.column8, s.column9, s.column10,
  'live', 0, '[]', u.id, unixepoch() * 1000, unixepoch() * 1000
FROM (VALUES
  ('CHE-1233', 'Environmental chemistry', 'Oil and plastic', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 250 (§33.3)', 'An oil spill harms marine life mainly by', '["raising the pH of seawater", "dissolving fully into the water", "adding nutrients that feed fish", "forming a surface layer that blocks sunlight and reduces oxygen exchange"]', 3, 'The floating oil film blocks light and gas exchange; animals ingest oil when grooming.', '{"0": "Not the main effect.", "1": "Oil floats on water.", "2": "Oil is not a nutrient."}'),
  ('CHE-1234', 'Environmental chemistry', 'Effects', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 253 (§33.5)', 'Biomagnification means that persistent toxins such as mercury and pesticides', '["are diluted as they move up the food chain", "become more concentrated at each step up the food chain", "are broken down by top predators", "affect only plants"]', 1, 'Top predators, including humans, receive the highest doses.', '{"0": "They become more concentrated.", "2": "They are not broken down.", "3": "Animals are affected too."}'),
  ('CHE-1235', 'Environmental chemistry', 'Effects', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 253 (§33.5)', 'Water pollution can add to global warming because', '["it produces ozone", "polluted water absorbs CO₂ only", "organic matter decaying in oxygen-poor water releases methane", "it raises dissolved oxygen"]', 2, 'Anaerobic decomposition of algae and sewage releases methane, a potent greenhouse gas.', '{"0": "Not the stated link.", "1": "Not the stated link.", "3": "Pollution lowers DO."}'),
  ('CHE-1236', 'Environmental chemistry', 'Treatment', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 253 (§33.6)', 'The first stage of wastewater treatment removes large particles and settleable solids by', '["ion exchange", "reverse osmosis", "chlorination", "screening and sedimentation"]', 3, 'Screens catch large debris; sedimentation tanks let suspended solids settle by gravity.', '{"0": "Ion exchange softens water.", "1": "RO is for high-purity water.", "2": "Chlorination is disinfection."}'),
  ('CHE-1237', 'Environmental chemistry', 'Treatment', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 254 (§33.6 iii)', 'In advanced filtration, the material used to adsorb remaining impurities is', '["activated carbon", "aluminium sulfate", "sodium chloride", "calcium carbonate"]', 0, 'Graded sand and gravel trap fine particles; activated carbon is used for more advanced purification.', '{"1": "Alum is a coagulant.", "2": "Not used for filtration.", "3": "Not used for filtration."}'),
  ('CHE-1238', 'Environmental chemistry', 'Treatment', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 254 (§33.6 iv)', 'When chlorine or sodium hypochlorite is added to water, the species that kills microbes is', '["hypochlorous acid, HOCl", "hydrochloric acid only", "chloride ions", "sodium ions"]', 0, 'HOCl penetrates the cell walls of bacteria and viruses and disrupts their functions.', '{"1": "Not the disinfecting species named.", "2": "Chloride is not the disinfectant.", "3": "Na⁺ does not disinfect."}'),
  ('CHE-1239', 'Environmental chemistry', 'Treatment', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 254 (§33.6)', 'Reverse osmosis produces high-purity water by', '["forcing water under pressure through a semi-permeable membrane that holds back salts and microbes", "adding chlorine", "boiling and condensing", "adding alum"]', 0, 'RO is used for laboratory water and in high-salinity regions.', '{"1": "That is disinfection.", "2": "That is distillation.", "3": "That is coagulation."}'),
  ('CHE-1240', 'Environmental chemistry', 'Conservation', 'easy', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 255 (§33.7.2)', 'Which is an efficient water-saving technology in agriculture?', '["drip irrigation", "flood irrigation", "open-channel flooding", "using hosepipes"]', 0, 'Drip and sprinkler irrigation reduce wastage while improving yields.', '{"1": "Flood irrigation wastes water.", "2": "Wasteful.", "3": "Wasteful."}'),
  ('CHE-1241', 'Environmental chemistry', 'Conservation', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 255 (§33.7.2)', 'Greywater, which can be reused for toilet flushing or gardens, is', '["used water from laundry, dishwashing and bathing", "sewage from toilets", "industrial effluent", "rainwater only"]', 0, 'Reusing greywater conserves fresh water and reduces the load on sewage treatment.', '{"1": "Toilet waste is not greywater.", "2": "Not greywater.", "3": "Rainwater is harvested separately."}'),
  ('CHE-1242', 'Environmental chemistry', 'Regulations', 'moderate', 'Chemistry 12 (PECTAA, Punjab), Ch. 33 Water, p. 256 (Table 33.3)', 'Which law prohibits discharging pollutants or blocking water flow, with up to 3 months'' imprisonment and/or a Rs 500,000 fine?', '["Punjab Water Act, 2019", "Punjab Environmental Protection Act, 1997", "Punjab Irrigation, Drainage and Rivers Act, 2023", "Punjab Water and Sanitation Authority Act, 2025"]', 0, 'Table 33.3 lists these penalties under the Punjab Water Act, 2019.', '{"1": "Its fines go up to Rs 5 million.", "2": "No penalty is listed for this Act.", "3": "It sets up the authority in major cities."}')
) AS s
JOIN users u ON u.email = 'hozaiphaa@gmail.com';

